                { code: "CYCLE832", controllers: ["siemens"], description: "Siemens high-speed cycle" },
                { code: "G05 P2", controllers: ["makino"], description: "Makino SGI mode" },
                { code: "G08 P1", controllers: ["fanuc", "okuma"], description: "High precision mode" }
