        "180": 1.00,  // Straight - no reduction
        "170": 0.98,
        "160": 0.95,
        "150": 0.90,
        "140": 0.82,
        "135": 0.78,  // 45° direction change
        "130": 0.72,
        "120": 0.65,
        "110": 0.55,
        "100": 0.45,
