// Toggle Tool Selection
function toggleToolSelection(toolId) {
    const index = toolLibraryState.selectedTools.indexOf(toolId);
    if (index > -1) {
        toolLibraryState.selectedTools.splice(index, 1);
    } else {
        toolLibraryState.selectedTools.push(toolId);
    }
    // Update batch actions visibility
    const batchActions = document.getElementById('libBatchActions');
    if (batchActions) {
        batchActions.style.display = toolLibraryState.selectedTools.length > 0 ? 'block' : 'none';
        document.getElementById('libSelectedCount')?.textContent = toolLibraryState.selectedTools.length;
    }
    renderToolLibrary();
}
// Open Buy Modal for Tool
function openToolBuyModal(toolId) {
    const tool = toolLibraryState.allTools.find(t => t.id === toolId);
    if (!tool) return;

    openPrismBuyModal({
        name: tool.name || 'Cutting Tool',
        partNumber: tool.partNumber || tool.id,
        brand: tool.manufacturer || tool.brand || 'Various',
        category: tool.category || 'Cutting Tools',
        price: tool.price || null,
        type: 'cutting_tool',
        diameter: tool.diameter,
        flutes: tool.flutes,
        coating: tool.coating,
        unitSystem: tool.unitSystem
    });
}
// Clear Library Selection
function clearLibrarySelection() {
    toolLibraryState.selectedTools = [];
    document.getElementById('libBatchActions')?.style.display = 'none';
    renderToolLibrary();
}
// Quick Add Single Tool to Crib
function quickAddToToolCrib(toolId) {
    // Find tool in library
    let tool = null;
    for (const cat of ['milling', 'turning', 'drilling', 'threading', 'holders']) {
        tool = MASTER_TOOL_LIBRARY[cat]?.inch?.find(t => t.id === toolId) ||
               MASTER_TOOL_LIBRARY[cat]?.metric?.find(t => t.id === toolId);
        if (tool) break;
    }
    if (tool) {
        const cribTool = {
            id: `tool_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            type: tool.type || 'endmill',
            typeName: tool.typeName || 'End Mill',
            name: tool.name,
            displayName: `${tool.manufacturer || ''} ${tool.name}`.trim(),
            diameter: tool.diameter,
            diameterUnit: tool.unitSystem === 'inch' ? 'in' : 'mm',
            flutes: tool.flutes || 'N/A',
            material: tool.material || 'carbide',
            coating: tool.coating || 'TiAlN',
            brand: tool.manufacturer || 'Unknown',
            loc: tool.loc || null,
            locUnit: tool.unitSystem === 'inch' ? 'in' : 'mm',
            quantity: 1,
            partNumber: tool.partNumber || '',
            details: `${tool.coating || ''} ${tool.material || ''}`
        };
        MY_SHOP.addItem('cuttingTools', cribTool);
        MY_SHOP.showNotification(`Added ${tool.name} to Tool Crib`, 'success');
        updateToolCribDisplay();
    }
}
// Add Selected Tools to Tool Crib
function addSelectedToToolCrib() {
    toolLibraryState.selectedTools.forEach(toolId => {
        quickAddToToolCrib(toolId);
    });
    clearLibrarySelection();
}
