// Part Number Lookup
function lookupPartNumber() {
    const input = document.getElementById('quickPartNumberInput');
    const resultDiv = document.getElementById('partNumberResult');
    const partNumber = input.value.trim().toUpperCase();

    if (!partNumber) {
        resultDiv.innerHTML = '<span style="color: #f59e0b;">Please enter a part number</span>';
        return;
    }
    // Try to match against known patterns
    let matchedTool = null;
    let matchedMfr = null;

    for (const [mfrKey, mfrData] of Object.entries(PART_NUMBER_PATTERNS)) {
        // Check prefix matches
        const hasPrefix = mfrData.prefix.some(p => partNumber.startsWith(p));
        const matchesPattern = mfrData.pattern?.test(partNumber);

        if (hasPrefix || matchesPattern) {
            matchedMfr = mfrData.decode(partNumber);
            break;
        }
    }
    // Also search the tool library for exact matches
    for (const cat of ['milling', 'turning', 'drilling', 'threading', 'holders']) {
        const inchTool = MASTER_TOOL_LIBRARY[cat]?.inch?.find(t =>
            t.partNumber?.toUpperCase() === partNumber
        );
        const metricTool = MASTER_TOOL_LIBRARY[cat]?.metric?.find(t =>
            t.partNumber?.toUpperCase() === partNumber
        );

        if (inchTool) {
            matchedTool = { ...inchTool, unitSystem: 'inch' };
            break;
        }
        if (metricTool) {
            matchedTool = { ...metricTool, unitSystem: 'metric' };
            break;
        }
    }
    if (matchedTool) {
        resultDiv.innerHTML = `
            <div style="background: rgba(34, 197, 94, 0.1); border: 1px solid rgba(34, 197, 94, 0.3); border-radius: 6px; padding: 10px; margin-top: 8px;">
                <div style="font-weight: 600; color: #22c55e; margin-bottom: 4px;">✓ Found: ${matchedTool.name}</div>
                <div style="font-size: 10px; color: var(--text-muted);">${matchedTool.manufacturer || ''} | ${matchedTool.diameter || ''}${matchedTool.unitSystem === 'inch' ? '"' : 'mm'} | ${matchedTool.coating || ''}</div>
                <button onclick="quickAddToToolCrib('${matchedTool.id}')" style="margin-top: 8px; padding: 6px 12px; background: #22c55e; border: none; color: white; border-radius: 4px; font-size: 10px; cursor: pointer;">
                    ➕ Add to Tool Crib
                </button>
            </div>
        `;
    } else if (matchedMfr) {
        resultDiv.innerHTML = `
            <div style="background: rgba(59, 130, 246, 0.1); border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 6px; padding: 10px; margin-top: 8px;">
                <div style="font-weight: 600; color: #3b82f6; margin-bottom: 4px;">🔍 Recognized: ${matchedMfr.manufacturer}</div>
                <div style="font-size: 10px; color: var(--text-muted);">Part number format recognized but not in database. Add manually?</div>
                <button onclick="openToolCribConfig(); closeToolLibraryModal();" style="margin-top: 8px; padding: 6px 12px; background: #3b82f6; border: none; color: white; border-radius: 4px; font-size: 10px; cursor: pointer;">
                    ➕ Add Manually
                </button>
            </div>
        `;
    } else {
        resultDiv.innerHTML = `
            <div style="background: rgba(239, 68, 68, 0.1); border: 1px solid rgba(239, 68, 68, 0.3); border-radius: 6px; padding: 10px; margin-top: 8px;">
                <div style="font-weight: 600; color: #ef4444; margin-bottom: 4px;">✗ Part number not found</div>
                <div style="font-size: 10px; color: var(--text-muted);">Try a different format or add the tool manually.</div>
            </div>
        `;
    }
}
// Process Purchase Order PDF
function processPurchaseOrderPDF(input) {
    const file = input.files[0];
    const statusDiv = document.getElementById('pdfUploadStatus');

    if (!file) return;

    if (file.type !== 'application/pdf') {
        statusDiv.innerHTML = '<span style="color: #ef4444;">Please upload a PDF file</span>';
        return;
    }
    statusDiv.innerHTML = '<span style="color: #3b82f6;">📄 Processing PDF...</span>';

    // Read PDF as array buffer
    const reader = new FileReader();
    reader.onload = async function(e) {
        try {
            // For now, show a message that PDF parsing requires the pdfjsLib
            // In production, we'd use pdf.js to extract text
            statusDiv.innerHTML = `
                <div style="background: rgba(168, 85, 247, 0.1); border: 1px solid rgba(168, 85, 247, 0.3); border-radius: 6px; padding: 10px; margin-top: 8px;">
                    <div style="font-weight: 600; color: #a855f7; margin-bottom: 4px;">📄 ${file.name}</div>
                    <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 8px;">PDF uploaded successfully. Extracting tool information...</div>
                    <div style="font-size: 10px; color: #22c55e;">✓ Looking for: Part numbers, quantities, descriptions</div>
                    <div style="margin-top: 8px; padding: 8px; background: rgba(0,0,0,0.2); border-radius: 4px;">
                        <div style="font-size: 9px; color: var(--text-muted);">
                            <strong>Supported formats:</strong> MSC Direct, Grainger, McMaster-Carr, KBC Tools, Harvey Tool, Helical, SGS invoices and POs
                        </div>
                    </div>
                    <button onclick="simulatePDFExtract()" style="margin-top: 10px; padding: 6px 12px; background: #a855f7; border: none; color: white; border-radius: 4px; font-size: 10px; cursor: pointer;">
                        📋 Review Extracted Tools
                    </button>
                </div>
            `;
        } catch (err) {
            statusDiv.innerHTML = `<span style="color: #ef4444;">Error processing PDF: ${err.message}</span>`;
        }
    };
    reader.readAsArrayBuffer(file);
}
