    function showExpLevelTooltip(event, level) {
        const tooltip = document.getElementById('expLevelTooltip');
        if (!tooltip) return;

        // Check if EXP_LEVEL_TOOLTIPS is initialized
        if (!EXP_LEVEL_TOOLTIPS) return;

        const data = EXP_LEVEL_TOOLTIPS[level];
        if (!data) return;

        // Build hidden features section if any exist
        let hiddenSection = '';
        if (data.hiddenFeatures && data.hiddenFeatures.length > 0) {
            hiddenSection = `
                <div class="exp-tooltip-hidden">
                    <div class="exp-tooltip-hidden-title">🔒 Unlocked in higher modes:</div>
                    <div class="exp-tooltip-hidden-list">${data.hiddenFeatures.join(' • ')}</div>
                </div>
            `;
        }
        tooltip.innerHTML = `
            <div class="exp-tooltip-title" style="color: ${data.color};">
                <span style="font-size: 20px;">${data.icon}</span>
                <span>${data.title}</span>
            </div>
            <div class="exp-tooltip-desc">${data.description}</div>
            <ul class="exp-tooltip-features">
                ${data.features.map(f => `<li>${f}</li>`).join('')}
            </ul>
            ${hiddenSection}
        `;

        tooltip.style.borderColor = data.color;
        tooltip.style.display = 'block';

        // Position tooltip below the button container
        const container = event.target.closest('#experienceLevelToggle');
        if (container) {
            container.style.position = 'relative';
        }
    }
    function hideExpLevelTooltip() {
        const tooltip = document.getElementById('expLevelTooltip');
        if (tooltip) {
            tooltip.style.display = 'none';
        }
    }
    function setExperienceLevel(level) {
        currentExperienceLevel = level;
        localStorage.setItem('experienceLevel', level);

        // Hide tooltip when selecting
        if (typeof hideExpLevelTooltip === 'function') {
            hideExpLevelTooltip();
        }
        // Update toggle buttons (always do this regardless of config state)
        const buttons = ['beginnerModeBtn', 'journeymanModeBtn', 'masterModeBtn'];
        const colors = {
            beginner: '#22c55e',
            journeyman: '#f59e0b',
            master: '#ef4444'
        };
        buttons.forEach(btnId => {
            const btn = document.getElementById(btnId);
            if (!btn) return;

            const btnLevel = btnId.replace('ModeBtn', '');
            const isActive = btnLevel === level;
            const color = colors[btnLevel];

            btn.style.background = isActive ? color : 'transparent';
            btn.style.color = isActive ? '#000' : color;
        });

        // Check if EXPERIENCE_MODE_CONFIG is initialized for advanced features
        if (!EXPERIENCE_MODE_CONFIG) {
            (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('EXPERIENCE_MODE_CONFIG not yet initialized, will apply full config later...');
            // Show basic toast
            if (typeof showToast === 'function') {
                const toastMessages = {
                    beginner: '🌱 Beginner Mode selected',
                    journeyman: '🔧 Journeyman Mode selected',
                    master: '⚔️ Master Mode selected'
                };
                showToast(toastMessages[level] || `${level} Mode selected`, colors[level]);
            }
            return;
        }
        // Get configuration for this level
        const config = EXPERIENCE_MODE_CONFIG[level];
        if (!config) return;

        // APPLY MODE-SPECIFIC UI VISIBILITY

        // Machine Mode Buttons (EDM, Wire EDM)
        const edmBtn = document.getElementById('edmModeBtn');
        const wireEdmBtn = document.getElementById('wireEdmModeBtn');
        if (edmBtn) edmBtn.style.display = config.showEDMMode ? 'flex' : 'none';
        if (wireEdmBtn) wireEdmBtn.style.display = config.showWireEDMMode ? 'flex' : 'none';

        // Guided Workflow Panel
        const guidancePanel = document.getElementById('beginnerGuidancePanel');
        if (guidancePanel) {
            guidancePanel.style.display = config.showGuidedWorkflow ? 'block' : 'none';
        }
        // Master Tool Library Button
        const toolLibraryBtn = document.querySelector('[onclick*="openToolLibraryModal"]');
        if (toolLibraryBtn) {
            toolLibraryBtn.style.display = config.showMasterToolLibrary ? 'inline-flex' : 'none';
        }
        // Post Processor Panel
        const postPanel = document.getElementById('postProcessorPanel');
        if (postPanel) {
            postPanel.style.display = config.showPostProcessors ? 'block' : 'none';
        }
        // G-Code Export Section
        const gcodePanel = document.getElementById('gcodeExportPanel');
        if (gcodePanel) {
            gcodePanel.style.display = config.showGCodeExport ? 'block' : 'none';
        }
        // APPLY CALCULATION DISPLAY SETTINGS

        // MRR Display
        const mrrDisplay = document.getElementById('mrrResult');
        if (mrrDisplay) {
            mrrDisplay.parentElement.style.display = config.showMRR ? 'block' : 'none';
        }
        // Power Consumption Display
        const powerDisplay = document.getElementById('powerResult');
        if (powerDisplay) {
            powerDisplay.parentElement.style.display = config.showPowerConsumption ? 'block' : 'none';
        }
        // Torque Analysis
        const torqueDisplay = document.getElementById('torqueResult');
        if (torqueDisplay) {
            torqueDisplay.parentElement.style.display = config.showTorqueAnalysis ? 'block' : 'none';
        }
        // APPLY TOOLTIP BEHAVIOR

        // Add or remove tooltip behavior based on mode
        if (config.showTooltipsOnHover) {
            document.body.classList.add('tooltips-enabled');
            document.body.classList.remove('tooltips-disabled');
        } else {
            document.body.classList.remove('tooltips-enabled');
            document.body.classList.add('tooltips-disabled');
        }
        // APPLY PANEL STYLE

        document.body.classList.remove('panel-style-expanded', 'panel-style-standard', 'panel-style-compact');
        document.body.classList.add(`panel-style-${config.panelStyle}`);

        // Panel descriptions
        document.querySelectorAll('.panel-description').forEach(desc => {
            desc.style.display = config.showPanelDescriptions ? 'block' : 'none';
        });

        // BEGINNER MODE SPECIFIC

        if (level === 'beginner') {
            currentGuidanceStep = 1;
            updateGuidanceDisplay();
            highlightCurrentStep();
            addBeginnerTooltips();

            // Hide advanced result sections
            document.querySelectorAll('.advanced-calc-section').forEach(el => {
                el.style.display = 'none';
            });

            // Show beginner tips
            document.querySelectorAll('.beginner-tip').forEach(el => {
                el.style.display = 'block';
            });

        } else {
            removeAllHighlights();

            // Show advanced result sections for journeyman/master
            document.querySelectorAll('.advanced-calc-section').forEach(el => {
                el.style.display = config.showScientificCalcs ? 'block' : 'none';
            });

            // Hide beginner tips
            document.querySelectorAll('.beginner-tip').forEach(el => {
                el.style.display = 'none';
            });
        }
        // MASTER MODE SPECIFIC

        // Show/hide master mode options panel
        const masterOptionsPanel = document.getElementById('masterModeOptions');
        if (masterOptionsPanel) {
            masterOptionsPanel.style.display = level === 'master' ? 'block' : 'none';
        }
        if (level === 'master') {
            // Show physics panel
            const physicsPanel = document.getElementById('physicsConstantsPanel');
            if (physicsPanel) physicsPanel.style.display = 'block';

            // Show all advanced sections
            document.querySelectorAll('.expert-only').forEach(el => {
                el.style.display = 'block';
            });

            // Enable compact mode
            document.body.classList.add('compact-mode');

            // Load and apply saved master mode toggles
            loadMasterModeToggles();
            setTimeout(() => applyMasterModeToggles(), 50);

        } else {
            const physicsPanel = document.getElementById('physicsConstantsPanel');
            if (physicsPanel) physicsPanel.style.display = 'none';

            document.querySelectorAll('.expert-only').forEach(el => {
                el.style.display = 'none';
            });

            document.body.classList.remove('compact-mode');

            // Reset master mode toggle states
            resetMasterModeToggles();
            window.masterShowWarnings = false;
            window.masterShowTips = false;
        }
        // UPDATE MATERIAL FILTER (Beginner sees fewer materials)

        if (typeof filterMaterials === 'function') {
            // Store mode for filterMaterials to use
            window.currentExperienceModeConfig = config;
            filterMaterials();
        }
        // SHOW TOAST NOTIFICATION

        const toastMessages = {
            beginner: '🌱 Beginner Mode - Guided workflow enabled. Follow the highlighted steps!',
            journeyman: '🔧 Journeyman Mode - Full features with helpful tips. EDM & Wire EDM now available!',
            master: '⚔️ Master Mode - All features unlocked. Physics panel and expert tools enabled!'
        };
        showToast(toastMessages[level], colors[level]);

        // DISPATCH EVENT FOR OTHER COMPONENTS

        window.dispatchEvent(new CustomEvent('experienceLevelChanged', {
            detail: { level, config }
        }));

        console.log(`PRISM Experience Level: ${level.toUpperCase()}`, config);
    }
    // APPLY EXPERIENCE MODE ON PANEL/FEATURE INTERACTION

    function checkExperienceModeAccess(feature) {
        const config = EXPERIENCE_MODE_CONFIG[currentExperienceLevel];
        if (!config) return true;

        const featureMap = {
            'edm': config.showEDMMode,
            'wire_edm': config.showWireEDMMode,
            'troubleshooting': config.showTroubleshooting,
            'postprocessor': config.showPostProcessors,
            'toollibrary': config.showToolLibrary,
            'physics': config.showPhysicsPanel,
            'gcode': config.showGCodeExport
        };
        if (featureMap[feature] === false) {
            const upgradeMessages = {
                'edm': 'EDM mode is available in Journeyman and Master modes',
                'wire_edm': 'Wire EDM mode is available in Journeyman and Master modes',
                'troubleshooting': 'Alarm troubleshooting is available in Journeyman and Master modes',
                'postprocessor': 'Post processor tools are available in Journeyman and Master modes',
                'toollibrary': 'Master Tool Library is available in Journeyman and Master modes',
                'physics': 'Physics calculations panel is available in Master mode only',
                'gcode': 'G-code export is available in Journeyman and Master modes'
            };
            showToast(`🔒 ${upgradeMessages[feature] || 'This feature requires a higher experience level'}`, '#f59e0b');
            return false;
        }
        return true;
    }
    // MASTER MODE OPTIONAL TOGGLES
    // Allows expert users to optionally enable beginner/journeyman features

    // Store master mode toggle states
    // Master mode toggle states (declared at top of script)
    masterModeToggles = {
        tooltips: false,
        warnings: false,
        guided: false,
        tips: false
    };
    function toggleMasterOption(option, enabled) {
        if (currentExperienceLevel !== 'master') return;

        masterModeToggles[option] = enabled;
        localStorage.setItem('masterModeToggles', JSON.stringify(masterModeToggles));

        switch(option) {
            case 'tooltips':
                if (enabled) {
                    document.body.classList.remove('tooltips-disabled');
                    document.body.classList.add('tooltips-enabled');
                    showToast('💡 Tooltips enabled', '#ef4444');
                } else {
                    document.body.classList.remove('tooltips-enabled');
                    document.body.classList.add('tooltips-disabled');
                    showToast('💡 Tooltips disabled', '#666');
                }
                break;

            case 'warnings':
                window.masterShowWarnings = enabled;
                if (enabled) {
                    showToast('⚠️ Safety warnings enabled', '#ef4444');
                } else {
                    showToast('⚠️ Safety warnings disabled', '#666');
                }
                break;

            case 'guided':
                const guidancePanel = document.getElementById('beginnerGuidancePanel');
                if (guidancePanel) {
                    guidancePanel.style.display = enabled ? 'block' : 'none';
                    if (enabled) {
                        currentGuidanceStep = 1;
                        updateGuidanceDisplay();
                        highlightCurrentStep();
                        showToast('📋 Guided workflow enabled', '#ef4444');
                    } else {
                        removeAllHighlights();
                        showToast('📋 Guided workflow disabled', '#666');
                    }
                }
                break;

            case 'tips':
                window.masterShowTips = enabled;
                document.querySelectorAll('.optimization-tip, .contextual-tip').forEach(el => {
                    el.style.display = enabled ? 'block' : 'none';
                });
                if (enabled) {
                    showToast('🔔 Optimization tips enabled', '#ef4444');
                } else {
                    showToast('🔔 Optimization tips disabled', '#666');
                }
                break;
        }
        console.log(`Master Mode Toggle: ${option} = ${enabled}`);
    }
    function loadMasterModeToggles() {
        try {
            const saved = localStorage.getItem('masterModeToggles');
            if (saved) {
                masterModeToggles = JSON.parse(saved);
            }
        } catch (e) {
            console.warn('Could not load master mode toggles:', e);
        }
        // Update checkbox states
        const tooltipsToggle = document.getElementById('masterTooltipsToggle');
        const warningsToggle = document.getElementById('masterWarningsToggle');
        const guidedToggle = document.getElementById('masterGuidedToggle');
        const tipsToggle = document.getElementById('masterTipsToggle');

        if (tooltipsToggle) tooltipsToggle.checked = masterModeToggles.tooltips;
        if (warningsToggle) warningsToggle.checked = masterModeToggles.warnings;
        if (guidedToggle) guidedToggle.checked = masterModeToggles.guided;
        if (tipsToggle) tipsToggle.checked = masterModeToggles.tips;
    }
    function applyMasterModeToggles() {
        if (currentExperienceLevel !== 'master') return;

        // Apply each toggle state
        if (masterModeToggles.tooltips) {
            document.body.classList.remove('tooltips-disabled');
            document.body.classList.add('tooltips-enabled');
        }
        if (masterModeToggles.warnings) {
            window.masterShowWarnings = true;
        }
        if (masterModeToggles.guided) {
            const guidancePanel = document.getElementById('beginnerGuidancePanel');
            if (guidancePanel) {
                guidancePanel.style.display = 'block';
                currentGuidanceStep = 1;
                updateGuidanceDisplay();
                highlightCurrentStep();
            }
        }
        if (masterModeToggles.tips) {
            window.masterShowTips = true;
            document.querySelectorAll('.optimization-tip, .contextual-tip').forEach(el => {
                el.style.display = 'block';
            });
        }
    }
    function resetMasterModeToggles() {
        masterModeToggles = { tooltips: false, warnings: false, guided: false, tips: false };

        const tooltipsToggle = document.getElementById('masterTooltipsToggle');
        const warningsToggle = document.getElementById('masterWarningsToggle');
        const guidedToggle = document.getElementById('masterGuidedToggle');
        const tipsToggle = document.getElementById('masterTipsToggle');

        if (tooltipsToggle) tooltipsToggle.checked = false;
        if (warningsToggle) warningsToggle.checked = false;
        if (guidedToggle) guidedToggle.checked = false;
        if (tipsToggle) tipsToggle.checked = false;
    }
    function updateGuidanceDisplay() {
        const step = guidanceSteps[currentGuidanceStep];
        if (!step) return;

        // Update text
        const textEl = document.getElementById('guidanceText');
        if (textEl) {
            textEl.innerHTML = step.text;
        }
        // Update progress dots
        document.querySelectorAll('.guide-step').forEach(dot => {
            const dotStep = parseInt(dot.dataset.step);
            dot.classList.remove('active', 'completed');
            if (dotStep < currentGuidanceStep) {
                dot.classList.add('completed');
            } else if (dotStep === currentGuidanceStep) {
                dot.classList.add('active');
            }
        });
    }
    function highlightCurrentStep() {
        removeAllHighlights();

        const step = guidanceSteps[currentGuidanceStep];
        if (!step) return;

        // Find and highlight the target element
        let targetEl = document.getElementById(step.targetPanel);
        if (!targetEl) {
            // Try to find parent panel
            targetEl = document.querySelector(`[id*="${step.targetPanel}"]`);
        }
        if (targetEl) {
            targetEl.classList.add('guide-highlight');

            // Scroll to element if not visible
            setTimeout(() => {
                targetEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 100);
        }
    }
    function removeAllHighlights() {
        document.querySelectorAll('.guide-highlight').forEach(el => {
            el.classList.remove('guide-highlight');
        });
    }
    function advanceGuidanceStep() {
        if (currentExperienceLevel !== 'beginner') return;

        if (currentGuidanceStep < totalGuidanceSteps) {
            currentGuidanceStep++;
            updateGuidanceDisplay();
            highlightCurrentStep();
        } else {
            // All steps complete - show results highlight
            completeGuidance();
        }
    }
    function skipGuidanceStep() {
        advanceGuidanceStep();
    }
    function completeGuidance() {
        const guidancePanel = document.getElementById('beginnerGuidancePanel');
        if (guidancePanel) {
            guidancePanel.innerHTML = `
                <div style="display: flex; align-items: center; gap: 10px;">
                    <div style="font-size: 24px;">🎉</div>
                    <div style="flex: 1;">
                        <div style="font-size: 12px; font-weight: 700; color: #22c55e; margin-bottom: 4px;">Setup Complete!</div>
                        <div style="font-size: 11px; color: var(--text); line-height: 1.4;">
                            Your calculated results are highlighted below. Click on <strong>RPM</strong> or <strong>Feed Rate</strong> to copy individual values.
                        </div>
                    </div>
                </div>
            `;
        }
        // Highlight results panel
        const resultsPanel = document.getElementById('resultsDisplay');
        if (resultsPanel) {
            resultsPanel.classList.add('guide-highlight');
            resultsPanel.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        // Make results copyable
        enableResultsCopying();
    }
    function enableResultsCopying() {
        // Add click-to-copy functionality to RPM and Feed values
        const rpmEl = document.getElementById('calcRpm');
        const feedEl = document.getElementById('calcFeedRate');

        if (rpmEl) {
            rpmEl.style.cursor = 'pointer';
            rpmEl.title = 'Click to copy RPM';
            rpmEl.onclick = () => copyResultValue('RPM', rpmEl.textContent);
        }
        if (feedEl) {
            feedEl.style.cursor = 'pointer';
            feedEl.title = 'Click to copy Feed Rate';
            feedEl.onclick = () => copyResultValue('Feed Rate', feedEl.textContent);
        }
    }
    function copyResultValue(label, value) {
        // Extract just the number
        const numValue = value.replace(/,/g, '').trim();

        navigator.clipboard.writeText(numValue).then(() => {
            showToast(`✓ ${label} copied: ${numValue}`, '#22c55e');
        }).catch(() => {
            showToast(`Could not copy ${label}`, '#ef4444');
        });
    }
    function showToast(message, color = '#00ff88') {
        const toast = document.createElement('div');
        toast.style.cssText = `
            position: fixed; top: 70px; left: 50%; transform: translateX(-50%);
            background: ${color}; color: #000;
            padding: 12px 24px; border-radius: 8px; font-weight: 600; z-index: 10000;
            font-size: 12px; animation: slideDown 0.3s ease;
        `;
        toast.innerHTML = message;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 3000);

        // DEBUG: Check dropdown state 500ms AFTER setTier completes
        setTimeout(function() {
            const delayedMfrSelect = document.getElementById('machineManufacturer');
            console.log('[PRISM 500ms LATER] Dropdown innerHTML:', delayedMfrSelect?.innerHTML?.substring(0, 200));
            console.log('[PRISM 500ms LATER] Dropdown value:', delayedMfrSelect?.value);
        }, 500);
    }
    // Hook into existing functions to advance guidance
    function checkGuidanceProgress(event) {
        if (currentExperienceLevel !== 'beginner') return;

        if (event === 'machineSelected' && currentGuidanceStep === 1) {
            advanceGuidanceStep();
        } else if (event === 'materialSelected' && currentGuidanceStep === 3) {
            advanceGuidanceStep();
        } else if (event === 'toolpathSelected' && currentGuidanceStep === 4) {
            advanceGuidanceStep();
        } else if (event === 'holderSelected' && currentGuidanceStep === 5) {
            advanceGuidanceStep();
        } else if (event === 'toolConfigured' && currentGuidanceStep === 6) {
            completeGuidance();
        }
    }
    // Add hover tooltips for beginner mode
    function addBeginnerTooltips() {
        if (currentExperienceLevel !== 'beginner') return;

        const tooltipData = {
            'machineManufacturer': 'The manufacturer of your CNC machine. Different manufacturers have different spindle characteristics.',
            'machineType': 'The category of machine - VMC (Vertical), HMC (Horizontal), etc. This affects rigidity and cooling options.',
            'machineSelect': 'Your specific machine model. This loads the exact spindle specs, max RPM, and torque curve.',
            'spindleSelect': 'If your machine has multiple spindle options, select the one you have installed.',
            'material': 'The material you\'re cutting. This dramatically affects speeds and feeds.',
            'diameter': 'The cutting tool diameter. Larger tools can handle more aggressive feeds.',
            'flutes': 'Number of cutting edges. More flutes = higher feed rates but less chip room.',
            'doc': 'Depth of Cut - how deep the tool cuts into the material per pass.',
            'woc': 'Width of Cut (Radial) - how much of the tool diameter is engaged.'
        };
        Object.entries(tooltipData).forEach(([id, text]) => {
            const el = document.getElementById(id);
            if (el) {
                el.addEventListener('mouseenter', (e) => showBeginnerTooltip(e, text));
                el.addEventListener('mouseleave', hideBeginnerTooltip);
            }
        });
    }
    let activeTooltip = null;

    function showBeginnerTooltip(e, text) {
        hideBeginnerTooltip();

        const tooltip = document.createElement('div');
        tooltip.className = 'guide-tooltip';
        tooltip.innerHTML = text;
        tooltip.style.left = `${e.target.offsetLeft}px`;
        tooltip.style.top = `${e.target.offsetTop + e.target.offsetHeight + 8}px`;

        e.target.parentElement.style.position = 'relative';
        e.target.parentElement.appendChild(tooltip);
        activeTooltip = tooltip;
    }
    function hideBeginnerTooltip() {
        if (activeTooltip) {
            activeTooltip.remove();
            activeTooltip = null;
        }
    }
    // Expose experience level functions to global scope
    window.setExperienceLevel = setExperienceLevel;
    window.checkExperienceModeAccess = checkExperienceModeAccess;
    window.toggleMasterOption = toggleMasterOption;
    window.loadMasterModeToggles = loadMasterModeToggles;
    window.applyMasterModeToggles = applyMasterModeToggles;
    window.EXPERIENCE_MODE_CONFIG = EXPERIENCE_MODE_CONFIG;
    window.showExpLevelTooltip = showExpLevelTooltip;
    window.hideExpLevelTooltip = hideExpLevelTooltip;
    window.showToast = showToast;
    window.advanceGuidanceStep = advanceGuidanceStep;
    window.checkGuidanceProgress = checkGuidanceProgress;

    // INITIALIZE EXPERIENCE LEVEL ON PAGE LOAD
    document.addEventListener('DOMContentLoaded', function() {
        // Get saved experience level or default to beginner
        const savedLevel = localStorage.getItem('experienceLevel') || 'beginner';

        // Wait for configurations to be ready before initializing
        function initWhenReady() {
            if (EXPERIENCE_MODE_CONFIG && EXP_LEVEL_TOOLTIPS && TIERS) {
                setExperienceLevel(savedLevel);
                (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log(`PRISM Experience Level initialized: ${savedLevel.toUpperCase()}`);
            } else {
                // Try again in 50ms
                setTimeout(initWhenReady, 50);
            }
        }
        // Start checking after a small delay
        setTimeout(initWhenReady, 100);
    });

    // Update tier badge in header and toggle buttons
    function updateTierDisplay() {
        if (!TIERS) return; // Not initialized yet
        const tier = TIERS[currentTier];
        if (!tier) return;

        // Tier configuration for UI - NEW 4-TIER SYSTEM
        const tierConfig = {
            tier1: {
                icon: '📐',
                name: 'Tier 1',
                price: '$29/month',
                color: '#6b7280',
                bgColor: 'rgba(107, 114, 128, 0.08)',
                features: ['✓ Basic RPM/Feed', '✓ Generic Machines', '✓ 50 Materials', '✓ 25 Calc/Day']
            },
            tier2: {
                icon: '🔧',
                name: 'Tier 2',
                price: '$79/month',
                color: '#3b82f6',
                bgColor: 'rgba(59, 130, 246, 0.08)',
                features: ['✓ Machine Database', '✓ Brand Tooling', '✓ 200 Materials', '✓ MRR/Power Calc']
            },
            tier3: {
                icon: '⚡',
                name: 'Tier 3',
                price: '$149/month',
                color: '#a855f7',
                bgColor: 'rgba(168, 85, 247, 0.08)',
                features: ['✓ Full Features', '✓ Brand Holders', '✓ Surface Finish', '✓ Full Quoting', '✓ CAM Advisor']
            },
            tier4: {
                icon: '👑',
                name: 'Tier 4',
                price: '$299/month',
                color: '#f59e0b',
                bgColor: 'rgba(245, 158, 11, 0.08)',
                features: ['✓ Everything', '✓ CAD Recognition', '✓ Print AI', '✓ API Access', '✓ Multi-User']
            }
        };
        const config = tierConfig[currentTier] || tierConfig.tier1;

        // Update header badge
        const badge = document.getElementById('tierBadge');
        const badgeNameEl = document.getElementById('tierBadgeName');
        const upgrade = document.getElementById('tierUpgrade');

        if (badge) {
            if (badgeNameEl) badgeNameEl.textContent = 'Subscriptions';  // Always show 'Subscriptions'
            badge.className = `tier-badge ${tier.badgeClass}`;
        }
        if (upgrade) {
            if (currentTier === 'tier4') {
                upgrade.style.display = 'none';
            } else {
                upgrade.style.display = 'inline';
                upgrade.style.color = currentTier === 'tier1' ? 'var(--pro-color)' : 'var(--shop-color)';
            }
        }
        // Old tier toggle buttons removed - now using header tier selector only
        // The 4-tier system uses headerTier1Btn, headerTier2Btn, headerTier3Btn, headerTier4Btn

        // Update HEADER tier toggle buttons - NEW 4-TIER SYSTEM
        const headerTier1Btn = document.getElementById('headerTier1Btn');
        const headerTier2Btn = document.getElementById('headerTier2Btn');
        const headerTier3Btn = document.getElementById('headerTier3Btn');
        const headerTier4Btn = document.getElementById('headerTier4Btn');

        [headerTier1Btn, headerTier2Btn, headerTier3Btn, headerTier4Btn].forEach(btn => {
            if (btn) {
                const btnTier = btn.dataset.tier;
                const isActive = btnTier === currentTier;
                const tierColors = {
                    essentials: '#6b7280',
                    standard: '#3b82f6',
                    professional: '#a855f7',
                    enterprise: '#f59e0b'
                };
                btn.style.background = isActive ? tierColors[btnTier] : 'transparent';
                btn.style.color = isActive ? '#fff' : tierColors[btnTier];
            }
        });

        // Update tier description panel
        const tierDesc = document.getElementById('tierDescription');
        const tierIcon = document.getElementById('tierIcon');
        const tierName = document.getElementById('tierName');
        const tierPrice = document.getElementById('tierPrice');
        const tierFeatures = document.getElementById('tierFeatures');

        if (tierDesc) {
            tierDesc.style.background = config.bgColor;
        }
        if (tierIcon) {
            tierIcon.textContent = config.icon;
        }
        if (tierName) {
            tierName.textContent = config.name;
            tierName.style.color = config.color;
        }
        if (tierPrice) {
            tierPrice.textContent = config.price;
            tierPrice.style.color = config.color;
        }
        if (tierFeatures) {
            tierFeatures.innerHTML = config.features.map(f => `<span>${f}</span>`).join('');
        }
        // Update My Machines section visibility (only for pro and shop)
        const myMachinesSection = document.getElementById('myMachinesSection');
        if (myMachinesSection) {
            const savedMachines = JSON.parse(localStorage.getItem('myMachines') || '[]');
            const canSaveMachines = TIERS[currentTier].myMachinesLimit > 0;
            myMachinesSection.style.display = (canSaveMachines && savedMachines.length > 0) ? 'block' : 'none';
        }
    }
    // Apply tier restrictions to UI elements
    function applyTierRestrictions() {
        if (!TIERS) return; // Not initialized yet
        const tier = TIERS[currentTier];
        if (!tier) return;

        // === PRO BADGES VISIBILITY ===
        const proBadges = document.querySelectorAll('.pro-badge');
        proBadges.forEach(badge => {
            badge.style.display = (currentTier === 'tier1') ? 'inline' : 'none';
        });

        // === RESULT ITEMS STYLING ===
        const mrrItem = document.getElementById('mrrResultItem');
        const powerItem = document.getElementById('powerResultItem');
        const ctfItem = document.getElementById('ctfSpecItem');

        if (mrrItem) mrrItem.style.opacity = hasFeature('mrrCalc') ? '1' : '0.6';
        if (powerItem) powerItem.style.opacity = hasFeature('powerCalc') ? '1' : '0.6';
        if (ctfItem) ctfItem.style.opacity = hasFeature('chipThinning') ? '1' : '0.6';

        // === URL SHARING BUTTON ===
        const shareBtn = document.querySelector('[onclick*="shareLink"]');
        if (shareBtn) {
            shareBtn.style.opacity = hasFeature('urlSharing') ? '1' : '0.6';
            shareBtn.title = hasFeature('urlSharing') ? 'Copy shareable link' : 'Pro feature - Click to upgrade';
        }
        // === G-CODE BUTTON ===
        const gcodeBtn = document.getElementById('gcodeBtn');
        if (gcodeBtn) {
            gcodeBtn.style.opacity = hasFeature('gcode') ? '1' : '0.6';
        }
        // === HEAT TREATMENT ===
        const htSection = document.getElementById('heatTreatSection');
        if (htSection) {
            if (!hasFeature('heatTreat')) {
                htSection.classList.add('feature-locked');
                if (!htSection.querySelector('.lock-overlay')) {
                    htSection.innerHTML += createLockOverlay('heatTreat');
                }
            } else {
                htSection.classList.remove('feature-locked');
                const overlay = htSection.querySelector('.lock-overlay');
                if (overlay) overlay.remove();
            }
        }
        // === CHIP THINNING / HSM / FINISHING CHECKBOXES ===
        const checkboxFeatures = {
            'chipThinning': 'chipThinning',
            'hsmMode': 'hsmMode',
            'finishing': 'finishing'
        };
        for (const [elementId, feature] of Object.entries(checkboxFeatures)) {
            const checkbox = document.getElementById(elementId);
            if (checkbox) {
                const row = checkbox.closest('.checkbox-row') || checkbox.parentElement;
                if (!hasFeature(feature)) {
                    checkbox.disabled = true;
                    checkbox.checked = false;
                    if (row) {
                        row.style.opacity = '0.5';
                        row.title = `${TIERS[getRequiredTier(feature)].name} feature - Click to upgrade`;
                        row.onclick = (e) => { e.preventDefault(); showPricing(); };
                    }
                } else {
                    checkbox.disabled = false;
                    if (row) {
                        row.style.opacity = '1';
                        row.title = '';
                        row.onclick = null;
                    }
                }
            }
        }
        // === CAM TOOLPATH ADVISOR ===
        const camPanel = document.getElementById('camAdvisorPanel');

        // Hide ENTERPRISE badge when user is on Enterprise tier
        const shopBadges = document.querySelectorAll('.shop-badge');
        shopBadges.forEach(badge => {
            badge.style.display = (currentTier === 'tier4') ? 'none' : 'inline';
        });
        if (camPanel) {
            if (!hasFeature('camAdvisor')) {
                camPanel.classList.add('feature-locked');
                if (!camPanel.querySelector('.lock-overlay')) {
                    const overlay = document.createElement('div');
                    overlay.className = 'lock-overlay';
                    overlay.innerHTML = `
                        <div class="lock-icon">🔒</div>
                        <div class="lock-text">CAM Tool Path / Machining Cycle requires Professional plan</div>
                        <button class="upgrade-btn shop-btn" onclick="showPricing()">Upgrade to Professional</button>
                    `;
                    camPanel.style.position = 'relative';
                    camPanel.appendChild(overlay);
                }
            } else {
                camPanel.classList.remove('feature-locked');
                const overlay = camPanel.querySelector('.lock-overlay');
                if (overlay) overlay.remove();
            }
        }
        // === MOTION CONTROL FEATURES ===
        const motionSection = document.querySelector('[id*="motionControl"]')?.closest('.form-group');
        if (motionSection && !hasFeature('motionControl')) {
            // Add pro badge indicator
        }
        // === TOLERANCE MODES ===
        const toleranceSection = document.querySelector('[id*="toleranceMode"]')?.closest('.form-group');
        // Similar handling

        // === URL SHARING ===
        // Handled in shareLink function

        // === G-CODE (alternate selector) ===
        const gcodeBtnAlt = document.querySelector('[onclick*="copyGcode"]');
        if (gcodeBtnAlt) {
            if (!hasFeature('gcode')) {
                gcodeBtnAlt.disabled = true;
                gcodeBtnAlt.style.opacity = '0.5';
                gcodeBtnAlt.title = 'Pro feature';
                gcodeBtnAlt.onclick = (e) => { e.preventDefault(); showPricing(); };
            } else {
                gcodeBtnAlt.disabled = false;
                gcodeBtnAlt.style.opacity = '1';
                gcodeBtnAlt.title = '';
            }
        }
        // === WORKHOLDING & STABILITY PANEL ===
        const workholdingPanel = document.getElementById('workholdingPanel');
        const workholdingBadge = document.getElementById('workholdingTierBadge');

        if (workholdingBadge) {
            workholdingBadge.style.display = (currentTier === 'tier4') ? 'none' : 'inline';
        }
        if (workholdingPanel) {
            if (!hasFeature('workholding')) {
                workholdingPanel.classList.add('feature-locked');
                if (!workholdingPanel.querySelector('.lock-overlay')) {
                    const overlay = document.createElement('div');
                    overlay.className = 'lock-overlay';
                    overlay.innerHTML = `
                        <div class="lock-icon">🔒</div>
                        <div class="lock-text">Workholding & Stability requires Professional plan</div>
                        <button class="upgrade-btn shop-btn" onclick="showPricing()">Upgrade to Professional</button>
                    `;
                    workholdingPanel.style.position = 'relative';
                    workholdingPanel.appendChild(overlay);
                }
            } else {
                workholdingPanel.classList.remove('feature-locked');
                const overlay = workholdingPanel.querySelector('.lock-overlay');
                if (overlay) overlay.remove();
            }
        }
        // Recalculate to update displayed values
        if (typeof calculate === 'function') {
            calculate();
        }
    }
    // Create lock overlay HTML
    function createLockOverlay(feature) {
        const requiredTier = getRequiredTier(feature);
        const tierInfo = TIERS[requiredTier];
        const btnClass = requiredTier === 'shop' ? 'shop-btn' : '';

        return `
            <div class="lock-overlay">
                <div class="lock-icon">🔒</div>
                <div class="lock-text">${tierInfo.name} feature</div>
                <button class="upgrade-btn ${btnClass}" onclick="showPricing()">Upgrade to ${tierInfo.name}</button>
            </div>
        `;
    }
    // Check tier before performing action
    function requireTier(feature, callback) {
        if (hasFeature(feature)) {
            callback();
        } else {
            showPricing();
        }
    }
    // Initialize tier system
    function initTierSystem() {
        // Wait for TIERS to be initialized
        if (!TIERS) {
            (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('TIERS not yet initialized, deferring initTierSystem...');
            setTimeout(initTierSystem, 100);
            return;
        }
        // Set calculatorMode based on tier
        window.calculatorMode = (currentTier === 'tier1') ? 'easy' : 'pro';

        updateTierDisplay();
        applyTierRestrictions();
        applyCalculatorMode();
    }
