    // DRILL SELECTION HELPER FUNCTIONS

    function findDrillBySize(targetSize, tolerance = 0.001) {
        const results = [];
        const target = parseFloat(targetSize);

        // Search fractional sizes
        DRILL_CATALOG.sizes.fractional.forEach(drill => {
            if (Math.abs(drill.decimal - target) <= tolerance) {
                results.push({ ...drill, type: 'fractional' });
            }
        });

        // Search wire gauge sizes
        DRILL_CATALOG.sizes.wire.forEach(drill => {
            if (Math.abs(drill.decimal - target) <= tolerance) {
                results.push({ ...drill, type: 'wire' });
            }
        });

        // Search letter sizes
        DRILL_CATALOG.sizes.letter.forEach(drill => {
            if (Math.abs(drill.decimal - target) <= tolerance) {
                results.push({ ...drill, type: 'letter' });
            }
        });

        // Search metric sizes
        DRILL_CATALOG.sizes.metric.forEach(drill => {
            if (Math.abs(drill.decimal - target) <= tolerance) {
                results.push({ ...drill, type: 'metric' });
            }
        });

        return results.sort((a, b) => Math.abs(a.decimal - target) - Math.abs(b.decimal - target));
    }
    function getTapDrill(tapSize, threadSystem = 'unc') {
        const chart = DRILL_CATALOG.tapDrillCharts[threadSystem];
        if (!chart) return null;

        return chart.find(entry =>
            entry.tap.toLowerCase() === tapSize.toLowerCase() ||
            entry.tap.toLowerCase().includes(tapSize.toLowerCase())
        );
    }
    function recommendDrillForMaterial(material, holeDepth, holeDiameter, requirements = {}) {
        const recommendations = [];

        // Determine drill material based on workpiece material
        let drillMaterial = 'hss';
        let coating = 'uncoated';

        if (material.includes('stainless') || material.includes('titanium')) {
            drillMaterial = 'cobalt_m42';
            coating = 'altin';
        } else if (material.includes('hardened') || material.includes('inconel')) {
            drillMaterial = 'carbide';
            coating = 'altin';
        } else if (material.includes('aluminum')) {
            drillMaterial = 'hss';
            coating = 'zrn';
        } else if (material.includes('steel')) {
            drillMaterial = 'cobalt_m35';
            coating = 'tin';
        } else if (material.includes('cast_iron')) {
            drillMaterial = 'hss';
            coating = 'ticn';
        }
        // Determine drill type based on hole depth
        let drillType = 'jobber';
        const ldRatio = holeDepth / holeDiameter;

        if (ldRatio <= 5) {
            drillType = 'stub';
        } else if (ldRatio <= 10) {
            drillType = 'jobber';
        } else if (ldRatio <= 15) {
            drillType = 'taper_length';
        } else {
            drillType = 'parabolic';
        }
        // Add coolant-through recommendation for deep holes
        if (ldRatio > 8 && requirements.coolantThrough !== false) {
            recommendations.push({
                type: 'coolant_fed',
                material: 'carbide',
                coating: 'tialn',
                reason: `Deep hole (${ldRatio.toFixed(1)}x diameter) - coolant-through recommended`
            });
        }
        recommendations.push({
            type: drillType,
            material: drillMaterial,
            coating: coating,
            reason: `${material} with ${ldRatio.toFixed(1)}x L/D ratio`
        });

        return recommendations;
    }
    function calculateDrillPointLength(diameter, pointAngle = 135) {
        // Point length = (diameter / 2) / tan(point angle / 2)
        const angleRad = (pointAngle / 2) * (Math.PI / 180);
        return (diameter / 2) / Math.tan(angleRad);
    }
    function calculateMinimumHoleDepth(diameter, pointAngle = 135) {
        return calculateDrillPointLength(diameter, pointAngle);
    }
