    // Build complete searchable drill catalog
    function buildDrillCatalog() {
        const catalog = [];

        // Add McMaster products
        if (typeof DRILL_CATALOG !== 'undefined' && DRILL_CATALOG.mcmaster) {
            Object.entries(DRILL_CATALOG.mcmaster).forEach(([categoryKey, category]) => {
                if (category.products) {
                    category.products.forEach(product => {
                        catalog.push({
                            ...product,
                            brand: 'mcmaster',
                            brandName: 'McMaster-Carr',
                            category: categoryKey,
                            material: category.material || 'hss',
                            coating: category.coating || 'uncoated',
                            type: category.type || 'jobber',
                            point: category.point || 'split_135',
                            coolantThrough: category.coolantThrough || false,
                            source: 'mcmaster'
                        });
                    });
                }
            });
        }
        // Add Guhring products
        if (typeof DRILL_CATALOG !== 'undefined' && DRILL_CATALOG.guhring) {
            Object.entries(DRILL_CATALOG.guhring).forEach(([seriesKey, series]) => {
                if (series.products) {
                    series.products.forEach(product => {
                        catalog.push({
                            ...product,
                            brand: 'guhring',
                            brandName: 'Guhring',
                            series: series.series,
                            category: seriesKey,
                            material: series.material || 'carbide',
                            coating: series.coating || 'tialn',
                            type: series.coolantThrough ? 'coolant_fed' : 'jobber',
                            point: 'helical_140',
                            coolantThrough: series.coolantThrough || false,
                            source: 'guhring'
                        });
                    });
                }
            });
        }
        // Add OSG products
        if (typeof DRILL_CATALOG !== 'undefined' && DRILL_CATALOG.osg) {
            Object.entries(DRILL_CATALOG.osg).forEach(([seriesKey, series]) => {
                if (series.products) {
                    series.products.forEach(product => {
                        catalog.push({
                            ...product,
                            brand: 'osg',
                            brandName: 'OSG',
                            series: series.series,
                            category: seriesKey,
                            material: series.material || 'carbide',
                            coating: series.coating || 'tialn',
                            type: series.coolantThrough ? 'coolant_fed' : 'jobber',
                            point: 'helical_140',
                            coolantThrough: series.coolantThrough || false,
                            source: 'osg'
                        });
                    });
                }
            });
        }
        // Add Kennametal products
        if (typeof DRILL_CATALOG !== 'undefined' && DRILL_CATALOG.kennametal) {
            Object.entries(DRILL_CATALOG.kennametal).forEach(([seriesKey, series]) => {
                if (series.products) {
                    series.products.forEach(product => {
                        catalog.push({
                            ...product,
                            brand: 'kennametal',
                            brandName: 'Kennametal',
                            series: series.series,
                            category: seriesKey,
                            material: series.material || 'carbide',
                            coating: series.coating || 'altin',
                            type: series.coolantThrough ? 'coolant_fed' : 'jobber',
                            point: 'helical_140',
                            coolantThrough: series.coolantThrough || false,
                            source: 'kennametal'
                        });
                    });
                }
            });
        }
        // Add Sandvik products
        if (typeof DRILL_CATALOG !== 'undefined' && DRILL_CATALOG.sandvik) {
            Object.entries(DRILL_CATALOG.sandvik).forEach(([seriesKey, series]) => {
                if (series.products) {
                    series.products.forEach(product => {
                        catalog.push({
                            ...product,
                            brand: 'sandvik',
                            brandName: 'Sandvik Coromant',
                            series: series.series,
                            category: seriesKey,
                            material: series.material || 'carbide_ultrafine',
                            coating: series.coating || 'multilayer',
                            type: series.coolantThrough ? 'coolant_fed' : 'jobber',
                            point: 'helical_140',
                            coolantThrough: series.coolantThrough || false,
                            source: 'sandvik'
                        });
                    });
                }
            });
        }
        // Add YG-1 products
        if (typeof DRILL_CATALOG !== 'undefined' && DRILL_CATALOG.yg1) {
            Object.entries(DRILL_CATALOG.yg1).forEach(([seriesKey, series]) => {
                if (series.products) {
                    series.products.forEach(product => {
                        catalog.push({
                            ...product,
                            brand: 'yg1',
                            brandName: 'YG-1',
                            series: series.series,
                            category: seriesKey,
                            material: series.material || 'carbide',
                            coating: series.coating || 'tialn',
                            type: series.coolantThrough ? 'coolant_fed' : 'jobber',
                            point: 'split_135',
                            coolantThrough: series.coolantThrough || false,
                            source: 'yg1'
                        });
                    });
                }
            });
        }
        // Add Precision Twist Drill products
        if (typeof DRILL_CATALOG !== 'undefined' && DRILL_CATALOG.precision_twist) {
            Object.entries(DRILL_CATALOG.precision_twist).forEach(([seriesKey, series]) => {
                if (series.products) {
                    series.products.forEach(product => {
                        catalog.push({
                            ...product,
                            brand: 'precision_twist',
                            brandName: 'Precision Twist Drill',
                            series: series.series,
                            category: seriesKey,
                            material: series.material || 'hss',
                            coating: series.coating || 'uncoated',
                            type: 'jobber',
                            point: 'split_135',
                            coolantThrough: false,
                            madeInUSA: series.madeInUSA || false,
                            source: 'precision_twist'
                        });
                    });
                }
            });
        }
        // Add center drills
        if (typeof DRILL_CATALOG !== 'undefined' && DRILL_CATALOG.centerDrills) {
            Object.entries(DRILL_CATALOG.centerDrills).forEach(([typeKey, type]) => {
                if (type.products) {
                    type.products.forEach(product => {
                        catalog.push({
                            ...product,
                            partNo: product.partNo,
                            brand: 'mcmaster',
                            brandName: 'McMaster-Carr',
                            category: 'center_drill',
                            material: type.material || 'hss',
                            coating: 'uncoated',
                            type: 'center_drill',
                            point: typeKey === 'typeB' ? '120' : '60',
                            decimal: product.drillDia,
                            source: 'mcmaster'
                        });
                    });
                }
            });
        }
        // Add spot drills
        if (typeof DRILL_CATALOG !== 'undefined' && DRILL_CATALOG.spotDrills) {
            Object.entries(DRILL_CATALOG.spotDrills).forEach(([typeKey, type]) => {
                if (type.products) {
                    type.products.forEach(product => {
                        catalog.push({
                            ...product,
                            partNo: product.partNo,
                            brand: 'mcmaster',
                            brandName: 'McMaster-Carr',
                            category: 'spot_drill',
                            material: type.material || 'hss',
                            coating: type.coating || 'uncoated',
                            type: 'spot_drill',
                            point: String(type.angle),
                            source: 'mcmaster'
                        });
                    });
                }
            });
        }
        return catalog;
    }
    // Filter drills based on selected criteria
    function filterDrills() {
        const materialFilter = document.getElementById('drillMaterialFilter')?.value || 'all';
        const coatingFilter = document.getElementById('drillCoatingFilter')?.value || 'all';
        const typeFilter = document.getElementById('drillTypeFilter')?.value || 'all';
        const pointFilter = document.getElementById('drillPointFilter')?.value || 'all';
        const brandFilter = document.getElementById('drillBrandFilter')?.value || 'all';
        const sizeFilter = document.getElementById('drillSizeFilter')?.value || 'all';

        const catalog = buildDrillCatalog();

        filteredDrills = catalog.filter(drill => {
            // Material filter
            if (materialFilter !== 'all' && drill.material !== materialFilter) return false;

            // Coating filter
            if (coatingFilter !== 'all' && drill.coating !== coatingFilter) return false;

            // Type filter
            if (typeFilter !== 'all' && drill.type !== typeFilter) return false;

            // Point filter
            if (pointFilter !== 'all') {
                const drillPoint = drill.point?.replace('split_', '').replace('helical_', '').replace('conventional_', '');
                if (drillPoint !== pointFilter) return false;
            }
            // Brand filter
            if (brandFilter !== 'all' && drill.brand !== brandFilter) return false;

            // Size filter
            if (sizeFilter !== 'all') {
                const targetSize = parseFloat(sizeFilter);
                if (Math.abs(drill.decimal - targetSize) > 0.01) return false;
            }
            return true;
        });

        renderDrillResults();
    }
    // Search drills by text
    function searchDrills() {
        const searchTerm = document.getElementById('drillSearchInput')?.value?.toLowerCase() || '';

        if (searchTerm.length < 2) {
            filterDrills();
            return;
        }
        const catalog = buildDrillCatalog();

        filteredDrills = catalog.filter(drill => {
            const searchFields = [
                drill.partNo?.toLowerCase(),
                drill.size?.toLowerCase(),
                drill.brandName?.toLowerCase(),
                drill.series?.toLowerCase(),
                drill.material?.toLowerCase(),
                drill.coating?.toLowerCase()
            ].filter(Boolean).join(' ');

            return searchFields.includes(searchTerm);
        });

        renderDrillResults();
    }
    // Render drill results
    function renderDrillResults() {
        const container = document.getElementById('drillResultsContainer');
        const countEl = document.getElementById('drillResultsCount');

        if (!container) return;

        countEl.textContent = filteredDrills.length;

        if (filteredDrills.length === 0) {
            container.innerHTML = `
                <div style="padding: 30px; text-align: center; color: var(--text-muted);">
                    <div style="font-size: 32px; margin-bottom: 10px;">🔍</div>
                    <div style="font-size: 12px; margin-bottom: 4px;">No drills found</div>
                    <div style="font-size: 10px;">Try adjusting your filters or search term</div>
                </div>
            `;
            return;
        }
        // Limit to 50 results for performance
        const displayDrills = filteredDrills.slice(0, 50);

        container.innerHTML = displayDrills.map((drill, index) => {
            const materialClass = drill.material?.includes('carbide') ? 'carbide' :
                                  drill.material?.includes('cobalt') ? 'cobalt' : 'hss';
            const materialIcon = drill.material?.includes('carbide') ? '💎' :
                                 drill.material?.includes('cobalt') ? '⭐' : '🔩';
            const priceStr = drill.price ? `$${drill.price.toFixed(2)}` : 'Quote';

            return `
                <div class="drill-result-item ${selectedDrill?.partNo === drill.partNo ? 'selected' : ''}"
                     onclick="selectDrillFromList(${index})">
                    <div class="drill-icon ${materialClass}">${materialIcon}</div>
                    <div class="drill-info">
                        <div class="drill-name">${drill.brandName} ${drill.series || ''} ${drill.size}</div>
                        <div class="drill-specs">
                            ${drill.material?.replace('_', ' ').toUpperCase()} • ${drill.coating?.replace('_', ' ').toUpperCase()} •
                            ${drill.fluteLen || drill.drillLen || '?'}" FL • ${drill.oal || '?'}" OAL
                        </div>
                        <div class="drill-part-no">${drill.partNo}</div>
                    </div>
                    <div class="drill-price">${priceStr}</div>
                    <button class="drill-buy-btn" onclick="event.stopPropagation(); quickBuyDrill(${index})">Buy</button>
                </div>
            `;
        }).join('');

        if (filteredDrills.length > 50) {
            container.innerHTML += `
                <div style="padding: 10px; text-align: center; font-size: 10px; color: var(--text-muted);">
                    Showing 50 of ${filteredDrills.length} results. Refine filters to see more.
                </div>
            `;
        }
    }
    // Select drill from list
    function selectDrillFromList(index) {
        selectedDrill = filteredDrills[index];
        renderDrillResults();
        updateSelectedDrillDisplay();
        calculateDrillParameters();

        // Show buy section when drill is selected
        const buySection = document.getElementById('twistDrillBuySection');
        if (buySection) buySection.style.display = 'flex';
    }
    // Update selected drill display
    function updateSelectedDrillDisplay() {
        const display = document.getElementById('selectedDrillDisplay');
        if (!display || !selectedDrill) {
            if (display) display.style.display = 'none';
            return;
        }
        display.style.display = 'block';

        document.getElementById('selectedDrillName')?.textContent =
            `${selectedDrill.brandName} ${selectedDrill.series || ''} ${selectedDrill.size}`;
        document.getElementById('selectedDrillPrice')?.textContent =
            selectedDrill.price ? `$${selectedDrill.price.toFixed(2)}` : 'Quote';
        document.getElementById('selectedDrillPartNo')?.textContent = selectedDrill.partNo;
        document.getElementById('selectedDrillSize')?.textContent =
            `${selectedDrill.decimal?.toFixed(4)}"`;
        document.getElementById('selectedDrillFlute')?.textContent =
            `${selectedDrill.fluteLen || selectedDrill.drillLen || '?'}"`;
        document.getElementById('selectedDrillOAL')?.textContent =
            `${selectedDrill.oal || '?'}"`;

        // Material name
        const materialNames = {
            hss: 'HSS', hss_premium: 'M7 HSS', cobalt_m35: 'M35 Co',
            cobalt_m42: 'M42 Co', carbide: 'Carbide', carbide_ultrafine: 'UFG Carbide'
        };
        document.getElementById('selectedDrillMaterial')?.textContent =
            materialNames[selectedDrill.material] || selectedDrill.material;

        // Coating name
        const coatingNames = {
            uncoated: 'Bright', black_oxide: 'Black Ox', tin: 'TiN',
            ticn: 'TiCN', tialn: 'TiAlN', altin: 'AlTiN', zrn: 'ZrN'
        };
        document.getElementById('selectedDrillCoating')?.textContent =
            coatingNames[selectedDrill.coating] || selectedDrill.coating;

        // Point angle
        const pointAngle = selectedDrill.point?.replace('split_', '').replace('helical_', '').replace('conventional_', '') || '135';
        document.getElementById('selectedDrillPoint')?.textContent = `${pointAngle}°`;
    }
    // Calculate drill parameters based on current material and coolant
    function calculateDrillParameters() {
        if (!selectedDrill) return;

        // Get current material from calculator
        const materialSelect = document.getElementById('material');
        const currentMaterial = materialSelect?.value || 'aluminum_6061';

        // Map material to drill database material
        let matKey = 'aluminum';
        if (currentMaterial.includes('steel') && !currentMaterial.includes('stainless')) {
            matKey = currentMaterial.includes('4140') || currentMaterial.includes('4340') ? 'alloy_steel' : 'mild_steel';
        } else if (currentMaterial.includes('stainless')) {
            matKey = 'stainless_304';
        } else if (currentMaterial.includes('titanium')) {
            matKey = 'titanium_6al4v';
        } else if (currentMaterial.includes('cast_iron')) {
            matKey = 'cast_iron_gray';
        }
        // Get drill material type
        const drillMat = selectedDrill.material?.includes('carbide') ? 'carbide' :
                         selectedDrill.material?.includes('cobalt') ? 'cobalt' : 'hss';

        // Look up speed/feed from database
        const sfData = DRILL_DATABASE?.speedFeedRecommendations?.[matKey]?.[drillMat];

        // Get coolant configuration
        const coolantType = document.getElementById('drillCoolantType')?.value || 'flood';
        const coolantConfig = getCoolantConfiguration(coolantType);

        if (sfData) {
            let sfm = sfData.sfm[1]; // Recommended SFM
            let ipr = sfData.ipr[1]; // Recommended IPR
            const dia = selectedDrill.decimal || 0.25;

            // Apply coolant boost/penalty
            sfm = Math.round(sfm * coolantConfig.sfmMultiplier);
            ipr = Math.round(ipr * coolantConfig.iprMultiplier * 10000) / 10000;

            const rpm = Math.round((sfm * 3.82) / dia);
            const feedIpm = Math.round(rpm * ipr * 100) / 100;

            // Estimate thrust and torque
            const thrust = Math.round(dia * 500 * (ipr / 0.006)); // lbf estimate
            const torque = Math.round(dia * 50 * (ipr / 0.006) * 10) / 10; // in-lb estimate

            document.getElementById('drillCalcRPM')?.textContent = rpm.toLocaleString();
            document.getElementById('drillCalcFeed')?.textContent = `${feedIpm} IPM`;
            document.getElementById('drillCalcIPR')?.textContent = ipr.toFixed(4);
            document.getElementById('drillCalcSFM')?.textContent = sfm;
            document.getElementById('drillCalcThrust')?.textContent = `~${thrust} lbf`;
            document.getElementById('drillCalcTorque')?.textContent = `~${torque} in-lb`;
        }
        // Update coolant display
        updateCoolantDisplay(coolantConfig);
    }
    // Get coolant configuration based on type
    function getCoolantConfiguration(coolantType) {
        const configs = {
            flood: {
                sfmMultiplier: 1.0,
                iprMultiplier: 1.0,
                boost: '+0%',
                note: '💡 Standard flood coolant. Good chip evacuation and tool cooling.',
                color: '#22c55e'
            },
            mist: {
                sfmMultiplier: 0.85,
                iprMultiplier: 0.9,
                boost: '-15%',
                note: '💨 Mist/MQL reduces cooling. Lower speeds recommended. Good for aluminum.',
                color: '#f59e0b'
            },
            tsc_300: {
                sfmMultiplier: 1.15,
                iprMultiplier: 1.1,
                boost: '+15%',
                note: '🔵 TSC 300 PSI - Good chip evacuation. Standard through-spindle coolant.',
                color: '#3b82f6'
            },
            tsc_500: {
                sfmMultiplier: 1.25,
                iprMultiplier: 1.15,
                boost: '+25%',
                note: '🔵 TSC 500 PSI - Excellent chip control. Recommended for deep holes (>5×D).',
                color: '#3b82f6'
            },
            tsc_1000: {
                sfmMultiplier: 1.40,
                iprMultiplier: 1.25,
                boost: '+40%',
                note: '🚀 TSC 1000 PSI (HP) - Superior chip evacuation. Ideal for difficult materials and deep holes.',
                color: '#8b5cf6'
            },
            tsc_1500: {
                sfmMultiplier: 1.50,
                iprMultiplier: 1.30,
                boost: '+50%',
                note: '🚀 TSC 1500 PSI (UHP) - Maximum performance. For titanium, Inconel, and >8×D holes.',
                color: '#a855f7'
            },
            air: {
                sfmMultiplier: 0.70,
                iprMultiplier: 0.75,
                boost: '-30%',
                note: '💨 Air blast only. Reduces tool life significantly. Use for plastics and cast iron only.',
                color: '#ef4444'
            },
            dry: {
                sfmMultiplier: 0.50,
                iprMultiplier: 0.60,
                boost: '-50%',
                note: '⚠️ Dry cutting. Not recommended for most drilling. Severe tool wear.',
                color: '#ef4444'
            }
        };
        return configs[coolantType] || configs.flood;
    }
    // Update coolant display
    function updateCoolantDisplay(config) {
        const boostLabel = document.getElementById('coolantBoostLabel');
        const boostValue = document.getElementById('coolantBoostValue');
        const coolantNote = document.getElementById('coolantNote');

        if (boostValue) {
            boostValue.textContent = config.boost;
            boostValue.style.color = config.color;
        }
        if (coolantNote) {
            coolantNote.innerHTML = config.note;
        }
    }
    // Update drill calc params when coolant changes
    function updateDrillCalcParams() {
        calculateDrillParameters();
    }
    // Update drill recommendation based on hole parameters
    function updateDrillRecommendation() {
        const holeDia = parseFloat(document.getElementById('drillHoleDia')?.value) || 0.25;
        const holeDepth = parseFloat(document.getElementById('drillHoleDepth')?.value) || 0.5;
        const tolerance = document.getElementById('drillHoleTolerance')?.value || 'standard';

        // Get current material
        const materialSelect = document.getElementById('material');
        const currentMaterial = materialSelect?.selectedOptions?.[0]?.text || '6061 Aluminum';
        const materialValue = materialSelect?.value || 'aluminum_6061';

        // Calculate L/D ratio
        const ldRatio = holeDepth / holeDia;

        // Map material value to peck database key
        let peckMatKey = 'mild_steel'; // default
        if (materialValue.includes('aluminum')) peckMatKey = 'aluminum';
        else if (materialValue.includes('stainless') && materialValue.includes('17')) peckMatKey = 'stainless_17_4';
        else if (materialValue.includes('stainless')) peckMatKey = 'stainless_304';
        else if (materialValue.includes('titanium')) peckMatKey = 'titanium';
        else if (materialValue.includes('inconel') || materialValue.includes('hastelloy')) peckMatKey = 'inconel';
        else if (materialValue.includes('cast_iron') && materialValue.includes('ductile')) peckMatKey = 'cast_iron_ductile';
        else if (materialValue.includes('cast_iron')) peckMatKey = 'cast_iron_gray';
        else if (materialValue.includes('brass') || materialValue.includes('bronze')) peckMatKey = 'brass';
        else if (materialValue.includes('copper')) peckMatKey = 'copper';
        else if (materialValue.includes('acrylic') || materialValue.includes('pmma')) peckMatKey = 'plastic_acrylic';
        else if (materialValue.includes('delrin') || materialValue.includes('acetal')) peckMatKey = 'plastic_delrin';
        else if (materialValue.includes('nylon')) peckMatKey = 'plastic_nylon';
        else if (materialValue.includes('wood') && materialValue.includes('hard')) peckMatKey = 'wood_hardwood';
        else if (materialValue.includes('4140') || materialValue.includes('4340')) peckMatKey = 'alloy_steel';
        else if (materialValue.includes('hardened') || (materialValue.includes('steel') && materialValue.includes('hrc'))) peckMatKey = 'hardened_steel';

        // Get peck data from database
        const peckData = DRILL_DATABASE?.peckDrilling?.materials?.[peckMatKey];

        // Determine recommendations
        let drillType = 'Jobber Length';
        let drillMaterial = 'HSS';
        let drillCoating = 'Uncoated or TiN';
        let pointAngle = '135° Split Point';
        let notes = '';

        // Peck drilling variables
        let peckRequired = false;
        let peckDepthMultiplier = 1.0;
        let peckCycleType = 'G73';
        let retractType = 'chip_break';
        let peckNote = '';
        let peckWarning = '';

        // Drill type based on L/D ratio
        if (ldRatio <= 3) {
            drillType = 'Stub / Screw Machine';
        } else if (ldRatio <= 6) {
            drillType = 'Jobber Length';
        } else if (ldRatio <= 10) {
            drillType = 'Taper Length or Parabolic';
        } else {
            drillType = 'Parabolic or Coolant-Through';
        }
        // Material-specific recommendations
        if (materialValue.includes('aluminum')) {
            drillMaterial = 'HSS or Carbide';
            drillCoating = 'ZrN, DLC, or Uncoated';
            pointAngle = '135° Split Point';
            notes += '💡 Use sharp tools, high speeds, and flood coolant to prevent built-up edge.';
        } else if (materialValue.includes('stainless')) {
            drillMaterial = 'Cobalt M42 or Carbide';
            drillCoating = 'TiAlN or AlTiN';
            pointAngle = '135-140° Split Point';
            notes += '💡 Never dwell - keep cutting to prevent work hardening. Use high-pressure coolant.';
        } else if (materialValue.includes('titanium')) {
            drillMaterial = 'Carbide (Premium)';
            drillCoating = 'AlCrN or TiAlN';
            pointAngle = '140° High Performance';
            notes += '💡 Low speed, constant feed, high-pressure coolant. Fire risk with chips.';
        } else if (materialValue.includes('inconel') || materialValue.includes('hastelloy')) {
            drillMaterial = 'Premium Carbide';
            drillCoating = 'nACo or AlTiN';
            pointAngle = '140° High Performance';
            notes += '💡 Extreme work hardening. Very low speed, sharp tools only, premium coolant.';
        } else if (materialValue.includes('cast_iron')) {
            drillMaterial = 'HSS or Carbide';
            drillCoating = 'TiCN or TiAlN';
            pointAngle = '118-135° Split Point';
            notes += '💡 Dry or air blast preferred. Chips are abrasive.';
        } else if (materialValue.includes('brass') || materialValue.includes('bronze')) {
            drillMaterial = 'HSS (Slow Helix)';
            drillCoating = 'Uncoated';
            pointAngle = '118° Conventional';
            notes += '⚠️ Use slow helix drill - brass grabs! Reduce feed on breakthrough.';
        } else if (materialValue.includes('copper')) {
            drillMaterial = 'HSS or Carbide';
            drillCoating = 'DLC or ZrN';
            pointAngle = '135° Split Point';
            notes += '💡 Very gummy - use sharp, polished flute drills. DLC coating prevents sticking.';
        } else if (materialValue.includes('plastic') || materialValue.includes('acrylic') || materialValue.includes('delrin') || materialValue.includes('nylon')) {
            drillMaterial = 'HSS';
            drillCoating = 'Uncoated (Polished)';
            pointAngle = '60-90° Plastic Geometry';
            notes += '🌡️ High RPM, light feed. Peck to prevent melting. Air blast only.';
        } else if (materialValue.includes('steel')) {
            if (materialValue.includes('4140') || materialValue.includes('4340')) {
                drillMaterial = 'Cobalt M35+ or Carbide';
                drillCoating = 'TiAlN or AlTiN';
            } else {
                drillMaterial = 'HSS or Cobalt';
                drillCoating = 'TiN or TiCN';
            }
            pointAngle = '135° Split Point';
            notes += '💡 Flood coolant for best results.';
        }
        // Calculate peck drilling recommendation from database
        if (peckData) {
            const threshold = peckData.peckThreshold || 5;

            // Find appropriate depth category
            let depthCategory = null;
            if (ldRatio <= (peckData.recommendations.shallow?.maxLD || 4)) {
                depthCategory = peckData.recommendations.shallow;
            } else if (ldRatio <= (peckData.recommendations.medium?.maxLD || 8)) {
                depthCategory = peckData.recommendations.medium;
            } else if (ldRatio <= (peckData.recommendations.deep?.maxLD || 12)) {
                depthCategory = peckData.recommendations.deep;
            } else {
                depthCategory = peckData.recommendations.veryDeep;
            }
            if (depthCategory) {
                peckRequired = depthCategory.peck === true || (depthCategory.peck === 'recommended' && ldRatio >= threshold);
                peckDepthMultiplier = depthCategory.peckDepth || 1.0;
                retractType = depthCategory.retractType || 'chip_break';
                peckNote = depthCategory.note || '';

                // Set cycle type based on retract type
                if (retractType === 'full') {
                    peckCycleType = 'G83';
                } else {
                    peckCycleType = 'G73';
                }
            }
            // Add material-specific warnings
            if (peckData.specialTips && peckData.specialTips.length > 0) {
                const criticalTips = peckData.specialTips.filter(tip => tip.startsWith('⚠️') || tip.startsWith('🔥'));
                if (criticalTips.length > 0) {
                    peckWarning = criticalTips[0];
                }
            }
        } else {
            // Default peck logic if no database entry
            if (ldRatio <= 3) {
                peckRequired = false;
                peckDepthMultiplier = 0;
                peckNote = 'No peck required for shallow holes.';
            } else if (ldRatio <= 6) {
                peckRequired = false;
                peckDepthMultiplier = 1.5;
                peckNote = 'Optional chip break every 1.5×D.';
            } else if (ldRatio <= 10) {
                peckRequired = true;
                peckDepthMultiplier = 1.0;
                retractType = 'partial';
                peckCycleType = 'G73';
                peckNote = 'Standard peck every 1×D recommended.';
            } else {
                peckRequired = true;
                peckDepthMultiplier = 0.75;
                retractType = 'full';
                peckCycleType = 'G83';
                peckNote = 'Full retract peck every 0.75×D required for deep holes.';
            }
        }
        // Calculate actual peck depth
        const actualPeckDepth = holeDia * peckDepthMultiplier;
        const numberOfPecks = peckRequired && peckDepthMultiplier > 0 ? Math.ceil(holeDepth / actualPeckDepth) : 0;

        // Tolerance adjustments
        if (tolerance === 'precision' || tolerance === 'ream') {
            notes += ` 📐 For ±0.001" or better: drill undersized (0.005-0.010") and ream.`;
        }
        // Update main display
        document.getElementById('recMaterialName')?.textContent = currentMaterial;
        document.getElementById('recDrillType')?.textContent = drillType;
        document.getElementById('recDrillCoating')?.textContent = drillCoating;
        document.getElementById('recDrillPoint')?.textContent = pointAngle;
        document.getElementById('recDrillLD')?.textContent = `${ldRatio.toFixed(1)}:1 (${ldRatio <= 3 ? 'Very Rigid' : ldRatio <= 6 ? 'Rigid' : ldRatio <= 10 ? 'Moderate' : 'Flexible'})`;
        document.getElementById('recDrillNotes')?.textContent = notes;

        // Update peck drilling display
        const peckSection = document.getElementById('peckRecommendationSection');
        const peckIcon = document.getElementById('peckIcon');
        const peckStatus = document.getElementById('peckStatus');
        const peckDepthValue = document.getElementById('peckDepthValue');
        const peckDepthXD = document.getElementById('peckDepthXD');
        const peckCycleTypeEl = document.getElementById('peckCycleType');
        const peckCycleNote = document.getElementById('peckCycleNote');
        const peckWarningEl = document.getElementById('peckWarning');

        if (peckSection) {
            if (!peckRequired && ldRatio <= 3) {
                // No peck needed
                peckIcon.textContent = '✅';
                peckStatus.textContent = 'Peck Drilling: Not Required';
                peckStatus.style.color = '#22c55e';
                peckSection.style.borderLeftColor = '#22c55e';
                peckDepthValue.textContent = 'N/A';
                peckDepthXD.textContent = 'Continuous';
                peckCycleTypeEl.textContent = 'G81';
                peckCycleNote.textContent = 'Standard drilling cycle - continuous feed to depth. Chips clear naturally.';
            } else if (!peckRequired && peckDepthMultiplier > 0) {
                // Optional peck
                peckIcon.textContent = '💡';
                peckStatus.textContent = 'Peck Drilling: Optional';
                peckStatus.style.color = '#f59e0b';
                peckSection.style.borderLeftColor = '#f59e0b';
                peckDepthValue.textContent = actualPeckDepth.toFixed(3) + '"';
                peckDepthXD.textContent = peckDepthMultiplier.toFixed(1) + '×D';
                peckCycleTypeEl.textContent = 'G73';
                peckCycleNote.textContent = peckNote || 'Chip break recommended if chips wrap around drill or pack in flutes.';
            } else if (peckRequired) {
                // Peck required
                peckIcon.textContent = '🔄';
                peckStatus.textContent = 'Peck Drilling: REQUIRED';
                peckStatus.style.color = '#ef4444';
                peckSection.style.borderLeftColor = '#ef4444';
                peckDepthValue.textContent = actualPeckDepth.toFixed(3) + '"';
                peckDepthXD.textContent = peckDepthMultiplier.toFixed(2) + '×D';
                peckCycleTypeEl.textContent = peckCycleType;

                // Detailed cycle note
                if (peckCycleType === 'G83') {
                    peckCycleNote.innerHTML = `<strong>G83 Full Retract:</strong> ${peckNote || 'Retracts to R plane between pecks for complete chip clearing and coolant flooding.'} <br><span style="color: #22c55e;">${numberOfPecks} pecks for this hole.</span>`;
                } else {
                    peckCycleNote.innerHTML = `<strong>G73 Chip Break:</strong> ${peckNote || 'Small retract (0.010-0.050") breaks chips without full withdrawal.'} <br><span style="color: #22c55e;">${numberOfPecks} pecks for this hole.</span>`;
                }
            }
            // Show/hide warning
            if (peckWarning) {
                peckWarningEl.textContent = peckWarning;
                peckWarningEl.style.display = 'block';
            } else {
                peckWarningEl.style.display = 'none';
            }
        }
        // Auto-set filters based on recommendation
        if (materialValue.includes('stainless') || materialValue.includes('titanium') || materialValue.includes('inconel')) {
            document.getElementById('drillMaterialFilter')?.value = 'carbide';
        } else if (materialValue.includes('aluminum') || materialValue.includes('plastic')) {
            document.getElementById('drillMaterialFilter')?.value = 'hss';
        }
        // Update warnings and tips based on hole type and geometry
        updateDrillWarningsAndTips(materialValue, holeDia, holeDepth, ldRatio);

        // Update point angle recommendation display
        updatePointAngleRecommendation(materialValue, tolerance);
    }
    // Update warnings and tips section
    function updateDrillWarningsAndTips(materialValue, holeDia, holeDepth, ldRatio) {
        const warningsSection = document.getElementById('drillWarningsSection');
        const warningsList = document.getElementById('drillWarningsList');
        const tipsSection = document.getElementById('drillTipsSection');
        const tipsList = document.getElementById('drillTipsList');
        const holeType = document.getElementById('drillHoleType')?.value || 'through';
        const surfaceFinish = document.getElementById('drillSurfaceFinish')?.value || 'standard';
        const productionVol = document.getElementById('drillProductionVol')?.value || 'prototype';

        let warnings = [];
        let tips = [];

        // L/D ratio warnings
        if (ldRatio > 10) {
            warnings.push('🔴 L/D > 10: Drill walking, deflection, and breakage risk HIGH');
            tips.push('Use gun drill or coolant-through drill');
            tips.push('Consider pilot hole + step drilling');
        } else if (ldRatio > 6) {
            warnings.push('🟡 L/D > 6: Use peck cycle, monitor for chip packing');
        }
        // Hole type specific warnings
        if (holeType === 'angled') {
            warnings.push('⚠️ Angled entry: Drill will walk! Use spot drill or flat-bottom first');
            tips.push('Reduce feed 50% until fully engaged');
            tips.push('Use rigid setup with minimal stickout');
        } else if (holeType === 'intersecting') {
            warnings.push('⚠️ Intersecting hole: Interrupted cut - tool shock risk');
            tips.push('Reduce feed 30% through intersection');
            tips.push('Use carbide for better shock resistance');
        } else if (holeType === 'stacked') {
            warnings.push('⚠️ Stacked plates: Air gaps cause re-cutting chips');
            tips.push('Clamp plates firmly together');
            tips.push('Consider step drill or subland drill');
        } else if (holeType === 'blind') {
            tips.push('Account for drill point in depth calculation');
            tips.push('Flat-bottom drill if full-depth thread needed');
        }
        // Large diameter warnings
        if (holeDia > 0.5) {
            warnings.push('🔵 Large diameter: High thrust force - verify setup rigidity');
            tips.push('Consider pilot hole (0.5× final diameter)');
            tips.push('Use indexable or spade drill for economy');
        }
        // Material-specific warnings
        if (materialValue.includes('stainless')) {
            warnings.push('⚠️ Stainless: Work hardens if you dwell! Keep cutting');
            tips.push('Never stop feed in cut');
            tips.push('Sharp tools, constant chip load');
        } else if (materialValue.includes('titanium')) {
            warnings.push('🔥 Titanium: Fire risk with dry chips');
            tips.push('Keep chips wet with flood coolant');
            tips.push('Low RPM, positive feed');
        } else if (materialValue.includes('brass') || materialValue.includes('bronze')) {
            warnings.push('⚠️ Brass/Bronze: GRABS on breakthrough!');
            tips.push('Use slow-spiral drill geometry');
            tips.push('Reduce feed 75% near breakthrough');
        } else if (materialValue.includes('plastic') || materialValue.includes('acrylic')) {
            warnings.push('🌡️ Plastic: Melts easily - avoid friction heat');
            tips.push('High RPM, light feed, air blast');
            tips.push('Peck frequently to clear chips');
        } else if (materialValue.includes('aluminum')) {
            tips.push('ZrN or DLC coating prevents built-up edge');
            tips.push('High speed, generous chip load OK');
        }
        // Surface finish tips
        if (surfaceFinish === 'fine') {
            tips.push('For 32 Ra: Use reamer after drilling undersized');
            tips.push('Or use boring bar for precise finish');
        }
        // Production volume tips
        if (productionVol === 'high') {
            tips.push('Consider indexable drill for lower cost/hole');
            tips.push('Carbide for extended tool life');
        } else if (productionVol === 'prototype') {
            tips.push('HSS acceptable for prototype work');
        }
        // Update warning display
        if (warnings.length > 0) {
            warningsSection.style.display = 'block';
            warningsList.innerHTML = warnings.map(w => `• ${w}`).join('<br>');
        } else {
            warningsSection.style.display = 'none';
        }
        // Update tips display
        if (tips.length > 0) {
            tipsList.innerHTML = tips.slice(0, 5).map(t => `• ${t}`).join('<br>');
        }
    }
    // Update point angle recommendation
    function updatePointAngleRecommendation(materialValue, tolerance) {
        const angleRec = document.getElementById('angleRecommendation');

        // Reset all angle boxes
        ['angle90Box', 'angle118Box', 'angle135Box', 'angle140Box', 'angle180Box'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.style.borderColor = 'transparent';
        });

        let recommendedAngle = 135;
        let explanation = '';

        if (materialValue.includes('aluminum') || materialValue.includes('plastic')) {
            recommendedAngle = 118;
            explanation = '118° conventional for soft materials. Lower thrust, good chip evacuation.';
        } else if (materialValue.includes('stainless') || materialValue.includes('titanium') || materialValue.includes('inconel')) {
            recommendedAngle = 140;
            explanation = '140° high-performance for tough alloys. Stronger point, reduced deflection.';
        } else if (materialValue.includes('brass') || materialValue.includes('bronze')) {
            recommendedAngle = 118;
            explanation = '118° with slow helix for brass. Prevents grabbing on breakthrough.';
        } else if (materialValue.includes('cast_iron')) {
            recommendedAngle = 118;
            explanation = '118° or 135° for cast iron. Handles abrasive material well.';
        } else {
            recommendedAngle = 135;
            explanation = '135° split point for general steel. Self-centering, reduced thrust, better chip evacuation.';
        }
        // Highlight recommended angle
        const angleBox = document.getElementById(`angle${recommendedAngle}Box`);
        if (angleBox) angleBox.style.borderColor = 'var(--primary)';

        // Update recommendation text
        if (angleRec) {
            angleRec.innerHTML = `<span style="color: var(--primary); font-weight: 600;">💡 Recommended: ${recommendedAngle}°</span> - ${explanation}`;
        }
    }
    // Select drill angle manually
    function selectDrillAngle(angle) {
        // Reset all angle boxes
        ['angle90Box', 'angle118Box', 'angle135Box', 'angle140Box', 'angle180Box'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.style.borderColor = 'transparent';
        });

        // Highlight selected
        const selectedBox = document.getElementById(`angle${angle}Box`);
        if (selectedBox) selectedBox.style.borderColor = 'var(--primary)';

        // Update filter
        const pointFilter = document.getElementById('drillPointFilter');
        if (pointFilter) {
            if (angle === 180) {
                pointFilter.value = 'all'; // 180° not in standard filter
            } else {
                pointFilter.value = angle.toString();
            }
            filterDrills();
        }
        // Update recommendation text
        const angleRec = document.getElementById('angleRecommendation');
        const explanations = {
            90: '90° spotting drill for centering before drilling. Also for countersinks.',
            118: '118° conventional for soft materials (aluminum, plastics, brass). Lower thrust force.',
            135: '135° split point for general purpose. Self-centering, good for steel and most metals.',
            140: '140° high-performance for hard materials (stainless, titanium). Stronger point geometry.',
            180: '180° flat-bottom for blind holes requiring flat bottom. Used with indexable drills, flat-bottom end mills, or specialized flat-bottom drills. Requires pilot hole or pre-drilled start.'
        };
        if (angleRec) {
            angleRec.innerHTML = `<span style="color: var(--primary); font-weight: 600;">Selected: ${angle}°</span> - ${explanations[angle] || ''}`;
        }
    }
