    // MODULAR DRILL FUNCTIONS

    function filterModularDrills() {
        const brand = document.getElementById('modularDrillBrand')?.value || 'all';
        const diaRange = document.getElementById('modularDrillDia')?.value || 'all';
        const depthCap = document.getElementById('modularDrillDepth')?.value || 'all';
        const searchTerm = document.getElementById('modularDrillSearch')?.value?.toLowerCase() || '';

        let results = [];

        Object.entries(INDEXABLE_DRILL_DATABASE).forEach(([brandKey, brandData]) => {
            if (brand !== 'all' && brand !== brandKey) return;

            Object.entries(brandData.bodies || {}).forEach(([seriesKey, series]) => {
                if (series.type !== 'modular' && series.type !== 'replaceable_head') return;
                if (depthCap !== 'all' && !series.depthCapabilities?.includes(depthCap)) return;

                series.products?.forEach(product => {
                    const diaMM = product.diaMM || product.dia;

                    // Diameter filter
                    if (diaRange !== 'all') {
                        const [minStr, maxStr] = diaRange.split('-');
                        const minDia = parseFloat(minStr);
                        const maxDia = parseFloat(maxStr);
                        if (diaMM < minDia || diaMM > maxDia) return;
                    }
                    if (searchTerm && !product.partNo.toLowerCase().includes(searchTerm) &&
                        !series.series.toLowerCase().includes(searchTerm)) return;

                    results.push({
                        ...product,
                        brand: brandKey,
                        brandName: brandData.company,
                        series: series.series,
                        inserts: series.inserts
                    });
                });
            });
        });

        renderModularDrillBodies(results);
    }
    function renderModularDrillBodies(bodies) {
        const container = document.getElementById('modularDrillBodyResults');
        const countEl = document.getElementById('modularDrillCount');
        if (!container) return;

        countEl.textContent = bodies.length;

        if (bodies.length === 0) {
            container.innerHTML = `<div style="padding: 20px; text-align: center; color: var(--text-muted);"><div style="font-size: 24px; margin-bottom: 8px;">🔄</div><div style="font-size: 11px;">No modular drill bodies found</div></div>`;
            return;
        }
        container.innerHTML = bodies.slice(0, 30).map((body, idx) => `
            <div class="drill-result-item ${selectedModularBody?.partNo === body.partNo ? 'selected' : ''}" onclick="selectModularBody(${idx})">
                <div class="drill-icon carbide">🔄</div>
                <div class="drill-info">
                    <div class="drill-name">${body.brandName} ${body.series}</div>
                    <div class="drill-specs">Ø${formatDrillDia(body.diaMM || body.dia, body.diaInch)} • ${body.depth} • Coolant-Thru</div>
                    <div class="drill-part-no">${body.partNo}</div>
                </div>
                <div class="drill-price">$${body.price.toFixed(2)}</div>
            </div>
        `).join('');

        window._modularBodies = bodies;
    }
    function selectModularBody(idx) {
        selectedModularBody = window._modularBodies[idx];
        selectedModularTip = null;

        filterModularDrills();

        document.getElementById('selectedModularBody')?.style.display = 'block';
        document.getElementById('modularBodyInfo')?.innerHTML = `
            <div style="display: flex; justify-content: space-between; align-items: center;">
                <div>
                    <div style="font-size: 12px; font-weight: 600;">${selectedModularBody.brandName} ${selectedModularBody.series}</div>
                    <div style="font-size: 10px; font-family: monospace;">${selectedModularBody.partNo}</div>
                </div>
                <div style="font-size: 14px; font-weight: 700; color: #22c55e;">$${selectedModularBody.price.toFixed(2)}</div>
            </div>
            <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-top: 8px;">
                <div style="text-align: center; padding: 4px; background: rgba(0,0,0,0.2); border-radius: 4px;">
                    <div style="font-size: 11px; font-weight: 600;">${formatDrillDia(selectedModularBody.diaMM || selectedModularBody.dia, selectedModularBody.diaInch)}</div>
                    <div style="font-size: 8px; color: var(--text-muted);">DIAMETER</div>
                </div>
                <div style="text-align: center; padding: 4px; background: rgba(0,0,0,0.2); border-radius: 4px;">
                    <div style="font-size: 11px; font-weight: 600;">${selectedModularBody.depth}</div>
                    <div style="font-size: 8px; color: var(--text-muted);">DEPTH</div>
                </div>
                <div style="text-align: center; padding: 4px; background: rgba(0,0,0,0.2); border-radius: 4px;">
                    <div style="font-size: 11px; font-weight: 600;">${selectedModularBody.shank}mm</div>
                    <div style="font-size: 8px; color: var(--text-muted);">SHANK</div>
                </div>
            </div>
        `;

        document.getElementById('modularTipSection')?.style.display = 'block';
        filterModularTips();
    }
    function filterModularTips() {
        if (!selectedModularBody?.inserts) return;

        const gradeFilter = document.getElementById('modularTipGrade')?.value || 'all';
        const container = document.getElementById('modularTipResults');

        let tips = selectedModularBody.inserts.head || selectedModularBody.inserts.tip || selectedModularBody.inserts.crown || [];

        if (gradeFilter !== 'all') {
            tips = tips.filter(tip => {
                const materials = tip.materials || [];
                if (gradeFilter === 'steel') return materials.includes('P');
                if (gradeFilter === 'stainless') return materials.includes('M');
                if (gradeFilter === 'cast_iron') return materials.includes('K');
                if (gradeFilter === 'universal') return materials.length >= 3;
                return true;
            });
        }
        container.innerHTML = tips.map((tip, idx) => `
            <div class="drill-result-item ${selectedModularTip?.partNo === tip.partNo ? 'selected' : ''}" onclick="selectModularTip(${idx})">
                <div class="drill-icon hss">🔶</div>
                <div class="drill-info">
                    <div class="drill-name">${tip.partNo}</div>
                    <div class="drill-specs">Grade: ${tip.grade} • ${tip.geometry} • ${(tip.materials || []).join(', ')}</div>
                </div>
                <div class="drill-price">$${tip.price.toFixed(2)}</div>
            </div>
        `).join('');

        window._modularTips = tips;
    }
    function selectModularTip(idx) {
        selectedModularTip = window._modularTips[idx];
        filterModularTips();

        document.getElementById('selectedModularTip')?.style.display = 'block';
        document.getElementById('modularTipInfo')?.innerHTML = `
            <div style="display: flex; justify-content: space-between; align-items: center;">
                <div>
                    <div style="font-size: 11px; font-weight: 600; color: #22c55e;">Selected Tip</div>
                    <div style="font-size: 10px; font-family: monospace;">${selectedModularTip.partNo}</div>
                </div>
                <div style="font-size: 14px; font-weight: 700; color: #22c55e;">$${selectedModularTip.price.toFixed(2)}</div>
            </div>
        `;

        document.getElementById('modularDrillBuySection')?.style.display = 'block';
    }
    function resetModularDrillFilters() {
        document.getElementById('modularDrillBrand')?.value = 'all';
        document.getElementById('modularDrillDia')?.value = 'all';
        document.getElementById('modularDrillDepth')?.value = 'all';
        document.getElementById('modularDrillSearch')?.value = '';
        selectedModularBody = null;
        selectedModularTip = null;
        document.getElementById('selectedModularBody')?.style.display = 'none';
        document.getElementById('modularTipSection')?.style.display = 'none';
        document.getElementById('modularDrillBuySection')?.style.display = 'none';
        filterModularDrills();
    }
    // INDEXABLE DRILL FUNCTIONS (2/3/4 Insert)

    function filterIndexableDrills() {
        const brand = document.getElementById('indexableDrillBrand')?.value || 'all';
        const insertCount = document.getElementById('indexableDrillInserts')?.value || 'all';
        const diaRange = document.getElementById('indexableDrillDia')?.value || 'all';
        const depthCap = document.getElementById('indexableDrillDepth')?.value || 'all';
        const searchTerm = document.getElementById('indexableDrillSearch')?.value?.toLowerCase() || '';

        let results = [];

        Object.entries(INDEXABLE_DRILL_DATABASE).forEach(([brandKey, brandData]) => {
            if (brand !== 'all' && brand !== brandKey) return;

            Object.entries(brandData.bodies || {}).forEach(([seriesKey, series]) => {
                // Only include indexable types (2, 3, 4 insert)
                if (!series.type?.startsWith('indexable')) return;

                // Insert count filter
                if (insertCount !== 'all') {
                    const count = parseInt(insertCount);
                    if (series.insertCount !== count) return;
                }
                if (depthCap !== 'all' && !series.depthCapabilities?.includes(depthCap)) return;

                series.products?.forEach(product => {
                    const diaMM = product.diaMM || product.dia;

                    // Diameter filter
                    if (diaRange !== 'all') {
                        const [minStr, maxStr] = diaRange.split('-');
                        if (maxStr) {
                            const minDia = parseFloat(minStr);
                            const maxDia = parseFloat(maxStr);
                            if (diaMM < minDia || diaMM > maxDia) return;
                        } else if (diaRange === '40+') {
                            if (diaMM < 40) return;
                        }
                    }
                    if (searchTerm && !product.partNo.toLowerCase().includes(searchTerm) &&
                        !series.series.toLowerCase().includes(searchTerm)) return;

                    results.push({
                        ...product,
                        brand: brandKey,
                        brandName: brandData.company,
                        series: series.series,
                        insertCount: series.insertCount,
                        insertPositions: series.insertPositions,
                        inserts: series.inserts
                    });
                });
            });
        });

        renderIndexableDrillBodies(results);
    }
    function renderIndexableDrillBodies(bodies) {
        const container = document.getElementById('indexableDrillBodyResults');
        const countEl = document.getElementById('indexableDrillCount');
        if (!container) return;

        countEl.textContent = bodies.length;

        if (bodies.length === 0) {
            container.innerHTML = `<div style="padding: 20px; text-align: center; color: var(--text-muted);"><div style="font-size: 24px; margin-bottom: 8px;">💎</div><div style="font-size: 11px;">No indexable drill bodies found</div></div>`;
            return;
        }
        container.innerHTML = bodies.slice(0, 30).map((body, idx) => `
            <div class="drill-result-item ${selectedIndexableBody?.partNo === body.partNo ? 'selected' : ''}" onclick="selectIndexableBodyFromDrillSelector(${idx})">
                <div class="drill-icon carbide">💎</div>
                <div class="drill-info">
                    <div class="drill-name">${body.brandName} ${body.series}</div>
                    <div class="drill-specs">Ø${formatDrillDia(body.diaMM || body.dia, body.diaInch)} • ${body.depth} • ${body.insertCount}-Insert</div>
                    <div class="drill-part-no">${body.partNo}</div>
                </div>
                <div class="drill-price">$${body.price.toFixed(2)}</div>
            </div>
        `).join('');

        window._indexableBodies = bodies;
    }
    function selectIndexableBodyFromDrillSelector(idx) {
        selectedIndexableBody = window._indexableBodies[idx];
        selectedIndexableCentralInsert = null;
        selectedIndexablePeripheralInsert = null;

        filterIndexableDrills();

        document.getElementById('selectedIndexableBody')?.style.display = 'block';
        document.getElementById('indexableBodyInfo')?.innerHTML = `
            <div style="display: flex; justify-content: space-between; align-items: center;">
                <div>
                    <div style="font-size: 12px; font-weight: 600;">${selectedIndexableBody.brandName} ${selectedIndexableBody.series}</div>
                    <div style="font-size: 10px; font-family: monospace;">${selectedIndexableBody.partNo}</div>
                </div>
                <div style="font-size: 14px; font-weight: 700; color: #22c55e;">$${selectedIndexableBody.price.toFixed(2)}</div>
            </div>
            <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-top: 8px;">
                <div style="text-align: center; padding: 4px; background: rgba(0,0,0,0.2); border-radius: 4px;">
                    <div style="font-size: 11px; font-weight: 600;">${formatDrillDia(selectedIndexableBody.diaMM || selectedIndexableBody.dia, selectedIndexableBody.diaInch)}</div>
                    <div style="font-size: 8px; color: var(--text-muted);">DIAMETER</div>
                </div>
                <div style="text-align: center; padding: 4px; background: rgba(0,0,0,0.2); border-radius: 4px;">
                    <div style="font-size: 11px; font-weight: 600;">${selectedIndexableBody.depth}</div>
                    <div style="font-size: 8px; color: var(--text-muted);">DEPTH</div>
                </div>
                <div style="text-align: center; padding: 4px; background: rgba(0,0,0,0.2); border-radius: 4px;">
                    <div style="font-size: 11px; font-weight: 600;">${selectedIndexableBody.shank}mm</div>
                    <div style="font-size: 8px; color: var(--text-muted);">SHANK</div>
                </div>
                <div style="text-align: center; padding: 4px; background: rgba(0,0,0,0.2); border-radius: 4px;">
                    <div style="font-size: 11px; font-weight: 600;">${selectedIndexableBody.insertCount}</div>
                    <div style="font-size: 8px; color: var(--text-muted);">INSERTS</div>
                </div>
            </div>
        `;

        document.getElementById('indexableInsertSection')?.style.display = 'block';
        filterIndexableInserts();
    }
    function filterIndexableInsertsOld() {
        if (!selectedIndexableBody?.inserts) return;

        const gradeFilter = document.getElementById('indexableInsertGrade')?.value || 'all';
        const coatingFilter = document.getElementById('indexableInsertCoating')?.value || 'all';

        // Get central and peripheral inserts
        const positions = selectedIndexableBody.insertPositions || ['central', 'peripheral'];
        let centralInserts = selectedIndexableBody.inserts[positions[0]] || selectedIndexableBody.inserts.central || selectedIndexableBody.inserts.inner || selectedIndexableBody.inserts.center || [];
        let peripheralInserts = selectedIndexableBody.inserts[positions[1]] || selectedIndexableBody.inserts.peripheral || selectedIndexableBody.inserts.outer || [];

        // Apply filters
        const filterFn = (insert) => {
            if (gradeFilter !== 'all') {
                const materials = insert.materials || [];
                if (gradeFilter === 'steel' && !materials.includes('P')) return false;
                if (gradeFilter === 'stainless' && !materials.includes('M')) return false;
                if (gradeFilter === 'cast_iron' && !materials.includes('K')) return false;
                if (gradeFilter === 'aluminum' && !materials.includes('N')) return false;
                if (gradeFilter === 'universal' && materials.length < 3) return false;
            }
            if (coatingFilter !== 'all' && insert.coating !== coatingFilter) return false;
            return true;
        };
        centralInserts = centralInserts.filter(filterFn);
        peripheralInserts = peripheralInserts.filter(filterFn);

        // Render central inserts
        const centralContainer = document.getElementById('indexableCentralInsertResults');
        centralContainer.innerHTML = centralInserts.map((insert, idx) => `
            <div class="drill-result-item ${selectedIndexableCentralInsert?.partNo === insert.partNo ? 'selected' : ''}" onclick="selectIndexableCentralInsert(${idx})">
                <div class="drill-icon cobalt">⬤</div>
                <div class="drill-info">
                    <div class="drill-name">${insert.partNo}</div>
                    <div class="drill-specs">${insert.grade} • ${insert.geometry} • ${(insert.materials || []).join(',')}</div>
                </div>
                <div class="drill-price">$${insert.price.toFixed(2)}</div>
            </div>
        `).join('') || '<div style="padding: 10px; text-align: center; color: var(--text-muted); font-size: 10px;">No central inserts match filters</div>';

        // Render peripheral inserts
        const peripheralContainer = document.getElementById('indexablePeripheralInsertResults');
        peripheralContainer.innerHTML = peripheralInserts.map((insert, idx) => `
            <div class="drill-result-item ${selectedIndexablePeripheralInsert?.partNo === insert.partNo ? 'selected' : ''}" onclick="selectIndexablePeripheralInsert(${idx})">
                <div class="drill-icon hss">◯</div>
                <div class="drill-info">
                    <div class="drill-name">${insert.partNo}</div>
                    <div class="drill-specs">${insert.grade} • ${insert.geometry} • ${(insert.materials || []).join(',')}</div>
                </div>
                <div class="drill-price">$${insert.price.toFixed(2)}</div>
            </div>
        `).join('') || '<div style="padding: 10px; text-align: center; color: var(--text-muted); font-size: 10px;">No peripheral inserts match filters</div>';

        window._centralInserts = centralInserts;
        window._peripheralInserts = peripheralInserts;
    }
    function selectIndexableCentralInsert(idx) {
        selectedIndexableCentralInsert = window._centralInserts[idx];
        filterIndexableInserts();
        checkIndexableComplete();
    }
    function selectIndexablePeripheralInsert(idx) {
        selectedIndexablePeripheralInsert = window._peripheralInserts[idx];
        filterIndexableInserts();
        checkIndexableComplete();
    }
    function checkIndexableComplete() {
        if (selectedIndexableBody && selectedIndexableCentralInsert && selectedIndexablePeripheralInsert) {
            document.getElementById('selectedIndexableInserts')?.style.display = 'block';
            document.getElementById('indexableInsertInfo')?.innerHTML = `
                <div style="font-size: 10px; font-weight: 600; color: #22c55e; margin-bottom: 6px;">✓ Inserts Selected</div>
                <div style="font-size: 9px; margin-bottom: 4px;"><span style="color: var(--text-muted);">Central:</span> ${selectedIndexableCentralInsert.partNo}</div>
                <div style="font-size: 9px;"><span style="color: var(--text-muted);">Peripheral:</span> ${selectedIndexablePeripheralInsert.partNo}</div>
            `;

            // Show params and cost
            document.getElementById('indexableDrillParams')?.style.display = 'block';
            document.getElementById('indexableDrillCost')?.style.display = 'block';
            document.getElementById('indexableDrillBuySection')?.style.display = 'block';

            updateIndexableDrillParams();
        }
    }
    function updateIndexableDrillParams() {
        if (!selectedIndexableBody) return;

        const diaMM = selectedIndexableBody.diaMM || selectedIndexableBody.dia;
        const diaInch = selectedIndexableBody.diaInch || (diaMM / 25.4);

        // Get material
        const materialSelect = document.getElementById('material');
        const materialValue = materialSelect?.value || 'steel_1018';

        // Calculate parameters
        let sfm = 350, ipr = 0.006;
        if (materialValue.includes('aluminum')) { sfm = 600; ipr = 0.010; }
        else if (materialValue.includes('stainless')) { sfm = 250; ipr = 0.005; }
        else if (materialValue.includes('titanium')) { sfm = 120; ipr = 0.004; }

        const rpm = Math.round((sfm * 12) / (Math.PI * diaInch));
        const feed = (rpm * ipr).toFixed(1);

        document.getElementById('idxMillRPM')?.textContent = rpm.toLocaleString();
        document.getElementById('idxMillFeed')?.textContent = feed;
        document.getElementById('idxMillIPR')?.textContent = ipr.toFixed(4);
        document.getElementById('idxMillSFM')?.textContent = sfm;

        document.getElementById('idxLatheRPM')?.textContent = rpm.toLocaleString();
        document.getElementById('idxLatheIPR')?.textContent = ipr.toFixed(4);
        document.getElementById('idxLatheSFM')?.textContent = sfm;

        // Cost analysis
        const bodyPrice = selectedIndexableBody.price;
        const centralPrice = selectedIndexableCentralInsert?.price || 0;
        const peripheralPrice = selectedIndexablePeripheralInsert?.price || 0;
        const totalCost = bodyPrice + centralPrice + peripheralPrice;

        document.getElementById('idxTotalCost')?.textContent = `$${totalCost.toFixed(2)}`;
        document.getElementById('idxCostPerEdge')?.textContent = `$${((centralPrice + peripheralPrice) / 2).toFixed(2)}`;
        document.getElementById('idxHolesPerEdge')?.textContent = '~600';
    }
    function resetIndexableDrillFilters() {
        document.getElementById('indexableDrillBrand')?.value = 'all';
        document.getElementById('indexableDrillInserts')?.value = 'all';
        document.getElementById('indexableDrillDia')?.value = 'all';
        document.getElementById('indexableDrillDepth')?.value = 'all';
        document.getElementById('indexableDrillSearch')?.value = '';
        selectedIndexableBody = null;
        selectedIndexableCentralInsert = null;
        selectedIndexablePeripheralInsert = null;
        document.getElementById('selectedIndexableBody')?.style.display = 'none';
        document.getElementById('indexableInsertSection')?.style.display = 'none';
        document.getElementById('indexableDrillParams')?.style.display = 'none';
        document.getElementById('indexableDrillCost')?.style.display = 'none';
        document.getElementById('indexableDrillBuySection')?.style.display = 'none';
        filterIndexableDrills();
    }
    // Generic buy modal opener
    function openDrillBuyModal(type) {
        const modal = document.getElementById('drillBuyModal');
        if (!modal) return;
        modal.classList.add('active');

        let bodyName = '', partNo = '';
        if (type === 'spade' && selectedSpadeBody) {
            bodyName = `${selectedSpadeBody.brandName} ${selectedSpadeBody.series}`;
            partNo = selectedSpadeBody.partNo;
        } else if (type === 'modular' && selectedModularBody) {
            bodyName = `${selectedModularBody.brandName} ${selectedModularBody.series}`;
            partNo = selectedModularBody.partNo;
        } else if (type === 'indexable' && selectedIndexableBody) {
            bodyName = `${selectedIndexableBody.brandName} ${selectedIndexableBody.series}`;
            partNo = selectedIndexableBody.partNo;
        }
        document.getElementById('drillBuyModalName')?.textContent = bodyName;
        document.getElementById('drillBuyModalInfo')?.textContent = `Part #: ${partNo}`;
    }
    // Generic copy part numbers
    function copyDrillPartNumbers(type) {
        let text = '';
        if (type === 'spade' && selectedSpadeBody) {
            text = `Body: ${selectedSpadeBody.partNo}`;
            if (selectedSpadeInsert) text += `\nBlade: ${selectedSpadeInsert.partNo}`;
        } else if (type === 'modular' && selectedModularBody) {
            text = `Body: ${selectedModularBody.partNo}`;
            if (selectedModularTip) text += `\nTip: ${selectedModularTip.partNo}`;
        } else if (type === 'indexable' && selectedIndexableBody) {
            text = `Body: ${selectedIndexableBody.partNo}`;
            if (selectedIndexableCentralInsert) text += `\nCentral: ${selectedIndexableCentralInsert.partNo}`;
            if (selectedIndexablePeripheralInsert) text += `\nPeripheral: ${selectedIndexablePeripheralInsert.partNo}`;
        }
        if (text) {
            navigator.clipboard.writeText(text).then(() => {
                const toast = document.createElement('div');
                toast.style.cssText = `position: fixed; top: 70px; left: 50%; transform: translateX(-50%); background: linear-gradient(135deg, #00ff88, #00cc66); color: #000; padding: 10px 20px; border-radius: 6px; font-weight: 600; z-index: 10001;`;
                toast.textContent = '✓ Part numbers copied!';
                document.body.appendChild(toast);
                setTimeout(() => toast.remove(), 2000);
            });
        }
    }
