    // CUTTING FORCE CALCULATION ENGINE - Kienzle Model
    const CuttingForceEngine = {
        // Material cutting force constants (kc1.1 in N/mm², mc exponent)
        materialConstants: {
            steel_1018: { kc11: 2100, mc: 0.25 },
            steel_4140: { kc11: 2400, mc: 0.23 },
            aluminum_6061: { kc11: 800, mc: 0.30 },
            aluminum_7075: { kc11: 950, mc: 0.28 },
            stainless_304: { kc11: 2800, mc: 0.21 },
            titanium: { kc11: 1900, mc: 0.18 },
            cast_iron: { kc11: 1450, mc: 0.28 }
        },
        // Calculate specific cutting force: kc = kc1.1 × h^(-mc)
        specificCuttingForce: function(kc11, mc, chipThickness) {
            if (chipThickness <= 0) return kc11;
            return kc11 * Math.pow(chipThickness, -mc);
        },
        // Calculate cutting forces
        calculate: function(params) {
            const { toolDia, flutes, rpm, feedrate, doc, woc, material } = params;

            // Get material constants (default to steel)
            const mat = this.materialConstants[material] || this.materialConstants.steel_1018;

            // Calculate chip thickness (mm)
            const fz = (feedrate / rpm / flutes) * 25.4;  // feed per tooth in mm
            const engagementRatio = Math.min(woc / toolDia, 1);
            const avgChipThickness = fz * engagementRatio * 0.7;  // Simplified average

            // Specific cutting force
            const kc = this.specificCuttingForce(mat.kc11, mat.mc, Math.max(avgChipThickness, 0.01));

            // Force calculations (simplified Kienzle)
            const docMM = doc * 25.4;
            const Fc = kc * docMM * avgChipThickness * flutes * engagementRatio;  // Tangential (N)
            const Fr = Fc * 0.4;  // Radial ≈ 40% of tangential
            const Fa = Fc * 0.2;  // Axial ≈ 20% of tangential
            const Ft = Math.sqrt(Fc*Fc + Fr*Fr + Fa*Fa);  // Resultant

            // Convert to lbf (1 N = 0.2248 lbf)
            return {
                tangential: Fc * 0.2248,
                radial: Fr * 0.2248,
                axial: Fa * 0.2248,
                resultant: Ft * 0.2248
            };
        }
    };
    // STABILITY CALCULATION ENGINE
    let selectedWorkholding = null;

    const StabilityEngine = {
        // Calculate overall stability score (0-100%)
        calculate: function() {
            // Get inputs
            const stockHeight = parseFloat(document.getElementById('stockHeight')?.value) || 2;
            const clampedDepth = parseFloat(document.getElementById('clampedDepth')?.value) || 0.75;
            const toolDia = parseFloat(document.getElementById('toolDia')?.value) || 0.5;
            const stickout = parseFloat(document.getElementById('stickout')?.value) || 2.0;
            const doc = parseFloat(document.getElementById('doc')?.value) || 0.5;
            const woc = parseFloat(document.getElementById('woc')?.value) || 0.25;

            // Get workholding
            const wh = selectedWorkholding ? WORKHOLDING_DATABASE[selectedWorkholding] : null;
            const baseRigidity = wh ? wh.rigidityScore : 7.0;

            // Calculate factors
            const clampRatio = clampedDepth / stockHeight;
            const stickoutRatio = stickout / toolDia;

            let score = 100;
            const warnings = [];

            // Clamping factor (20 points)
            if (clampRatio < 0.25) {
                score -= 25;
                warnings.push({ type: 'critical', text: '⚠️ CRITICAL: Clamping too shallow - ejection risk!' });
            } else if (clampRatio < 0.33) {
                score -= 12;
                warnings.push({ type: 'caution', text: '⚠️ Low clamping ratio - reduce aggressiveness' });
            }
            // Stickout factor (20 points)
            if (stickoutRatio > 5) {
                score -= 20;
                warnings.push({ type: 'critical', text: '⚠️ Extreme stickout - severe deflection!' });
            } else if (stickoutRatio > 4) {
                score -= 10;
                warnings.push({ type: 'caution', text: '⚠️ High stickout - reduce DOC/feed' });
            }
            // Workholding rigidity factor (15 points)
            score -= (10 - baseRigidity) * 1.5;

            // Cutting aggressiveness (15 points)
            const aggressiveness = (doc * woc) / (toolDia * toolDia);
            if (aggressiveness > 0.3) {
                score -= 15;
            } else if (aggressiveness > 0.15) {
                score -= 8;
            }
            return {
                score: Math.max(0, Math.min(100, score)),
                warnings: warnings,
                clampRatio: clampRatio,
                stickoutRatio: stickoutRatio
            };
        },
        // Get recommended parameters based on stability
        getRecommendations: function(score) {
            const toolDia = parseFloat(document.getElementById('toolDia')?.value) || 0.5;

            if (score >= 85) {
                return {
                    doc: (toolDia * 2.0).toFixed(3) + '"',
                    woc: (toolDia * 0.25).toFixed(3) + '"',
                    stickout: (toolDia * 4).toFixed(2) + '"',
                    strategy: 'Adaptive/Trochoidal'
                };
            } else if (score >= 70) {
                return {
                    doc: (toolDia * 1.5).toFixed(3) + '"',
                    woc: (toolDia * 0.20).toFixed(3) + '"',
                    stickout: (toolDia * 3.5).toFixed(2) + '"',
                    strategy: 'Adaptive Clearing'
                };
            } else if (score >= 50) {
                return {
                    doc: (toolDia * 1.0).toFixed(3) + '"',
                    woc: (toolDia * 0.15).toFixed(3) + '"',
                    stickout: (toolDia * 3).toFixed(2) + '"',
                    strategy: 'Light Pocketing'
                };
            } else {
                return {
                    doc: (toolDia * 0.5).toFixed(3) + '"',
                    woc: (toolDia * 0.10).toFixed(3) + '"',
                    stickout: (toolDia * 2.5).toFixed(2) + '"',
                    strategy: 'Conservative'
                };
            }
        }
    };
    // WORKHOLDING UI FUNCTIONS

    // Filter and populate workholding dropdown based on category and brand
    function filterWorkholding() {
        const categoryFilter = document.getElementById('workholdingCategory')?.value || '';
        const brandFilter = document.getElementById('workholdingBrand')?.value || '';
        const select = document.getElementById('workholdingType');
        const countEl = document.getElementById('workholdingCount');

        if (!select) return;

        // Clear current options
        select.innerHTML = '<option value="">Select Workholding...</option>';

        // Group workholding by category for organized display
        const grouped = {
            'Kurt Vises': [],
            'Glacern Vises': [],
            'Orange Vise': [],
            'Lang Technik': [],
            'Chick Workholding': [],
            '5th Axis': [],
            'Gerardi': [],
            'STM': [],
            'Raptor': [],
            'Piranha': [],
            'Kitagawa Chucks': [],
            'Bison Chucks': [],
            'Samchully Chucks': [],
            'Schunk': [],
            'Jergens': [],
            'Erowa': [],
            'System 3R': [],
            'Vacuum': [],
            'Magnetic': [],
            'Rotary / 4th Axis': [],
            'Clamps': [],
            'Specialty': [],
            'Accessories': [],
            'Other': []
        };
        let matchCount = 0;

        for (const [key, wh] of Object.entries(WORKHOLDING_DATABASE)) {
            // Apply category filter
            if (categoryFilter) {
                const catParts = categoryFilter.split('_');
                const mainCat = catParts[0];
                const subCat = catParts.slice(1).join('_');

                if (mainCat === 'vise' && wh.category !== 'vise') continue;
                if (mainCat === 'chuck' && wh.category !== 'chuck') continue;
                if (mainCat === 'fixture' && wh.category !== 'fixture') continue;
                if (mainCat === 'vacuum' && wh.category !== 'vacuum') continue;
                if (mainCat === 'magnetic' && wh.category !== 'magnetic') continue;
                if (mainCat === 'rotary' && wh.category !== 'rotary') continue;
                if (mainCat === 'clamp' && wh.category !== 'clamp') continue;
                if (mainCat === 'specialty' && wh.category !== 'specialty') continue;
                if (mainCat === 'accessory' && wh.category !== 'accessory') continue;

                // Check subcategory if specified
                if (subCat && wh.subcategory !== subCat &&
                    !(subCat === 'precision' && wh.subcategory === 'precision') &&
                    !(subCat === 'heavy_duty' && wh.subcategory === 'heavy_duty') &&
                    !(subCat === 'compact' && wh.subcategory === 'compact') &&
                    !(subCat === '5axis' && (wh.subcategory === '5axis' || wh.subcategory === '5axis_dovetail')) &&
                    !(subCat === 'power' && wh.subcategory === 'power_chuck') &&
                    !(subCat === 'manual' && wh.subcategory === 'manual_chuck') &&
                    !(subCat === 'ball_lock' && wh.subcategory === 'ball_lock') &&
                    !(subCat === 'zero_point' && wh.subcategory === 'zero_point') &&
                    !(subCat === 'modular' && wh.subcategory === 'modular') &&
                    !(subCat === 'pallet' && wh.subcategory === 'pallet')
                ) continue;
            }
            // Apply brand filter
            if (brandFilter && wh.brand !== brandFilter) continue;

            matchCount++;

            // Determine group
            let group = 'Other';
            if (wh.brand === 'Kurt') group = 'Kurt Vises';
            else if (wh.brand === 'Glacern') group = 'Glacern Vises';
            else if (wh.brand === 'Orange Vise') group = 'Orange Vise';
            else if (wh.brand === 'Lang Technik') group = 'Lang Technik';
            else if (wh.brand === 'Chick') group = 'Chick Workholding';
            else if (wh.brand === '5th Axis') group = '5th Axis';
            else if (wh.brand === 'Gerardi') group = 'Gerardi';
            else if (wh.brand === 'STM') group = 'STM';
            else if (wh.brand === 'Raptor') group = 'Raptor';
            else if (wh.brand === 'Piranha') group = 'Piranha';
            else if (wh.brand === 'Kitagawa') group = 'Kitagawa Chucks';
            else if (wh.brand === 'Bison') group = 'Bison Chucks';
            else if (wh.brand === 'Samchully') group = 'Samchully Chucks';
            else if (wh.brand === 'Schunk') group = 'Schunk';
            else if (wh.brand === 'Jergens') group = 'Jergens';
            else if (wh.brand === 'Erowa') group = 'Erowa';
            else if (wh.brand === 'System 3R') group = 'System 3R';
            else if (wh.category === 'vacuum') group = 'Vacuum';
            else if (wh.category === 'magnetic') group = 'Magnetic';
            else if (wh.category === 'rotary') group = 'Rotary / 4th Axis';
            else if (wh.category === 'clamp') group = 'Clamps';
            else if (wh.category === 'specialty') group = 'Specialty';
            else if (wh.category === 'accessory') group = 'Accessories';

            grouped[group].push({ key, wh });
        }
        // Add options by group
        for (const [groupName, items] of Object.entries(grouped)) {
            if (items.length === 0) continue;

            const optgroup = document.createElement('optgroup');
            optgroup.label = groupName;

            // Sort by name within group
            items.sort((a, b) => a.wh.name.localeCompare(b.wh.name));

            for (const { key, wh } of items) {
                const option = document.createElement('option');
                option.value = key;
                const price = wh.price ? ` ($${wh.price.toLocaleString()})` : '';
                option.textContent = `${wh.name}${price}`;
                optgroup.appendChild(option);
            }
            select.appendChild(optgroup);
        }
        // Update count
        if (countEl) {
            countEl.textContent = `(${matchCount} items)`;
        }
    }
    function selectWorkholdingType() {
        const select = document.getElementById('workholdingType');
        const type = select?.value;

        if (!type || !WORKHOLDING_DATABASE[type]) {
            selectedWorkholding = null;
            document.getElementById('workholdingDetails')?.innerHTML = 'No workholding selected';
            calculateStability();
            return;
        }
        selectedWorkholding = type;
        const wh = WORKHOLDING_DATABASE[type];

        // Build features list if available
        const featuresHtml = wh.features ?
            `<div style="margin-top: 6px; display: flex; flex-wrap: wrap; gap: 4px;">
                ${wh.features.map(f => `<span style="background: rgba(59,130,246,0.2); color: var(--primary); padding: 2px 6px; border-radius: 4px; font-size: 9px;">${f}</span>`).join('')}
            </div>` : '';

        // Build best-for list if available
        const bestForHtml = wh.bestFor ?
            `<div style="margin-top: 6px; font-size: 9px; color: var(--text-muted);">
                <span style="color: var(--success);">✓ Best for:</span> ${wh.bestFor.join(', ')}
            </div>` : '';

        // Additional specs based on category
        let additionalSpecs = '';
        if (wh.jawWidth) {
            additionalSpecs += `<span>Jaw Width: <strong>${wh.jawWidth}"</strong></span>`;
        }
        if (wh.maxOpening) {
            additionalSpecs += `<span>Max Opening: <strong>${wh.maxOpening}"</strong></span>`;
        }
        if (wh.chuckDiameter) {
            additionalSpecs += `<span>Chuck Size: <strong>${wh.chuckDiameter}"</strong></span>`;
        }
        if (wh.throughHole) {
            additionalSpecs += `<span>Through Hole: <strong>${wh.throughHole}"</strong></span>`;
        }
        if (wh.maxRpm) {
            additionalSpecs += `<span>Max RPM: <strong>${wh.maxRpm.toLocaleString()}</strong></span>`;
        }
        if (wh.plateSize) {
            additionalSpecs += `<span>Plate Size: <strong>${wh.plateSize}"</strong></span>`;
        }
        document.getElementById('workholdingDetails')?.innerHTML = `
            <div style="display: flex; justify-content: space-between; margin-bottom: 6px;">
                <strong style="color: var(--primary);">${wh.name}</strong>
                <span style="color: var(--success);">$${wh.price?.toLocaleString() || 'N/A'}</span>
            </div>
            <div style="color: var(--text-muted); margin-bottom: 6px;">${wh.brand}${wh.partNumber ? ' • ' + wh.partNumber : ''}</div>
            <div style="color: var(--text); font-size: 10px; margin-bottom: 8px;">${wh.description}</div>
            <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 4px; font-size: 9px;">
                <span>Clamp Force: <strong>${wh.clampForce?.toLocaleString() || 'N/A'} lbf</strong></span>
                <span>Rigidity: <strong>${wh.rigidityScore}/10</strong></span>
                <span>Stiffness: <strong>${wh.stiffness ? (wh.stiffness/1000).toFixed(0) + 'k lb/in' : 'N/A'}</strong></span>
                <span>Repeatability: <strong>${wh.repeatability}"</strong></span>
                ${additionalSpecs}
            </div>
            ${featuresHtml}
            ${bestForHtml}
        `;

        calculateStability();
    }
    function calculateStability() {
        // Check if feature is available (SHOP tier)
        if (!hasFeature('workholding')) {
            return;
        }
        // Calculate stability
        const result = StabilityEngine.calculate();
        const score = result.score;

        // Update stability display
        const valueEl = document.getElementById('stabilityValue');
        const indicatorEl = document.getElementById('stabilityIndicator');

        if (valueEl) {
            valueEl.textContent = Math.round(score) + '%';
            valueEl.className = 'stability-value ' +
                (score >= 85 ? 'excellent' : score >= 70 ? 'good' : score >= 50 ? 'warning' : 'critical');
        }
        if (indicatorEl) {
            indicatorEl.style.left = score + '%';
        }
        // Update clamp percentage
        const stockHeight = parseFloat(document.getElementById('stockHeight')?.value) || 2;
        const clampedDepth = parseFloat(document.getElementById('clampedDepth')?.value) || 0.75;
        const clampPercentEl = document.getElementById('clampPercent');
        if (clampPercentEl) {
            clampPercentEl.textContent = `(${((clampedDepth/stockHeight)*100).toFixed(1)}%)`;
        }
        // Update warnings
        const warningsEl = document.getElementById('stabilityWarnings');
        if (warningsEl) {
            warningsEl.innerHTML = result.warnings.map(w => `
                <div class="stability-warning ${w.type}">${w.text}</div>
            `).join('');
        }
        // Calculate and display forces
        const forces = CuttingForceEngine.calculate({
            toolDia: parseFloat(document.getElementById('toolDia')?.value) || 0.5,
            flutes: parseInt(document.getElementById('flutes')?.value) || 4,
            rpm: parseFloat(document.getElementById('resultRpm')?.textContent?.replace(/,/g, '')) || 5000,
            feedrate: parseFloat(document.getElementById('resultFeed')?.textContent) || 50,
            doc: parseFloat(document.getElementById('doc')?.value) || 0.5,
            woc: parseFloat(document.getElementById('woc')?.value) || 0.25,
            material: 'steel_1018'
        });

        document.getElementById('forceTangential')?.textContent = forces.tangential.toFixed(0);
        document.getElementById('forceRadial')?.textContent = forces.radial.toFixed(0);
        document.getElementById('forceResultant')?.textContent = forces.resultant.toFixed(0);

        // Update recommendations
        const recs = StabilityEngine.getRecommendations(score);
        document.getElementById('suggestedDOC')?.textContent = recs.doc;
        document.getElementById('suggestedWOC')?.textContent = recs.woc;
        document.getElementById('suggestedStickout')?.textContent = recs.stickout;
        document.getElementById('suggestedStrategy')?.textContent = recs.strategy;
    }
