    // Control type detection - maps manufacturer/control strings to feature compatibility
    const CONTROL_TYPE_MAP = {
        // Fanuc-based controls
        fanuc: ["fanuc", "pro 6", "pro6", "doosan", "okk", "hardinge", "matsuura", "g-tech", "kitamura", "yasda", "mitsui_seiki", "toyoda", "toyopuc", "hyundai", "ycm", "feeler", "quaser", "hartford", "johnford", "chevalier", "victor", "leadwell", "smtcl", "dmtg", "fanuc/siemens", "fanuc/g-tech"],
        // Siemens-based controls
        siemens: ["siemens", "840d", "sinumerik", "heller", "grob", "chiron", "spinner", "starrag", "emco", "siemens/fanuc", "fanuc/siemens"],
        // Heidenhain controls
        heidenhain: ["heidenhain", "tnc", "itnc", "hermle", "mikron", "kern"],
        // Okuma OSP
        okuma: ["okuma", "osp"],
        // Mazak controls
        mazak: ["mazak", "mazatrol", "smoothai", "smooth ai"],
        // Haas controls
        haas: ["haas", "ngc"],
        // Makino controls
        makino: ["makino", "pro 6", "pro6", "hyper"],
        // Hurco controls
        hurco: ["hurco", "winmax"],
        // Mitsubishi controls
        mitsubishi: ["mitsubishi", "m80", "m800", "roku"],
        // Brother controls
        brother: ["brother", "cnc-c00", "speedio"],
        // Sodick controls
        sodick: ["sodick", "ln2"],
        // Röders controls
        roders: ["röders", "roders", "rms"],
        // Fidia controls
        fidia: ["fidia", "c40"],
        // DMG MORI CELOS
        dmg_mori: ["dmg", "mori", "celos"],
        // Kitamura controls
        kitamura: ["kitamura", "arumatik"]
    };
    // Function to detect control type from machine
    function detectControlType(machineId) {
        const machine = MACHINE_DATABASE.machines[machineId];
        if (!machine) return [];

        const manufacturer = MACHINE_DATABASE.manufacturers[machine.manufacturer];
        const controlString = (machine.control || manufacturer?.control || '').toLowerCase();
        const mfrKey = machine.manufacturer.toLowerCase();

        const matchedTypes = [];

        for (const [controlType, keywords] of Object.entries(CONTROL_TYPE_MAP)) {
            for (const keyword of keywords) {
                if (controlString.includes(keyword) || mfrKey.includes(keyword)) {
                    if (!matchedTypes.includes(controlType)) {
                        matchedTypes.push(controlType);
                    }
                    break;
                }
            }
        }
        // If no specific match, default to generic capabilities
        if (matchedTypes.length === 0) {
            matchedTypes.push('generic');
        }
        return matchedTypes;
    }
    // Function to get available motion features for a machine
    function getAvailableMotionFeatures(machineId) {
        const controlTypes = detectControlType(machineId);
        const availableFeatures = [];

        for (const [featureId, feature] of Object.entries(FEATURE_DEFINITIONS)) {
            if (feature.category !== 'motion') continue;

            // Check if feature is compatible with machine's control
            if (feature.controls) {
                if (feature.controls.includes('all')) {
                    availableFeatures.push(featureId);
                } else {
                    for (const controlType of controlTypes) {
                        if (feature.controls.includes(controlType)) {
                            availableFeatures.push(featureId);
                            break;
                        }
                    }
                }
            }
        }
        return availableFeatures;
    }
