    function updateCannedCycleGuide() {
        const cycleType = document.getElementById('cannedCycleCategory')?.value || 'mill_drill_g81';
        const guide = CANNED_CYCLE_GUIDES[cycleType];
        const container = document.getElementById('cannedCycleGuideDisplay');
        const controlType = getSelectedControlType();
        const dialect = CONTROL_DIALECTS[controlType] || CONTROL_DIALECTS.fanuc;

        if (!guide || !container) return;

        // Control-specific cycle variations
        let controlNotes = [];
        let altSyntax = guide.syntax;

        if (controlType === 'siemens') {
            controlNotes = [
                'Siemens uses CYCLE81-CYCLE89 for drilling',
                'CYCLE840 for tapping, CYCLE82 for counterbore',
                'Parameters in parentheses: CYCLE83(RTP,RFP,SDIS,DP,DPR,DTB)'
            ];
            if (cycleType.includes('g83')) altSyntax = 'CYCLE83(RTP,RFP,SDIS,DP,DPR,FDEP,FDPR,DAM,DTB,DTS,FRF,VARI,AXN,MDEP,VRT,DTD,DIS1)';
            if (cycleType.includes('g81')) altSyntax = 'CYCLE81(RTP,RFP,SDIS,DP,DPR)';
            if (cycleType.includes('g84')) altSyntax = 'CYCLE840(RTP,RFP,SDIS,DP,DPR,DTB,SDR,SDAC,ENC,MPIT,PIT)';
        } else if (controlType === 'okuma') {
            controlNotes = [
                'Okuma uses similar G-codes but different parameter names',
                'G85/G86 for lathe roughing cycles (not boring)',
                'Threading: G71 instead of G76'
            ];
            if (cycleType.includes('lathe_rough_g71')) altSyntax = 'G71 U__ R__  or  G71 P__ Q__ U__ W__ F__ (Similar to Fanuc)';
            if (cycleType.includes('lathe_thread_g76')) altSyntax = 'G71 P__ Q__ F__ (Thread cycle on Okuma)';
        } else if (controlType === 'heidenhain') {
            controlNotes = [
                'Heidenhain uses CYCL DEF for cycles',
                'CYCL DEF 1.0 PECKING, CYCL DEF 2.0 TAPPING',
                'Different conversational format'
            ];
            if (cycleType.includes('g83')) altSyntax = 'CYCL DEF 1.0 PECKING\\n  Q200=2    ;SET-UP CLEARANCE\\n  Q201=-25  ;DEPTH\\n  Q206=150  ;FEED RATE\\n  Q202=5    ;PLUNGING DEPTH';
        } else if (controlType === 'mazak') {
            controlNotes = [
                'Mazatrol: Use UNITs for drilling/boring',
                'EIA Mode: Standard Fanuc cycles work',
                'Tool format: T0101 (4 digit)'
            ];
        } else if (controlType === 'haas') {
            controlNotes = [
                'Standard Fanuc cycles supported',
                'G98/G99 for return plane control',
                'Rigid tap by default (no M29 needed)'
            ];
        }
        container.innerHTML = `
            <!-- Control Type Badge -->
            <div style="background: linear-gradient(135deg, ${dialect.color}22, ${dialect.color}11); border: 1px solid ${dialect.color}66; border-radius: 8px; padding: 10px; margin-bottom: 12px;">
                <div style="display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px;">
                    <div style="display: flex; align-items: center; gap: 8px;">
                        <span style="font-size: 16px;">🎛️</span>
                        <div>
                            <div style="font-weight: 700; font-size: 12px; color: ${dialect.color};">CONTROL: ${dialect.name}</div>
                            <div style="font-size: 9px; color: var(--text-muted);">Cycle syntax for your control</div>
                        </div>
                    </div>
                </div>
                ${controlNotes.length > 0 ? `
                <div style="margin-top: 8px; padding-top: 8px; border-top: 1px solid ${dialect.color}33;">
                    <div style="font-size: 9px; color: var(--text-muted);">
                        ${controlNotes.map(n => `<div style="margin-bottom: 2px;">• ${n}</div>`).join('')}
                    </div>
                </div>
                ` : ''}
            </div>

            <div style="margin-bottom: 15px;">
                <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 10px;">
                    <span style="font-size: 28px; font-weight: 700; color: #22c55e; font-family: monospace;">${guide.gcode}</span>
                    <div>
                        <div style="font-weight: 700; font-size: 14px; color: var(--primary);">${guide.title}</div>
                        <div style="font-size: 11px; color: var(--text-muted);">${guide.motion}</div>
                    </div>
                </div>
            </div>

            <div style="background: rgba(0,100,200,0.1); border: 1px solid rgba(0,150,255,0.3); border-radius: 6px; padding: 10px; margin-bottom: 12px;">
                <div style="font-weight: 600; font-size: 11px; color: #60a5fa; margin-bottom: 6px;">📝 SYNTAX (${dialect.name})</div>
                <code style="font-family: 'Courier New', monospace; font-size: 12px; color: #22c55e; background: rgba(0,0,0,0.3); padding: 6px 10px; border-radius: 4px; display: block; white-space: pre-wrap;">
${altSyntax}</code>
            </div>

            <div style="background: rgba(50,50,50,0.3); border: 1px solid rgba(100,100,100,0.3); border-radius: 6px; padding: 10px; margin-bottom: 12px;">
                <div style="font-weight: 600; font-size: 11px; color: var(--text); margin-bottom: 6px;">📊 CYCLE DIAGRAM</div>
                <pre style="font-family: 'Courier New', monospace; font-size: 10px; color: #22c55e; background: #0a0a0a; padding: 10px; border-radius: 4px; margin: 0; white-space: pre;">${guide.diagram}</pre>
            </div>

            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 12px;">
                <div style="background: rgba(0,150,100,0.1); border: 1px solid rgba(16,185,129,0.3); border-radius: 6px; padding: 10px;">
                    <div style="font-weight: 600; font-size: 10px; color: #10b981; margin-bottom: 4px;">✅ BEST FOR</div>
                    <div style="font-size: 10px; color: var(--text-muted);">${guide.application}</div>
                </div>
                <div style="background: rgba(200,100,0,0.1); border: 1px solid rgba(245,158,11,0.3); border-radius: 6px; padding: 10px;">
                    <div style="font-weight: 600; font-size: 10px; color: #f59e0b; margin-bottom: 4px;">📌 NOTES</div>
                    <ul style="margin: 0; padding-left: 14px; font-size: 9px; color: var(--text-muted);">
                        ${guide.notes.map(n => `<li>${n}</li>`).join('')}
                    </ul>
                </div>
            </div>
        `;
    }
