    function updateToolpathCategoryButtons() {
        const container = document.getElementById('toolpathCategoryBtns');
        if (!container) return;

        const isLathe = typeof machineMode !== 'undefined' && machineMode === 'lathe';
        const categories = isLathe ? LATHE_TOOLPATH_CATEGORIES : MILL_TOOLPATH_CATEGORIES;

        // Set default category based on mode
        if (isLathe && !selectedToolpathCategory.startsWith('turn_')) {
            selectedToolpathCategory = 'turn_roughing';
        } else if (!isLathe && selectedToolpathCategory.startsWith('turn_')) {
            selectedToolpathCategory = 'roughing';
        }
        container.innerHTML = categories.map(cat => `
            <button class="toolpath-cat-btn ${selectedToolpathCategory === cat.id ? 'active' : ''}"
                    data-category="${cat.id}"
                    onclick="selectToolpathCategory('${cat.id}')">
                ${cat.icon} ${cat.name}
            </button>
        `).join('');

        // Update toolpath list
        populateToolpathList();
    }
    function updateCamToolpaths() {
        selectedToolpath = null;
        updateToolpathCategoryButtons();
        populateToolpathList();
        updateToolpathRecommendations();

        // Hide selected panel
        const selectedPanel = document.getElementById('selectedToolpathPanel');
        const quickPanel = document.getElementById('quickStrategyPanel');
        if (selectedPanel) selectedPanel.style.display = 'none';
        if (quickPanel) quickPanel.style.display = 'block';
    }
    function selectToolpathCategory(category) {
        selectedToolpathCategory = category;
        selectedToolpath = null;

        // Update button states
        document.querySelectorAll('.toolpath-cat-btn').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.category === category);
        });

        populateToolpathList();

        // Reset selected panel
        const selectedPanel = document.getElementById('selectedToolpathPanel');
        const quickPanel = document.getElementById('quickStrategyPanel');
        if (selectedPanel) selectedPanel.style.display = 'none';
        if (quickPanel) quickPanel.style.display = 'block';

        // SWITCH BETWEEN MILLING AND DRILLING TOOL TABS
        const isLathe = typeof machineMode !== 'undefined' && machineMode === 'lathe';
        const isDrillingOperation = category === 'drilling' || category === 'turn_drilling';

        const millingTabs = document.getElementById('millingToolTabs');
        const drillingTabs = document.getElementById('drillingToolTabs');

        if (isDrillingOperation) {
            // Show drilling tabs, hide milling tabs
            if (millingTabs) millingTabs.style.display = 'none';
            if (drillingTabs) drillingTabs.style.display = 'flex';

            // Show twist drill section by default
            selectDrillCategory('twist');
        } else {
            // Show milling tabs, hide drilling tabs
            if (millingTabs) millingTabs.style.display = 'flex';
            if (drillingTabs) drillingTabs.style.display = 'none';

            // Determine which cutting tool type is needed
            let toolType = 'solid'; // Default to end mills

            if (isLathe) {
                switch (category) {
                    case 'turn_milling':
                        toolType = 'solid';
                        break;
                }
            } else {
                switch (category) {
                    case 'roughing':
                    case 'finishing':
                    case '2d':
                    case '3d':
                    case '4axis':
                    case '5axis':
                        toolType = 'solid';
                        break;
                }
            }
            if (typeof selectToolCategory === 'function') {
                selectToolCategory(toolType);
            }
        }
        console.log(`CAM Toolpath: ${category} → ${isDrillingOperation ? 'Drilling Tools' : 'Milling Tools'}`);
    }
    // DRILL CATEGORY SELECTION (Twist, Spade, Modular, Indexable)
    function selectDrillCategory(category, btn) {
        // Update button states
        document.querySelectorAll('#drillingToolTabs .tab-btn').forEach(b => b.classList.remove('active'));

        const tabIds = {
            'twist': 'tabTwistDrills',
            'spade': 'tabSpadeDrills',
            'modular': 'tabModularDrills',
            'indexable': 'tabIndexableDrills'
        };
        const actualBtn = btn || document.getElementById(tabIds[category]);
        if (actualBtn) actualBtn.classList.add('active');

        // Hide ALL tool sections (both milling and drilling)
        const allSections = [
            'solidCarbideSection',      // End mills
            'iscarMillSection',         // Indexable mills
            'iscarDrillSection',        // Twist drills
            'spadeDrillSection',        // Spade drills
            'modularDrillSection',      // Modular drills
            'indexableDrillSection'     // Indexable drills
        ];
        allSections.forEach(id => {
            const el = document.getElementById(id);
            if (el) {
                el.style.display = 'none';
                el.classList.remove('active');
            }
        });

        // Show the selected drill section
        const sectionMap = {
            'twist': 'iscarDrillSection',
            'spade': 'spadeDrillSection',
            'modular': 'modularDrillSection',
            'indexable': 'indexableDrillSection'
        };
        const sectionId = sectionMap[category];
        const section = document.getElementById(sectionId);
        if (section) {
            section.style.display = 'block';
            section.classList.add('active');
        }
        // Initialize the selected category
        switch (category) {
            case 'twist':
                if (typeof updateDrillRecommendation === 'function') updateDrillRecommendation();
                if (typeof filterDrills === 'function') filterDrills();
                break;
            case 'spade':
                if (typeof filterSpadeDrills === 'function') filterSpadeDrills();
                break;
            case 'modular':
                if (typeof filterModularDrills === 'function') filterModularDrills();
                break;
            case 'indexable':
                if (typeof filterIndexableDrills === 'function') filterIndexableDrills();
                break;
        }
    }
    function populateToolpathList() {
        const camId = document.getElementById('camSoftware')?.value || 'fusion360';
        const isLathe = typeof machineMode !== 'undefined' && machineMode === 'lathe';
        const database = isLathe ? LATHE_TOOLPATH_DATABASE : CAM_TOOLPATH_DATABASE;
        const camData = database[camId];
        const container = document.getElementById('toolpathList');

        if (!camData || !container) return;

        const toolpaths = camData[selectedToolpathCategory] || [];

        container.innerHTML = toolpaths.map(tp => `
            <div class="toolpath-item ${selectedToolpath === tp.id ? 'selected' : ''}"
                 data-toolpath="${tp.id}">
                <div style="display: flex; align-items: center; gap: 8px;">
                    <div style="flex: 1; cursor: pointer;" onclick="selectToolpath('${tp.id}')">
                        <div class="toolpath-item-name">
                            ${tp.recommended ? '⭐ ' : ''}${tp.name}
                        </div>
                        <div class="toolpath-item-desc">${tp.desc}</div>
                    </div>
                    <div style="display: flex; align-items: center; gap: 6px;">
                        ${tp.recommended ? '<span style="font-size: 9px; color: var(--success); background: rgba(34,197,94,0.2); padding: 2px 6px; border-radius: 4px;">Recommended</span>' : ''}
                        <button onclick="event.stopPropagation(); showToolpathExplanation('${tp.id}')"
                                style="background: rgba(139, 92, 246, 0.2); border: 1px solid rgba(139, 92, 246, 0.4); border-radius: 4px; color: #a78bfa; width: 24px; height: 24px; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;"
                                title="Learn more about ${tp.name}">?</button>
                    </div>
                </div>
            </div>
        `).join('');

        if (toolpaths.length === 0) {
            container.innerHTML = '<div style="padding: 20px; text-align: center; color: var(--text-muted);">No toolpaths in this category for this CAM software</div>';
        }
    }
    function selectToolpath(toolpathId) {
        const camId = document.getElementById('camSoftware')?.value || 'fusion360';
        const isLathe = typeof machineMode !== 'undefined' && machineMode === 'lathe';
        const database = isLathe ? LATHE_TOOLPATH_DATABASE : CAM_TOOLPATH_DATABASE;
        const camData = database[camId];

        if (!camData) return;

        // Find the toolpath
        const toolpath = camData[selectedToolpathCategory]?.find(tp => tp.id === toolpathId);
        if (!toolpath) return;

        selectedToolpath = toolpathId;

        // Update visual selection
        document.querySelectorAll('.toolpath-item').forEach(item => {
            item.classList.toggle('selected', item.dataset.toolpath === toolpathId);
        });

        // Show selected panel
        const quickPanel = document.getElementById('quickStrategyPanel');
        const selectedPanel = document.getElementById('selectedToolpathPanel');
        if (quickPanel) quickPanel.style.display = 'none';
        if (selectedPanel) selectedPanel.style.display = 'block';

        // Update selected panel content
        const categoryIcons = isLathe ? {
            turn_roughing: '⛏️',
            turn_finishing: '✨',
            turn_grooving: '〰️',
            turn_parting: '✂️',
            turn_threading: '🔩',
            turn_drilling: '🕳️',
            turn_boring: '⭕',
            turn_milling: '⚡'
        } : {
            roughing: '⛏️',
            finishing: '✨',
            drilling: '🕳️',
            '2d': '📐',
            '3d': '🗻',
            '4axis': '🔄',
            '5axis': '✈️',
            turning: '🔩'
        };
        const iconEl = document.getElementById('selectedToolpathIcon');
        const nameEl = document.getElementById('selectedToolpathName');
        const camNameEl = document.getElementById('selectedToolpathCamName');

        if (iconEl) iconEl.textContent = categoryIcons[selectedToolpathCategory] || '🔧';
        if (nameEl) nameEl.textContent = toolpath.name;
        if (camNameEl) {
            const categoryName = selectedToolpathCategory.replace('turn_', '').toUpperCase();
            camNameEl.textContent = `${camData.name} • ${isLathe ? 'LATHE ' : ''}${categoryName}`;
        }
        // Generate parameter recommendations
        generateToolpathParams(toolpath, selectedToolpathCategory);

        // Trigger guidance advancement
        if (typeof checkGuidanceProgress === 'function') {
            checkGuidanceProgress('toolpathSelected');
        }
    }
