    /**
     * Enable the purchase card
     */
    function enablePostPurchase() {
        const purchaseCard = document.getElementById('postPurchaseCard');
        purchaseCard.style.opacity = '1';
        purchaseCard.style.pointerEvents = 'auto';

        // Update price based on machine complexity
        updatePostPrice();
    }
    /**
     * Update post processor price based on machine
     */
    function updatePostPrice() {
        const machineId = document.getElementById('machineSelect')?.value;
        let price = 149; // Base price

        if (machineMode === 'lathe') {
            const lathe = LATHE_MACHINE_DATABASE?.machines?.[machineId];
            if (lathe) {
                if (lathe.turret?.liveTools) price += 50;
                if (lathe.yAxis) price += 25;
                if (lathe.bAxis) price += 50;
                if (lathe.subSpindle) price += 50;
                if (lathe.millingSpindle) price += 75;
            }
        } else {
            const machine = MACHINE_DATABASE?.machines?.[machineId];
            if (machine) {
                if (machine.axes === 5) price += 75;
                else if (machine.axes === 4) price += 25;
                if (machine.spindle?.bigPlus) price += 25;
                if (machine.coolant?.tscPressure > 300) price += 25;
            }
        }
        document.getElementById('postPrice')?.textContent = price;
    }
