    /**
     * Get control type from machine selection
     */
    function getControlTypeFromMachine(machineId) {
        if (!machineId) return null;

        const id = machineId.toLowerCase();

        if (id.includes('haas')) return 'haas';
        if (id.includes('okuma')) return 'okuma';
        if (id.includes('mazak')) return 'mazak';
        if (id.includes('hurco')) return 'hurco';
        if (id.includes('hermle') || id.includes('heidenhain')) return 'heidenhain';
        if (id.includes('siemens') || id.includes('dmg')) return 'siemens';
        if (id.includes('doosan') || id.includes('fanuc') || id.includes('brother')) return 'fanuc';
        if (id.includes('makino')) return 'fanuc'; // Makino uses FANUC-based

        return 'fanuc'; // Default to FANUC-style
    }
    /**
     * Toggle between G-code and M-code view
     */
    function toggleCodeReference(type) {
        currentCodeView = type;

        // Update button styles
        const gcodeBtn = document.getElementById('gcodeToggleBtn');
        const mcodeBtn = document.getElementById('mcodeToggleBtn');

        if (type === 'gcode') {
            gcodeBtn.style.background = 'var(--primary)';
            gcodeBtn.style.color = 'white';
            mcodeBtn.style.background = 'transparent';
            mcodeBtn.style.color = 'var(--text-muted)';
        } else {
            mcodeBtn.style.background = 'var(--primary)';
            mcodeBtn.style.color = 'white';
            gcodeBtn.style.background = 'transparent';
            gcodeBtn.style.color = 'var(--text-muted)';
        }
        // Refresh the code reference
        updateCodeReference();
    }
    /**
     * Update the code reference based on selected machine
     */
    function updateCodeReference() {
        // Don't show G-code reference in EDM mode
        if (machineMode === 'edm') {
            const noMachineDiv = document.getElementById('codeRefNoMachine');
            const contentDiv = document.getElementById('codeRefContent');
            if (noMachineDiv) noMachineDiv.style.display = 'none';
            if (contentDiv) contentDiv.style.display = 'none';
            return;
        }
        const machineId = document.getElementById('machineSelect')?.value;
        const noMachineDiv = document.getElementById('codeRefNoMachine');
        const contentDiv = document.getElementById('codeRefContent');

        if (!machineId) {
            // No machine selected - show message
            if (noMachineDiv) noMachineDiv.style.display = 'block';
            if (contentDiv) contentDiv.style.display = 'none';
            return;
        }
        // Machine selected - show content
        if (noMachineDiv) noMachineDiv.style.display = 'none';
        if (contentDiv) contentDiv.style.display = 'block';

        // Get machine and control info
        let machineName = machineId;
        let controlName = 'Generic';

        if (machineMode === 'lathe' && LATHE_MACHINE_DATABASE?.machines?.[machineId]) {
            const lathe = LATHE_MACHINE_DATABASE.machines[machineId];
            machineName = lathe.model || machineId;
            controlName = lathe.control || 'Unknown';
        } else if (MACHINE_DATABASE?.machines?.[machineId]) {
            const machine = MACHINE_DATABASE.machines[machineId];
            machineName = machine.model || machine.name || machineId;
            controlName = machine.control?.name || 'Unknown';
        }
        // Update header
        document.getElementById('codeRefMachineName')?.textContent = machineName;
        document.getElementById('codeRefControlName')?.textContent = controlName;

        // Get control type and populate codes
        const controlType = getControlTypeFromMachine(machineId);
        populateCodeGrid(controlType);
    }
    /**
     * Populate the code grid with relevant codes
     */
    function populateCodeGrid(controlType) {
        const grid = document.getElementById('codeRefGrid');
        if (!grid) return;

        let codes = [];

        if (currentCodeView === 'gcode') {
            // Add common G-codes
            const common = GCODE_DATABASE.common;
            Object.values(common).forEach(category => {
                codes = codes.concat(category);
            });

            // Add control-specific G-codes
            if (GCODE_DATABASE[controlType]) {
                codes = codes.concat(GCODE_DATABASE[controlType]);
            }
        } else {
            // Add common M-codes
            const common = MCODE_DATABASE.common;
            Object.values(common).forEach(category => {
                codes = codes.concat(category);
            });

            // Add control-specific M-codes
            if (MCODE_DATABASE[controlType]) {
                codes = codes.concat(MCODE_DATABASE[controlType]);
            }
        }
        // Sort codes
        codes.sort((a, b) => {
            const aCode = a.code.replace(/[^0-9]/g, '') || '999';
            const bCode = b.code.replace(/[^0-9]/g, '') || '999';
            return parseInt(aCode) - parseInt(bCode);
        });

        // Render codes
        renderCodeGrid(codes);
    }
    /**
     * Render the code grid
     */
    function renderCodeGrid(codes) {
        const grid = document.getElementById('codeRefGrid');
        const searchTerm = document.getElementById('codeRefSearch')?.value?.toLowerCase() || '';

        // Filter codes if search term exists
        let filteredCodes = codes;
        if (searchTerm) {
            filteredCodes = codes.filter(c =>
                c.code.toLowerCase().includes(searchTerm) ||
                c.name.toLowerCase().includes(searchTerm) ||
                c.desc.toLowerCase().includes(searchTerm) ||
                c.category.toLowerCase().includes(searchTerm)
            );
        }
        // Group by category
        const byCategory = {};
        filteredCodes.forEach(code => {
            if (!byCategory[code.category]) {
                byCategory[code.category] = [];
            }
            byCategory[code.category].push(code);
        });

        // Generate HTML
        let html = '';

        // Category colors
        const categoryColors = {
            'Motion': '#22c55e',
            'Plane Selection': '#06b6d4',
            'Units': '#8b5cf6',
            'Compensation': '#f59e0b',
            'Work Offsets': '#3b82f6',
            'Canned Cycles': '#ec4899',
            'Positioning': '#14b8a6',
            'Feedrate': '#f97316',
            'HSM': '#eab308',
            '5-Axis': '#a855f7',
            'Macros': '#6366f1',
            'Transform': '#64748b',
            'Data': '#84cc16',
            'Special': '#78716c',
            'Cycles': '#ec4899',
            'Probing': '#06b6d4',
            'Program Control': '#ef4444',
            'Spindle': '#22c55e',
            'Tool Change': '#f59e0b',
            'Coolant': '#3b82f6',
            'Clamping': '#8b5cf6',
            'Auxiliary': '#64748b',
            'Rotary': '#a855f7',
            'Subprograms': '#6366f1',
            'User': '#78716c',
            'Door': '#14b8a6',
            'Pallet': '#f97316',
            'Tapping': '#ec4899',
            'Control': '#84cc16',
            'Turret': '#eab308',
            'Tool': '#f59e0b'
        };
        Object.keys(byCategory).sort().forEach(category => {
            const color = categoryColors[category] || '#6366f1';
            const catCodes = byCategory[category];

            html += `
                <div style="background: rgba(0,0,0,0.2); border-radius: 8px; padding: 12px; border-left: 3px solid ${color};">
                    <div style="font-weight: 600; font-size: 11px; color: ${color}; margin-bottom: 8px; text-transform: uppercase;">
                        ${category}
                    </div>
                    <div style="display: flex; flex-direction: column; gap: 6px;">
                        ${catCodes.map(c => `
                            <div style="display: flex; gap: 8px; align-items: flex-start;">
                                <code style="
                                    background: rgba(0,0,0,0.3);
                                    padding: 2px 6px;
                                    border-radius: 4px;
                                    font-size: 11px;
                                    font-weight: 600;
                                    color: ${color};
                                    white-space: nowrap;
                                    min-width: 60px;
                                ">${c.code}</code>
                                <div>
                                    <div style="font-size: 11px; font-weight: 500; color: var(--text-primary);">${c.name}</div>
                                    <div style="font-size: 9px; color: var(--text-muted);">${c.desc}</div>
                                </div>
                            </div>
                        `).join('')}
                    </div>
                </div>
            `;
        });

        grid.innerHTML = html || '<div style="text-align: center; padding: 40px; color: var(--text-muted);">No codes found matching your search.</div>';

        // Update count
        document.getElementById('codeRefCount')?.textContent = filteredCodes.length;
    }
    /**
     * Filter codes based on search input
     */
    function filterCodeReference() {
        const machineId = document.getElementById('machineSelect')?.value;
        if (!machineId) return;

        const controlType = getControlTypeFromMachine(machineId);
        populateCodeGrid(controlType);
    }
    // G-FORCE PHYSICS ENGINE FOR CNC MACHINING
    // Comprehensive calculations for:
    // - Axis acceleration/deceleration forces
    // - Corner dynamics and jerk limiting
    // - Centrifugal forces on rotating tools
    // - Tool holder balance requirements
    // - Cutting force analysis
    // - Chip ejection dynamics
    // - Machine kinematics optimization

    const G_FORCE_ENGINE = {
        // Physical constants
        GRAVITY: 9.81,  // m/s²
        GRAVITY_IPM: 386.4,  // in/s²

        // AXIS ACCELERATION LIMITS BY MACHINE TYPE
        MACHINE_ACCELERATION: {
            // Acceleration in g's for typical machines
            vmc_tier2: { x: 0.5, y: 0.5, z: 0.4, description: "Standard VMC (VF-series, etc.)" },
            vmc_high_speed: { x: 1.0, y: 1.0, z: 0.8, description: "High-speed VMC (Makino, Brother)" },
            hmc: { x: 0.8, y: 0.8, z: 0.6, description: "Horizontal Machining Center" },
            five_axis: { x: 0.6, y: 0.6, z: 0.5, a: 0.3, c: 0.4, description: "5-axis VMC" },
            lathe: { x: 0.8, z: 0.6, description: "CNC Lathe" },
            swiss: { x: 1.2, z: 0.9, description: "Swiss-style lathe" }
        },
        // JERK LIMITS (Rate of change of acceleration)
        JERK_LIMITS: {
            // Jerk in m/s³
            rough: 50,      // Aggressive - fastest moves
            standard: 30,   // Normal machining
            finish: 15,     // Smooth finish cuts
            ultraFinish: 5  // Mirror finishes, mold work
        },
        /**
         * Calculate axis acceleration force
         * F = ma, where a = Δv/Δt
         * @param {number} velocity - Feed rate in IPM
         * @param {number} decelDistance - Distance to decelerate in inches
         * @param {number} mass - Moving mass in kg
         * @returns {object} Force and G analysis
         */
        calculateAxisAcceleration: function(velocity, decelDistance, mass = 500) {
            // Convert IPM to in/s
            const v = velocity / 60;  // in/s

            // Calculate deceleration: v² = 2as, so a = v²/(2s)
            const accel = (v * v) / (2 * decelDistance);  // in/s²

            // Convert to g's
            const gForce = accel / this.GRAVITY_IPM;

            // Calculate force (F = ma)
            const force = mass * (accel * 0.0254);  // Convert to m/s², then N

            return {
                acceleration: accel,  // in/s²
                gForce: gForce,
                force: force,  // Newtons
                safe: gForce <= 1.0,
                recommendation: gForce > 1.0 ?
                    `Reduce feed to ${Math.round(velocity / Math.sqrt(gForce))} IPM` :
                    "Within safe limits"
            };
        },
        /**
         * Calculate corner deceleration requirements
         * At corners, velocity vector changes direction requiring deceleration
         * @param {number} feedRate - Feed rate in IPM
         * @param {number} angle - Corner angle in degrees (90 = right angle)
         * @param {number} maxAccel - Maximum acceleration in g's
         * @returns {object} Corner dynamics analysis
         */
        calculateCornerDynamics: function(feedRate, angle, maxAccel = 0.5) {
            // Convert angle to radians
            const angleRad = (180 - angle) * Math.PI / 180;

            // Velocity change at corner
            const velocityChange = feedRate * Math.sin(angleRad / 2) * 2;

            // Required deceleration for sharp corner (assuming 0.1" radius)
            const cornerRadius = 0.1;  // inches
            const centripetal = (feedRate / 60) ** 2 / cornerRadius;  // in/s²
            const gForceCorner = centripetal / this.GRAVITY_IPM;

            // Calculate maximum safe feed through corner
            const maxFeed = 60 * Math.sqrt(maxAccel * this.GRAVITY_IPM * cornerRadius);

            // Look-ahead blocks needed
            const lookAhead = Math.ceil((feedRate / 60) / (maxAccel * this.GRAVITY_IPM * 0.1));

            return {
                velocityChange: velocityChange,
                gForceAtCorner: gForceCorner,
                maxSafeFeed: Math.round(maxFeed),
                lookAheadBlocks: lookAhead,
                recommendation: feedRate > maxFeed ?
                    `Reduce feed to ${Math.round(maxFeed)} IPM at ${angle}° corners` :
                    "Feed rate acceptable for corner"
            };
        },
        /**
         * Calculate centrifugal force on rotating tool
         * F = mω²r = m(2πn/60)²r
         * @param {number} rpm - Spindle speed in RPM
         * @param {number} mass - Tool/insert mass in grams
         * @param {number} radius - Radius from centerline in mm
         * @returns {object} Centrifugal force analysis
         */
        calculateCentrifugalForce: function(rpm, mass, radius) {
            // Convert units
            const massKg = mass / 1000;
            const radiusM = radius / 1000;

            // Angular velocity (rad/s)
            const omega = (2 * Math.PI * rpm) / 60;

            // Centrifugal force (N)
            const force = massKg * omega * omega * radiusM;

            // G-force experienced
            const gForce = force / (massKg * this.GRAVITY);

            // Maximum safe RPM (typically inserts rated for 500g)
            const maxG = 500;
            const maxSafeRpm = 60 * Math.sqrt((maxG * this.GRAVITY) / radiusM) / (2 * Math.PI);

            return {
                force: force,  // Newtons
                gForce: Math.round(gForce),
                maxSafeRpm: Math.round(maxSafeRpm),
                safe: gForce <= maxG,
                recommendation: gForce > maxG ?
                    `Reduce RPM to ${Math.round(maxSafeRpm)} or use balanced holder` :
                    "Within insert retention limits"
            };
        },
        /**
         * Calculate tool holder balance requirements
         * G = (U × n) / (9549 × 1000)
         * Where U = unbalance (g·mm), n = RPM
         * @param {number} rpm - Maximum spindle speed
         * @param {number} holderMass - Holder + tool mass in kg
         * @returns {object} Balance grade requirements
         */
        calculateBalanceGrade: function(rpm, holderMass = 2) {
            // Balance grades and their permissible specific unbalance (mm/s)
            const grades = {
                'G0.4': 0.4,   // Precision grinding spindles
                'G1': 1.0,     // Precision tool holders
                'G2.5': 2.5,   // High-speed machining
                'G6.3': 6.3,   // Standard machining
                'G16': 16,     // General purpose
                'G40': 40      // Low-speed, rough work
            };
            // Calculate required balance grade
            // e = G × 9549 / n (mm/s eccentricity)
            const requiredGrades = {};

            for (const [grade, eper] of Object.entries(grades)) {
                const maxUnbalance = (eper * holderMass * 1000 * 9549) / rpm;  // g·mm
                requiredGrades[grade] = {
                    maxUnbalance: Math.round(maxUnbalance * 100) / 100,
                    recommended: false
                };
            }
            // Determine recommended grade based on RPM
            let recommendedGrade = 'G6.3';
            if (rpm > 15000) recommendedGrade = 'G2.5';
            if (rpm > 25000) recommendedGrade = 'G1';
            if (rpm > 40000) recommendedGrade = 'G0.4';

            requiredGrades[recommendedGrade].recommended = true;

            return {
                rpm: rpm,
                holderMass: holderMass,
                recommendedGrade: recommendedGrade,
                grades: requiredGrades,
                notes: rpm > 10000 ?
                    "High-speed operation - use shrink-fit or hydraulic holders" :
                    "Standard collet or ER holders acceptable"
            };
        },
        /**
         * Calculate cutting forces from chip load and material
         * Fc = Kc × Ac = Kc × (fz × ap)
         * @param {number} kc - Specific cutting force (N/mm²)
         * @param {number} chipLoad - Feed per tooth (mm)
         * @param {number} doc - Depth of cut (mm)
         * @param {number} numTeeth - Number of teeth engaged
         * @returns {object} Cutting force analysis
         */
        calculateCuttingForces: function(kc, chipLoad, doc, numTeeth = 1) {
            // Cross-sectional area of cut
            const chipArea = chipLoad * doc;  // mm²

            // Tangential cutting force (main cutting force)
            const Fc = kc * chipArea * numTeeth;  // N

            // Feed force (typically 30-50% of Fc)
            const Ff = Fc * 0.4;  // N

            // Radial/passive force (typically 20-40% of Fc)
            const Fp = Fc * 0.3;  // N

            // Resultant force
            const Fr = Math.sqrt(Fc*Fc + Ff*Ff + Fp*Fp);  // N

            // Power requirement: P = Fc × Vc / 60000 (kW)
            // Assuming 200 m/min cutting speed
            const Vc = 200;  // m/min
            const power = (Fc * Vc) / 60000;  // kW

            return {
                tangential: Math.round(Fc),     // N
                feed: Math.round(Ff),           // N
                radial: Math.round(Fp),         // N
                resultant: Math.round(Fr),      // N
                power: Math.round(power * 100) / 100,  // kW
                powerHp: Math.round(power * 1.341 * 100) / 100  // HP
            };
        },
        /**
         * Calculate chip ejection forces and velocities
         * Important for chip control and coolant requirements
         * @param {number} rpm - Spindle speed
         * @param {number} toolDia - Tool diameter (mm)
         * @param {number} chipLoad - Feed per tooth (mm)
         * @returns {object} Chip dynamics
         */
        calculateChipDynamics: function(rpm, toolDia, chipLoad) {
            // Cutting velocity at tool periphery (m/s)
            const Vc = (Math.PI * toolDia * rpm) / 60000;

            // Chip velocity is approximately equal to cutting velocity
            const chipVelocity = Vc;  // m/s

            // Chip mass flow rate (rough estimate)
            // Assuming 7850 kg/m³ density (steel), chip width = chipLoad
            const chipMassRate = 7850 * chipLoad/1000 * 0.5/1000 * Vc;  // kg/s (very rough)

            // Centrifugal acceleration on chip at exit
            const chipExitG = (Vc * Vc) / (toolDia / 2000) / this.GRAVITY;

            // Required coolant pressure for chip clearing
            let coolantPressure = "Low (50-150 PSI)";
            if (chipExitG < 50) coolantPressure = "Medium (150-300 PSI)";
            if (chipExitG < 20) coolantPressure = "High (300-1000 PSI) - TSC recommended";

            return {
                chipVelocity: Math.round(chipVelocity * 100) / 100,  // m/s
                chipExitG: Math.round(chipExitG),
                recommendedCoolant: coolantPressure,
                chipClearance: chipExitG > 100 ? "Good natural clearing" : "May need air blast assistance"
            };
        },
        /**
         * Calculate safe maximum RPM for tool assembly
         * Based on mass, balance, and insert retention
         * @param {number} toolDia - Tool diameter (mm)
         * @param {number} toolLength - Overall tool length (mm)
         * @param {string} holderType - 'er', 'shrink', 'hydraulic', 'collet'
         * @param {boolean} hasInserts - Whether tool has indexable inserts
         * @returns {object} Maximum safe RPM analysis
         */
        calculateMaxSafeRpm: function(toolDia, toolLength, holderType = 'er', hasInserts = false) {
            // Estimated tool mass (simplified)
            const toolMass = 0.0078 * Math.PI * (toolDia/2)**2 * toolLength / 1000;  // kg (steel density)

            // Balance quality factor by holder type
            const holderFactors = {
                'er': 0.8,
                'collet': 0.75,
                'shrink': 1.0,
                'hydraulic': 0.95,
                'milling_chuck': 0.7
            };
            const factor = holderFactors[holderType] || 0.75;

            // Base max RPM calculation (empirical formula)
            let maxRpm = 600000 / toolDia * factor;  // Simplified rule of thumb

            // Adjust for tool length (L/D ratio)
            const ldRatio = toolLength / toolDia;
            if (ldRatio > 4) maxRpm *= 0.8;
            if (ldRatio > 6) maxRpm *= 0.6;
            if (ldRatio > 8) maxRpm *= 0.4;

            // Insert retention limit (typically 50,000 RPM for 10mm radius)
            if (hasInserts) {
                const insertLimit = Math.sqrt(500 * this.GRAVITY / ((toolDia/2)/1000)) * 60 / (2 * Math.PI);
                maxRpm = Math.min(maxRpm, insertLimit);
            }
            // Balance grade required
            const balanceReq = this.calculateBalanceGrade(maxRpm, toolMass);

            return {
                maxRpm: Math.round(maxRpm / 100) * 100,  // Round to nearest 100
                estimatedMass: Math.round(toolMass * 1000),  // grams
                ldRatio: Math.round(ldRatio * 10) / 10,
                balanceGrade: balanceReq.recommendedGrade,
                holderType: holderType,
                warnings: ldRatio > 5 ? ["High L/D ratio - consider reduced speeds or supported setup"] : []
            };
        },
        /**
         * Calculate optimal feed rate based on machine dynamics
         * Accounts for acceleration limits, corner performance
         * @param {number} baseFeed - Programmed feed rate (IPM)
         * @param {number} pathLength - Segment length (inches)
         * @param {number} nextAngle - Angle to next segment (degrees)
         * @param {object} machineSpec - Machine acceleration specs
         * @returns {object} Optimized feed recommendation
         */
        optimizeFeedForDynamics: function(baseFeed, pathLength, nextAngle, machineSpec = null) {
            const spec = machineSpec || this.MACHINE_ACCELERATION.vmc_standard;
            const maxAccelG = Math.min(spec.x, spec.y);

            // Check if segment is long enough to reach full speed
            // s = v²/(2a) for accel + decel
            const maxAccel = maxAccelG * this.GRAVITY_IPM;  // in/s²
            const minLength = 2 * ((baseFeed/60)**2) / (2 * maxAccel);  // inches

            let optimizedFeed = baseFeed;
            let limited = false;
            let reason = "";

            // Limit by segment length
            if (pathLength < minLength) {
                optimizedFeed = 60 * Math.sqrt(pathLength * maxAccel);
                limited = true;
                reason = "Short segment";
            }
            // Limit by corner angle
            if (nextAngle < 150) {
                const cornerAnalysis = this.calculateCornerDynamics(optimizedFeed, nextAngle, maxAccelG);
                if (optimizedFeed > cornerAnalysis.maxSafeFeed) {
                    optimizedFeed = cornerAnalysis.maxSafeFeed;
                    limited = true;
                    reason = `${nextAngle}° corner`;
                }
            }
            return {
                originalFeed: baseFeed,
                optimizedFeed: Math.round(optimizedFeed),
                limited: limited,
                reason: reason,
                efficiency: Math.round((optimizedFeed / baseFeed) * 100)
            };
        }
    };
    // POST PROCESSOR COMPARISON ENGINE

    let uploadedPostAnalysis = null;
    let optimizedPostAnalysis = null;
    let postModifications = [];

    /**
     * Analyze uploaded post processor for comparison
     */
    function analyzeUploadedPost(postContent) {
        const analysis = {
            // Basic structure
            hasPercentSigns: /^%/.test(postContent) && /%\s*$/.test(postContent),
            hasProgramNumber: /O\d{4}/.test(postContent),
            hasLineNumbers: /N\d+/.test(postContent),

            // Safety blocks
            hasSafeStart: /G28|G53\s*Z/.test(postContent),
            hasSafeEnd: /M30|M02/.test(postContent),
            hasModalCancels: /G40.*G49|G49.*G40/.test(postContent),
            hasG80Cancel: /G80/.test(postContent),
            hasG17Plane: /G17/.test(postContent),

            // HSM features
            hasG187: /G187/.test(postContent),
            hasG05_1: /G05\.1/.test(postContent),
            hasG131: /G131/.test(postContent),
            hasCYCLE832: /CYCLE832/.test(postContent),

            // Coolant
            hasFloodCoolant: /M0?8(?!\d)/.test(postContent),
            hasTSC: /M88|M51/.test(postContent),
            hasAirBlast: /M83|M77/.test(postContent),

            // Tool management
            hasToolPreload: /T\d+(?=.*T\d+\s*M0?6)/s.test(postContent),
            hasToolComments: /\(TOOL|\(T\d+/.test(postContent),
            hasToolLengthComp: /G43/.test(postContent),

            // 5-axis
            hasTCPC: /G43\.4|G234|G169|TRAORI|M128/.test(postContent),
            hasDWO: /G254|G255/.test(postContent),
            hasInverseTime: /G93/.test(postContent),

            // Probing
            hasProbing: /G65\s*P9[78]|G36|CYCLE97/.test(postContent),

            // Subprograms
            hasSubprograms: /M98|M97|CALL/.test(postContent),
            hasMacros: /G65|G66/.test(postContent),

            // Advanced
            hasComments: /\(.*\)/.test(postContent),
            hasSSV: /SSV|M695/.test(postContent),
            hasChipConveyor: /M31|M32|M33/.test(postContent),

            // Code quality
            lineCount: postContent.split('\n').length,
            hasBlankLines: /\n\s*\n/.test(postContent),

            // Statistics
            rapidCount: (postContent.match(/G0(?:0)?(?=\s)/g) || []).length,
            linearCount: (postContent.match(/G0?1(?=\s)/g) || []).length,
            arcCount: (postContent.match(/G0?[23](?=\s)/g) || []).length
        };
        // Calculate optimization score
        analysis.score = calculatePostScore(analysis);

        return analysis;
    }
    /**
     * Calculate post processor optimization score
     */
    function calculatePostScore(analysis) {
        let score = 0;
        let maxScore = 0;

        // Safety (20 points)
        maxScore += 20;
        if (analysis.hasSafeStart) score += 5;
        if (analysis.hasSafeEnd) score += 3;
        if (analysis.hasModalCancels) score += 5;
        if (analysis.hasG80Cancel) score += 3;
        if (analysis.hasG17Plane) score += 4;

        // HSM (20 points)
        maxScore += 20;
        if (analysis.hasG187 || analysis.hasG05_1 || analysis.hasG131 || analysis.hasCYCLE832) score += 20;

        // Coolant (10 points)
        maxScore += 10;
        if (analysis.hasFloodCoolant) score += 4;
        if (analysis.hasTSC) score += 6;

        // Tool Management (15 points)
        maxScore += 15;
        if (analysis.hasToolPreload) score += 5;
        if (analysis.hasToolComments) score += 5;
        if (analysis.hasToolLengthComp) score += 5;

        // 5-Axis (15 points)
        maxScore += 15;
        if (analysis.hasTCPC) score += 10;
        if (analysis.hasDWO) score += 5;

        // Advanced (10 points)
        maxScore += 10;
        if (analysis.hasComments) score += 3;
        if (analysis.hasSubprograms) score += 4;
        if (analysis.hasChipConveyor) score += 3;

        // Structure (10 points)
        maxScore += 10;
        if (analysis.hasPercentSigns) score += 3;
        if (analysis.hasProgramNumber) score += 4;
        if (analysis.hasLineNumbers) score += 3;

        return Math.round((score / maxScore) * 100);
    }
    /**
     * Generate optimized post analysis based on machine selection
     */
    function generateOptimizedPostAnalysis() {
        const machineId = document.getElementById('machineSelect')?.value;

        return {
            hasPercentSigns: true,
            hasProgramNumber: true,
            hasLineNumbers: true,
            hasSafeStart: true,
            hasSafeEnd: true,
            hasModalCancels: true,
            hasG80Cancel: true,
            hasG17Plane: true,
            hasG187: machineId?.includes('haas'),
            hasG05_1: machineId?.includes('fanuc') || machineId?.includes('mazak'),
            hasG131: machineId?.includes('okuma'),
            hasCYCLE832: machineId?.includes('siemens') || machineId?.includes('dmg'),
            hasFloodCoolant: true,
            hasTSC: true,
            hasAirBlast: true,
            hasToolPreload: true,
            hasToolComments: true,
            hasToolLengthComp: true,
            hasTCPC: true,
            hasDWO: machineId?.includes('haas'),
            hasInverseTime: true,
            hasProbing: true,
            hasSubprograms: true,
            hasMacros: true,
            hasComments: true,
            hasSSV: true,
            hasChipConveyor: true,
            score: 100,
            // G-Force optimizations
            gforceOptimized: true,
            dynamicFeedControl: true,
            cornerDeceleration: true,
            jerkLimiting: true,
            lookAheadOptimized: true
        };
    }
    /**
     * Show post processor comparison panel
     */
    function showPostComparison() {
        const section = document.getElementById('postComparisonSection');
        if (!section) return;

        section.style.display = 'block';

        // Scroll to comparison
        section.scrollIntoView({ behavior: 'smooth', block: 'start' });

        // Populate comparison data
        populateFeatureComparison();
        populateDetailedOptimizations();
        updateGForceAnalysis();
        updateCodeSamples();
    }
    /**
     * Hide post comparison panel
     */
    function hidePostComparison() {
        const section = document.getElementById('postComparisonSection');
        if (section) section.style.display = 'none';
    }
    /**
     * Populate feature comparison table
     */
    function populateFeatureComparison() {
        const container = document.getElementById('featureComparisonRows');
        if (!container) return;

        const original = uploadedPostAnalysis || {
            hasSafeStart: true, hasSafeEnd: true, hasModalCancels: false, hasG80Cancel: false, hasG17Plane: true,
            hasG187: false, hasG05_1: false, hasG131: false, hasCYCLE832: false,
            hasFloodCoolant: true, hasTSC: false, hasAirBlast: false,
            hasToolPreload: false, hasToolComments: false, hasToolLengthComp: true,
            hasTCPC: false, hasDWO: false, hasInverseTime: false,
            hasProbing: false, hasSubprograms: false, hasMacros: false,
            hasSSV: false, hasChipConveyor: false
        };
        const optimized = generateOptimizedPostAnalysis();

        const features = [
            { name: "Safe Start Blocks (G28/G53)", key: "hasSafeStart", category: "Safety" },
            { name: "Safe End Sequence", key: "hasSafeEnd", category: "Safety" },
            { name: "Modal Cancels (G40/G49)", key: "hasModalCancels", category: "Safety" },
            { name: "Canned Cycle Cancel (G80)", key: "hasG80Cancel", category: "Safety" },
            { name: "Plane Selection (G17)", key: "hasG17Plane", category: "Safety" },
            { name: "HSM Smoothing (G187/G05.1/G131)", key: "hasG187", category: "HSM", optimizedKey: "hasG187" },
            { name: "Through-Spindle Coolant", key: "hasTSC", category: "Coolant" },
            { name: "Air Blast Chip Clearing", key: "hasAirBlast", category: "Coolant" },
            { name: "Tool Preloading", key: "hasToolPreload", category: "Tools" },
            { name: "Tool Description Comments", key: "hasToolComments", category: "Tools" },
            { name: "5-Axis TCP Control", key: "hasTCPC", category: "5-Axis" },
            { name: "Dynamic Work Offset (DWO)", key: "hasDWO", category: "5-Axis" },
            { name: "Inverse Time Feed (G93)", key: "hasInverseTime", category: "5-Axis" },
            { name: "Probing Cycles", key: "hasProbing", category: "Advanced" },
            { name: "Subprogram Support", key: "hasSubprograms", category: "Advanced" },
            { name: "Macro Support", key: "hasMacros", category: "Advanced" },
            { name: "Spindle Speed Variation (SSV)", key: "hasSSV", category: "Advanced" },
            { name: "Chip Conveyor Control", key: "hasChipConveyor", category: "Auxiliary" },
            { name: "G-Force Optimized Feeds", key: "gforceOptimized", category: "Dynamics", originalValue: false },
            { name: "Dynamic Corner Deceleration", key: "cornerDeceleration", category: "Dynamics", originalValue: false },
            { name: "Jerk-Limited Motion", key: "jerkLimiting", category: "Dynamics", originalValue: false },
            { name: "Look-Ahead Optimization", key: "lookAheadOptimized", category: "Dynamics", originalValue: false }
        ];

        let html = '';
        let currentCategory = '';

        features.forEach(feature => {
            // Category header
            if (feature.category !== currentCategory) {
                currentCategory = feature.category;
                html += `
                    <div style="display: grid; grid-template-columns: 2fr 1fr 1fr; background: rgba(99,102,241,0.1); padding: 6px 15px;">
                        <div style="font-size: 10px; font-weight: 600; color: var(--primary);">${currentCategory}</div>
                        <div></div>
                        <div></div>
                    </div>
                `;
            }
            const origValue = feature.originalValue !== undefined ? feature.originalValue : original[feature.key];
            const optValue = optimized[feature.optimizedKey || feature.key] || optimized[feature.key];

            const origIcon = origValue ? '✓' : '✕';
            const origColor = origValue ? 'var(--success)' : 'var(--error)';
            const optIcon = optValue ? '✓' : '✕';
            const optColor = optValue ? 'var(--success)' : 'var(--error)';

            const improved = !origValue && optValue;

            html += `
                <div style="display: grid; grid-template-columns: 2fr 1fr 1fr; padding: 8px 15px; border-bottom: 1px solid var(--border-color); ${improved ? 'background: rgba(16,185,129,0.05);' : ''}">
                    <div style="font-size: 11px; color: var(--text-secondary);">
                        ${feature.name}
                        ${improved ? '<span style="margin-left: 6px; font-size: 9px; color: var(--success); font-weight: 600;">NEW!</span>' : ''}
                    </div>
                    <div style="text-align: center; font-size: 14px; color: ${origColor};">${origIcon}</div>
                    <div style="text-align: center; font-size: 14px; color: ${optColor};">${optIcon}</div>
                </div>
            `;
        });

        container.innerHTML = html;
    }
