    // Update coolant products dropdown based on selected supplier
    function updateCoolantProducts() {
        const supplierSelect = document.getElementById('coolantSupplier');
        const productSelect = document.getElementById('coolantProduct');
        const coolantInfo = document.getElementById('coolantInfo');
        const buyBtn = document.getElementById('buyCoolantBtn');

        const supplierId = supplierSelect.value;

        productSelect.innerHTML = '<option value="">Select product...</option>';
        if (coolantInfo) coolantInfo.style.display = 'none';
        if (buyBtn) buyBtn.style.display = 'none';
        selectedCoolant = null;

        if (!supplierId || !COOLANT_DATABASE[supplierId]) return;

        const supplier = COOLANT_DATABASE[supplierId];

        // Group products by type
        const products = supplier.products;
        const productKeys = Object.keys(products);

        productKeys.forEach(key => {
            const product = products[key];
            const opt = document.createElement('option');
            opt.value = key;
            opt.textContent = `${product.name} (${product.type})`;
            productSelect.appendChild(opt);
        });
    }
    // Update coolant info display when product is selected
    function updateCoolantInfo() {
        const supplierSelect = document.getElementById('coolantSupplier');
        const productSelect = document.getElementById('coolantProduct');
        const coolantInfo = document.getElementById('coolantInfo');
        const buyBtn = document.getElementById('buyCoolantBtn');

        const supplierId = supplierSelect.value;
        const productId = productSelect.value;

        if (!supplierId || !productId || !COOLANT_DATABASE[supplierId]) {
            if (coolantInfo) coolantInfo.style.display = 'none';
            if (buyBtn) buyBtn.style.display = 'none';
            selectedCoolant = null;
            calculate();
            return;
        }
        const product = COOLANT_DATABASE[supplierId].products[productId];
        if (!product) {
            if (coolantInfo) coolantInfo.style.display = 'none';
            if (buyBtn) buyBtn.style.display = 'none';
            selectedCoolant = null;
            calculate();
            return;
        }
        // Store selected coolant
        selectedCoolant = {
            supplier: supplierId,
            product: productId,
            data: product
        };
        // Update display
        document.getElementById('coolantInfoName')?.textContent = product.name;
        document.getElementById('coolantInfoType')?.textContent = `${product.type} • ${COOLANT_DATABASE[supplierId].name}`;
        document.getElementById('coolantInfoConcentration')?.textContent = product.concentration;
        document.getElementById('coolantInfoDesc')?.textContent = product.description;
        document.getElementById('coolantInfoBestFor')?.textContent = product.bestFor;

        if (coolantInfo) {
            coolantInfo.style.display = 'block';
            coolantInfo.style.animation = 'fadeIn 0.2s ease-out';
        }
        // Show Buy button
        if (buyBtn) {
            buyBtn.style.display = 'block';
        }
        // Recalculate with new coolant modifiers
        calculate();
    }
