    let selectedMistProduct = null;

    function updateMistSupplierVisibility() {
        const settingsSection = document.getElementById('mistSettingsSection');
        const supplierSection = document.getElementById('mistSupplierSection');
        const easyModePreview = document.getElementById('mistEasyModePreview');
        const buyBtn = document.getElementById('buyMistBtn');

        const isMistSelected = activeFeatures.includes('coolant_mist');

        // In Easy Mode, show preview and basic settings
        if (calculatorMode === 'easy') {
            if (supplierSection) supplierSection.style.display = 'none';
            if (settingsSection) settingsSection.style.display = isMistSelected ? 'block' : 'none';
            if (easyModePreview) easyModePreview.style.display = isMistSelected ? 'block' : 'none';

            // Clear supplier selection
            const supplierEl = document.getElementById('mistSupplier');
            const productEl = document.getElementById('mistProduct');
            if (supplierEl) supplierEl.value = '';
            if (productEl) productEl.innerHTML = '<option value="">Select product...</option>';
            const infoEl = document.getElementById('mistInfo');
            const recEl = document.getElementById('mistRecommendation');
            if (infoEl) infoEl.style.display = 'none';
            if (recEl) recEl.style.display = 'none';
            if (buyBtn) buyBtn.style.display = 'none';
            selectedMistProduct = null;

            if (isMistSelected) updateMistSettings();
            return;
        }
        // Pro Mode: Show full sections
        if (easyModePreview) easyModePreview.style.display = 'none';

        if (isMistSelected) {
            if (settingsSection) settingsSection.style.display = 'block';
            if (supplierSection) supplierSection.style.display = 'block';
            updateMistSettings();
        } else {
            if (settingsSection) settingsSection.style.display = 'none';
            if (supplierSection) supplierSection.style.display = 'none';

            // Clear selections
            const supplierEl = document.getElementById('mistSupplier');
            const productEl = document.getElementById('mistProduct');
            if (supplierEl) supplierEl.value = '';
            if (productEl) productEl.innerHTML = '<option value="">Select product...</option>';
            const infoEl = document.getElementById('mistInfo');
            const recEl = document.getElementById('mistRecommendation');
            if (infoEl) infoEl.style.display = 'none';
            if (recEl) recEl.style.display = 'none';
            if (buyBtn) buyBtn.style.display = 'none';
            selectedMistProduct = null;
        }
    }
    function updateMistSettings() {
        const typeSelect = document.getElementById('mistType');
        const pressureSelect = document.getElementById('mistPressure');
        if (!typeSelect || !pressureSelect) return;

        const type = typeSelect.value;
        const pressure = parseInt(pressureSelect.value);

        const typeData = MIST_SETTINGS_DATA[type];
        const pressureData = MIST_PRESSURE_DATA[pressure];

        if (!typeData || !pressureData) return;

        // Update display
        const coverageEl = document.getElementById('mistCoverage');
        const consumptionEl = document.getElementById('mistConsumption');
        const bestForEl = document.getElementById('mistBestFor');
        const coolingEl = document.getElementById('mistCooling');

        if (coverageEl) coverageEl.textContent = pressureData.coverage;
        if (consumptionEl) consumptionEl.textContent = pressureData.consumption;
        if (bestForEl) bestForEl.textContent = typeData.bestFor;
        if (coolingEl) coolingEl.textContent = typeData.cooling;

        // Color code based on pressure
        if (coverageEl) {
            if (pressure >= 70) {
                coverageEl.style.color = '#00ff88';
            } else if (pressure >= 50) {
                coverageEl.style.color = '#87ceeb';
            } else {
                coverageEl.style.color = 'var(--text-muted)';
            }
        }
        calculate();
    }
    function updateMistProducts() {
        const supplierSelect = document.getElementById('mistSupplier');
        const productSelect = document.getElementById('mistProduct');
        const buyBtn = document.getElementById('buyMistBtn');

        if (!supplierSelect || !productSelect) return;

        const supplier = supplierSelect.value;
        productSelect.innerHTML = '<option value="">Select product...</option>';

        // Hide info and buy button when changing supplier
        const infoEl = document.getElementById('mistInfo');
        const recEl = document.getElementById('mistRecommendation');
        if (infoEl) infoEl.style.display = 'none';
        if (recEl) recEl.style.display = 'none';
        if (buyBtn) buyBtn.style.display = 'none';
        selectedMistProduct = null;

        if (!supplier || !MIST_PRODUCTS[supplier]) return;

        const products = MIST_PRODUCTS[supplier].products;
        products.forEach(product => {
            const option = document.createElement('option');
            option.value = product.id;
            option.textContent = `${product.name} (${product.type})`;
            productSelect.appendChild(option);
        });
    }
    function updateMistInfo() {
        const supplierSelect = document.getElementById('mistSupplier');
        const productSelect = document.getElementById('mistProduct');
        const infoEl = document.getElementById('mistInfo');
        const buyBtn = document.getElementById('buyMistBtn');

        if (!supplierSelect || !productSelect || !infoEl) return;

        const supplier = supplierSelect.value;
        const productId = productSelect.value;

        if (!productId || !MIST_PRODUCTS[supplier]) {
            infoEl.style.display = 'none';
            if (buyBtn) buyBtn.style.display = 'none';
            selectedMistProduct = null;
            return;
        }
        const product = MIST_PRODUCTS[supplier].products.find(p => p.id === productId);
        if (!product) return;

        selectedMistProduct = product;

        // Update info display
        document.getElementById('mistInfoName')?.textContent = product.name;
        document.getElementById('mistInfoType')?.textContent = `${MIST_PRODUCTS[supplier].country} ${MIST_PRODUCTS[supplier].name} • ${product.type}`;
        document.getElementById('mistInfoConcentration')?.textContent = product.concentration;
        document.getElementById('mistInfoDesc')?.textContent = product.desc;
        document.getElementById('mistInfoBestFor')?.textContent = product.bestFor;

        infoEl.style.display = 'block';
        if (buyBtn) buyBtn.style.display = 'inline-block';
    }
    function showMistRecommendation() {
        const recEl = document.getElementById('mistRecommendation');
        if (!recEl) return;

        // Get current material
        const materialSelect = document.getElementById('materialSelect');
        const material = materialSelect ? materialSelect.value : 'aluminum_6061';

        // Simple material-based recommendations
        let recommendation = {
            supplier: 'kool_mist',
            product: 'km_77',
            reason: 'Excellent for aluminum and non-ferrous metals'
        };
        if (material.includes('steel') || material.includes('4140') || material.includes('1018')) {
            recommendation = {
                supplier: 'kool_mist',
                product: 'km_78',
                reason: 'Heavy-duty formula optimized for steel machining'
            };
        } else if (material.includes('stainless') || material.includes('316') || material.includes('304')) {
            recommendation = {
                supplier: 'blaser',
                product: 'blasocut_2000',
                reason: 'Premium Swiss formula for demanding stainless steel'
            };
        } else if (material.includes('titanium') || material.includes('inconel')) {
            recommendation = {
                supplier: 'master',
                product: 'trim_mist',
                reason: 'Low-foam, high-lubricity for exotic alloys'
            };
        } else if (material.includes('brass') || material.includes('copper') || material.includes('bronze')) {
            recommendation = {
                supplier: 'hangsterfers',
                product: 'hang_cool',
                reason: 'Low-residue formula perfect for copper alloys'
            };
        }
        const supplierData = MIST_PRODUCTS[recommendation.supplier];
        const productData = supplierData?.products.find(p => p.id === recommendation.product);

        if (!productData) return;

        recEl.innerHTML = `
            <div style="display: flex; align-items: start; gap: 10px;">
                <span style="font-size: 20px;">💡</span>
                <div style="flex: 1;">
                    <div style="font-size: 12px; font-weight: 600; color: #87ceeb; margin-bottom: 4px;">
                        Recommended: ${productData.name}
                    </div>
                    <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 6px;">
                        ${supplierData.country} ${supplierData.name} • ${productData.type}
                    </div>
                    <div style="font-size: 10px; color: var(--text-light); margin-bottom: 8px;">
                        ${recommendation.reason}
                    </div>
                    <button onclick="applyMistRecommendation('${recommendation.supplier}', '${recommendation.product}')"
                            style="background: linear-gradient(135deg, #87ceeb 0%, #5ba3c6 100%); color: #0a1628;
                                   border: none; padding: 6px 12px; border-radius: 4px; font-size: 10px;
                                   font-weight: 600; cursor: pointer;">
                        Apply This Selection
                    </button>
                </div>
            </div>
        `;
        recEl.style.display = 'block';
    }
    function applyMistRecommendation(supplier, productId) {
        const supplierSelect = document.getElementById('mistSupplier');
        if (supplierSelect) {
            supplierSelect.value = supplier;
            updateMistProducts();

            setTimeout(() => {
                const productSelect = document.getElementById('mistProduct');
                if (productSelect) {
                    productSelect.value = productId;
                    updateMistInfo();
                }
            }, 50);
        }
    }
    function showMistPurchaseLinks() {
        if (!selectedMistProduct) return;

        // Show purchase modal or links
        const supplierSelect = document.getElementById('mistSupplier');
        const supplier = supplierSelect ? supplierSelect.value : '';
        const supplierData = MIST_PRODUCTS[supplier];

        if (!supplierData) return;

        alert(`Search for "${selectedMistProduct.name}" from ${supplierData.name}\n\nCheck with your local industrial supplier or visit the manufacturer website.`);
    }
    function getMistFeedBoost() {
        if (!activeFeatures.includes('coolant_mist')) return 1.0;
        const pressureSelect = document.getElementById('mistPressure');
        const pressure = pressureSelect ? parseInt(pressureSelect.value) : 50;
        const data = MIST_PRESSURE_DATA[pressure];
        return data ? data.feedBoost : 1.0;
    }
