    // Map control types to their tolerance settings
    function getControlToleranceSettings(machineId) {
        if (!machineId) return CONTROL_TOLERANCE_SETTINGS.generic;

        const controlTypes = detectControlType(machineId);

        // Priority order for tolerance settings
        const priorityOrder = ['haas', 'okuma', 'mazak', 'makino', 'hurco', 'fanuc', 'siemens', 'heidenhain', 'mitsubishi', 'brother', 'dmg_mori'];

        for (const control of priorityOrder) {
            if (controlTypes.includes(control) && CONTROL_TOLERANCE_SETTINGS[control]) {
                return CONTROL_TOLERANCE_SETTINGS[control];
            }
        }
        // Check for siemens/heidenhain based on control string
        const machine = MACHINE_DATABASE.machines[machineId];
        if (machine) {
            const manufacturer = MACHINE_DATABASE.manufacturers[machine.manufacturer];
            const controlString = (machine.control || manufacturer?.control || '').toLowerCase();

            if (controlString.includes('siemens') || controlString.includes('840d')) {
                return CONTROL_TOLERANCE_SETTINGS.siemens;
            }
            if (controlString.includes('heidenhain') || controlString.includes('tnc')) {
                return CONTROL_TOLERANCE_SETTINGS.heidenhain;
            }
        }
        return CONTROL_TOLERANCE_SETTINGS.generic;
    }
    // GLOBAL STATE
    let selectedHolder = null;
    let filteredHolders = [];
    let currentMachine = null;  // Will be set by filterMachines on page load
    let currentEDM = null;      // Selected EDM machine (sinker EDM mode)
    let activeFeatures = ['coolant_flood'];  // Default to flood coolant
    let toleranceMode = 'medium';            // Default tolerance mode

    // Tool Holder UI State
    holderUnitSystem = 'inch';           // 'inch' or 'metric'
    let currentHolderView = 'side';          // 'side', 'front', or '3d'
    let selectedBoreCategory = '';           // Bore diameter filter category
    let selectedProjectionCategory = '';     // Projection length filter category
    let selectedModelSeries = '';            // Model/Series filter

    // MACHINE MODE STATE (Mill vs Lathe)
    machineMode = 'mill';                 // 'mill' or 'lathe'

    // LATHE STATE VARIABLES
    let currentLathe = null;                  // Selected lathe machine
    let selectedTurningInsert = null;         // Selected turning insert (CNMG, WNMG, etc.)
    let selectedTurningHolder = null;         // Selected turning tool holder
    let latheOperationType = 'od_turning';    // Current lathe operation type
    let latheUnitSystem = 'inch';             // 'inch' or 'metric' for lathe
    let latheActiveFeatures = ['coolant_flood']; // Active lathe features

    // FEATURE MANAGEMENT
    function toggleFeature(featureId, btn) {
        const feature = FEATURE_DEFINITIONS[featureId];
        if (!feature) return;

        // Block all motion control features in Easy Mode
        if (calculatorMode === 'easy' && feature.category === 'motion') {
            return; // Do nothing in easy mode
        }
        // In Pro Mode, verify feature is available for selected machine's control
        if (calculatorMode === 'pro' && feature.category === 'motion') {
            const machineId = document.getElementById('machineSelect')?.value;
            if (machineId) {
                const availableFeatures = getAvailableMotionFeatures(machineId);
                if (!availableFeatures.includes(featureId)) {
                    return; // Feature not available for this control
                }
            }
        }
        // Check if this is an exclusive feature (like coolant)
        if (feature.exclusive) {
            // Remove all other features in the same category
            activeFeatures = activeFeatures.filter(f => {
                const def = FEATURE_DEFINITIONS[f];
                return !def || def.category !== feature.category;
            });

            // Update button states for this category
            document.querySelectorAll(`.feature-btn[data-feature^="coolant_"]`).forEach(b => {
                b.classList.remove('active');
            });
        }
        // Toggle this feature
        const index = activeFeatures.indexOf(featureId);
        if (index === -1) {
            activeFeatures.push(featureId);
            btn.classList.add('active');
        } else if (!feature.exclusive) {
            // Can only toggle off non-exclusive features
            activeFeatures.splice(index, 1);
            btn.classList.remove('active');
        } else {
            // For exclusive features, clicking the active one keeps it active
            activeFeatures.push(featureId);
            btn.classList.add('active');
        }
        // Show feature info
        showFeatureInfo(featureId);

        // Update coolant supplier visibility if coolant changed
        if (feature.category === 'coolant') {
            updateCoolantSupplierVisibility();
            updateMqlSupplierVisibility();
            updateTscPressureVisibility();
            updateMistSupplierVisibility();
        }
        // Update modifiers display and recalculate
        updateModifiersDisplay();
        calculate();
    }
    function setToleranceMode(mode, btn) {
        // Check if this is a pro-only mode in easy mode
        if (calculatorMode === 'easy') {
            const basicModes = ['rough', 'medium', 'finish'];
            if (!basicModes.includes(mode)) {
                showProUpgradeHint();
                return;
            }
        }
        const basicModes = ['rough', 'medium', 'finish'];

        // If clicking on currently active advanced mode, toggle back to medium
        if (toleranceMode === mode && !basicModes.includes(mode)) {
            mode = 'medium';
        }
        toleranceMode = mode;

        // Update button states
        document.querySelectorAll('.tolerance-btn').forEach(b => b.classList.remove('active'));

        // Find and activate the correct button
        const activeBtn = document.querySelector(`.tolerance-btn[data-tolerance="${mode}"]`);
        if (activeBtn) {
            activeBtn.classList.add('active');
        } else if (btn && toleranceMode === mode) {
            btn.classList.add('active');
        }
        // Update G-code display
        updateToleranceGCodeDisplay();

        // Show tolerance info panel
        showToleranceInfo(mode);

        updateModifiersDisplay();
        calculate();
    }
    function showToleranceInfo(mode) {
        const infoPanel = document.getElementById('toleranceInfo');
        if (!infoPanel) return;

        const machineId = document.getElementById('machineSelect')?.value;
        let modeData = null;
        let controlName = 'Standard';

        // Get control-specific mode data in Pro mode
        if (calculatorMode === 'pro' && machineId) {
            const settings = getControlToleranceSettings(machineId);
            if (settings && settings.modes && settings.modes[mode]) {
                modeData = settings.modes[mode];
                controlName = settings.name;
            }
        }
        // Fall back to basic TOLERANCE_MODES for Easy mode
        if (!modeData && TOLERANCE_MODES[mode]) {
            const basic = TOLERANCE_MODES[mode];
            modeData = {
                name: basic.name,
                icon: basic.icon,
                code: mode === 'rough' ? 'G64' : mode === 'medium' ? 'G64 P0.05' : 'G61',
                description: basic.description,
                tolerance: basic.tolerance
            };
            controlName = 'Generic';
        }
        if (!modeData) {
            infoPanel.style.display = 'none';
            return;
        }
        // Calculate feed and finish effects based on tolerance
        const baseTolerance = 0.002; // Medium baseline
        const ratio = baseTolerance / (modeData.tolerance || baseTolerance);
        const feedEffect = ratio > 1 ? `+${Math.round((ratio - 1) * 15)}%` : `-${Math.round((1 - ratio) * 15)}%`;
        const finishEffect = ratio > 1 ? `-${Math.round((ratio - 1) * 10)}%` : `+${Math.round((1 - ratio) * 20)}%`;

        // Update info panel elements
        document.getElementById('toleranceInfoIcon')?.textContent = modeData.icon || '⚙️';
        document.getElementById('toleranceInfoName')?.textContent = modeData.name + (calculatorMode === 'pro' ? ` (${controlName})` : '');
        document.getElementById('toleranceInfoCode')?.textContent = modeData.code;
        document.getElementById('toleranceInfoDesc')?.textContent = modeData.description;
        document.getElementById('toleranceInfoValue')?.textContent = `±${modeData.tolerance}"`;

        const feedEl = document.getElementById('toleranceInfoFeed');
        feedEl.textContent = feedEffect;
        feedEl.style.color = feedEffect.startsWith('+') ? 'var(--success)' : 'var(--danger)';

        const finishEl = document.getElementById('toleranceInfoFinish');
        finishEl.textContent = finishEffect;
        finishEl.style.color = finishEffect.startsWith('+') ? 'var(--success)' : 'var(--danger)';

        // Show the panel with animation
        infoPanel.style.display = 'block';
        infoPanel.style.animation = 'fadeIn 0.2s ease-out';
    }
    function updateToleranceGCodeDisplay() {
        const gcodeLabel = document.getElementById('toleranceGCode');
        if (!gcodeLabel) return;

        if (calculatorMode === 'easy') {
            gcodeLabel.style.display = 'none';
            return;
        }
        const machineId = document.getElementById('machineSelect')?.value;
        const settings = getControlToleranceSettings(machineId);

        if (settings && settings.modes && settings.modes[toleranceMode]) {
            const mode = settings.modes[toleranceMode];
            gcodeLabel.textContent = mode.code;
            gcodeLabel.style.display = 'inline';
            gcodeLabel.title = mode.description;
        } else {
            gcodeLabel.style.display = 'none';
        }
    }
    function updateToleranceModeButtons() {
        const toleranceContainer = document.getElementById('toleranceMode');
        const toleranceAdvanced = document.getElementById('toleranceAdvanced');
        const toleranceLabel = document.getElementById('toleranceLabel');
        const toleranceProBadge = document.getElementById('toleranceProBadge');
        const toleranceGCode = document.getElementById('toleranceGCode');

        if (!toleranceContainer) return;

        const machineId = document.getElementById('machineSelect')?.value;

        // Easy Mode: Show basic options only (all functional)
        if (calculatorMode === 'easy') {
            if (toleranceProBadge) toleranceProBadge.style.display = 'inline';
            if (toleranceGCode) toleranceGCode.style.display = 'none';

            // Update label
            if (toleranceLabel) {
                toleranceLabel.innerHTML = `Smooth Tolerance Mode <span id="toleranceProBadge_2" style="font-size: 9px; padding: 1px 5px; background: rgba(96, 165, 250, 0.2); color: #60a5fa; border-radius: 8px; margin-left: 4px;">PRO</span>`;
            }
            // Show basic options
            toleranceContainer.innerHTML = `
                <button class="feature-btn tolerance-btn ${toleranceMode === 'rough' ? 'active' : ''}" data-tolerance="rough" onclick="setToleranceMode('rough', this)" title="Rough: ±0.005&quot; tolerance, max speed">
                    <span class="feature-icon">🔨</span>
                    <span class="feature-name">Rough</span>
                </button>
                <button class="feature-btn tolerance-btn ${toleranceMode === 'medium' ? 'active' : ''}" data-tolerance="medium" onclick="setToleranceMode('medium', this)" title="Medium: ±0.002&quot; tolerance, balanced">
                    <span class="feature-icon">⚖️</span>
                    <span class="feature-name">Medium</span>
                </button>
                <button class="feature-btn tolerance-btn ${toleranceMode === 'finish' ? 'active' : ''}" data-tolerance="finish" onclick="setToleranceMode('finish', this)" title="Finish: ±0.0005&quot; tolerance, best accuracy">
                    <span class="feature-icon">✨</span>
                    <span class="feature-name">Finish</span>
                </button>
            `;

            // Show preview of advanced options (locked)
            if (toleranceAdvanced) {
                toleranceAdvanced.style.display = 'block';
                toleranceAdvanced.innerHTML = `
                    <div style="display: flex; gap: 6px; flex-wrap: wrap;">
                        <button class="feature-btn pro-only" onclick="showProUpgradeHint()" style="opacity: 0.5; cursor: pointer; flex: 1; min-width: 60px;" title="🔒 Pro ($30/mo) - Control-specific ultra precision">
                            <span class="feature-icon">💎</span>
                            <span class="feature-name">Ultra</span>
                        </button>
                        <button class="feature-btn pro-only" onclick="showProUpgradeHint()" style="opacity: 0.5; cursor: pointer; flex: 1; min-width: 60px;" title="🔒 Pro ($30/mo) - AICC/Nano/SGI modes">
                            <span class="feature-icon">🧠</span>
                            <span class="feature-name">AI Mode</span>
                        </button>
                        <button class="feature-btn pro-only" onclick="showProUpgradeHint()" style="opacity: 0.5; cursor: pointer; flex: 1; min-width: 60px;" title="🔒 Pro ($30/mo) - Surface finish optimization">
                            <span class="feature-icon">🌊</span>
                            <span class="feature-name">Surface</span>
                        </button>
                        <button class="feature-btn" onclick="showProUpgradeHint()" style="background: linear-gradient(135deg, rgba(96, 165, 250, 0.1) 0%, rgba(96, 165, 250, 0.05) 100%); border: 1px dashed rgba(96, 165, 250, 0.4); cursor: pointer; flex: 1; min-width: 60px;" title="Pro ($30/mo) for control-specific codes • 7-day trial">
                            <span class="feature-icon" style="font-size: 12px;">➕</span>
                            <span class="feature-name" style="color: #60a5fa;">More</span>
                        </button>
                    </div>
                `;
            }
            return;
        }
        // Pro Mode: Show control-specific options
        if (toleranceProBadge) toleranceProBadge.style.display = 'none';

        const settings = getControlToleranceSettings(machineId);

        // Update label with control name
        if (toleranceLabel) {
            toleranceLabel.innerHTML = `Smooth Tolerance Mode`;
        }
        // Update G-code label
        if (toleranceGCode && settings) {
            toleranceGCode.textContent = settings.gcode;
            toleranceGCode.style.display = 'inline';
            toleranceGCode.title = `${settings.name}: ${settings.description}`;
        }
        if (!settings || !settings.modes) {
            toleranceContainer.innerHTML = '<div style="color: var(--text-muted); font-size: 10px; text-align: center; padding: 8px;">Select a machine to see tolerance options</div>';
            if (toleranceAdvanced) toleranceAdvanced.style.display = 'none';
            return;
        }
        // Separate basic and advanced modes
        const basicModes = ['rough', 'medium', 'finish'];
        const advancedModes = Object.keys(settings.modes).filter(m => !basicModes.includes(m));

        // Render basic modes
        toleranceContainer.innerHTML = basicModes.map(modeKey => {
            const mode = settings.modes[modeKey];
            if (!mode) return '';
            return `
                <button class="feature-btn tolerance-btn ${toleranceMode === modeKey ? 'active' : ''}"
                        data-tolerance="${modeKey}"
                        onclick="setToleranceMode('${modeKey}', this)"
                        title="${mode.code}: ${mode.description}">
                    <span class="feature-icon">${mode.icon}</span>
                    <span class="feature-name">${mode.name}</span>
                    <span style="position: absolute; bottom: 2px; font-size: 7px; color: var(--text-muted);">${mode.code.split(' ')[0]}</span>
                </button>
            `;
        }).join('');

        // Render advanced modes
        if (advancedModes.length > 0 && toleranceAdvanced) {
            toleranceAdvanced.style.display = 'block';
            toleranceAdvanced.innerHTML = `
                <div style="font-size: 9px; color: var(--text-muted); margin-bottom: 6px;">Advanced (${settings.name})</div>
                <div style="display: grid; grid-template-columns: repeat(${Math.min(advancedModes.length, 4)}, 1fr); gap: 6px;">
                    ${advancedModes.map(modeKey => {
                        const mode = settings.modes[modeKey];
                        if (!mode) return '';
                        return `
                            <button class="feature-btn tolerance-btn ${toleranceMode === modeKey ? 'active' : ''}"
                                    data-tolerance="${modeKey}"
                                    onclick="setToleranceMode('${modeKey}', this)"
                                    title="${mode.code}: ${mode.description}"
                                    style="background: linear-gradient(135deg, rgba(96, 165, 250, 0.1) 0%, rgba(96, 165, 250, 0.05) 100%);">
                                <span class="feature-icon">${mode.icon}</span>
                                <span class="feature-name">${mode.name}</span>
                                <span style="position: absolute; bottom: 2px; font-size: 7px; color: #60a5fa;">${mode.code.split(' ')[0].substring(0, 8)}</span>
                            </button>
                        `;
                    }).join('')}
                </div>
            `;
        } else if (toleranceAdvanced) {
            toleranceAdvanced.style.display = 'none';
        }
        // Update G-code display for current mode
        updateToleranceGCodeDisplay();

        // Show tolerance info for current selection
        showToleranceInfo(toleranceMode);
    }
    function showFeatureInfo(featureId) {
        const feature = FEATURE_DEFINITIONS[featureId];
        if (!feature) return;

        const infoPanel = document.getElementById('featureInfo');
        document.getElementById('featureInfoName')?.textContent = feature.icon + ' ' + feature.name;
        document.getElementById('featureInfoDesc')?.textContent = feature.description;
        document.getElementById('featureInfoScience')?.textContent = '📊 ' + feature.science;

        infoPanel.style.display = 'block';

        // Auto-hide after 5 seconds
        setTimeout(() => {
            infoPanel.style.display = 'none';
        }, 5000);
    }
    function calculateFeatureModifiers() {
        // Start with base modifiers
        let modifiers = {
            sfm: 1.0,
            chipload: 1.0,
            toolLife: 1.0,
            doc: 1.0,
            woc: 1.0,
            feed: 1.0,
            surfaceFinish: 1.0
        };
        // Apply each active feature's modifiers
        activeFeatures.forEach(featureId => {
            const feature = FEATURE_DEFINITIONS[featureId];
            if (feature && feature.modifiers) {
                // Multiplicative stacking for most modifiers
                Object.keys(feature.modifiers).forEach(key => {
                    if (modifiers[key] !== undefined) {
                        modifiers[key] *= feature.modifiers[key];
                    }
                });
            }
        });

        // Apply tolerance mode modifiers
        // First check if we have control-specific modifiers in Pro mode
        const machineId = document.getElementById('machineSelect')?.value;
        let toleranceModifiers = null;

        if (calculatorMode === 'pro' && machineId) {
            const settings = getControlToleranceSettings(machineId);
            if (settings && settings.modes && settings.modes[toleranceMode]) {
                const mode = settings.modes[toleranceMode];
                // Calculate modifiers based on tolerance value
                const baseTolerance = 0.002; // Medium is baseline
                const ratio = baseTolerance / (mode.tolerance || baseTolerance);

                // Higher tolerance (looser) = faster feed, worse finish
                // Lower tolerance (tighter) = slower feed, better finish
                toleranceModifiers = {
                    feed: ratio > 1 ? 1 + (ratio - 1) * 0.15 : 1 - (1 - ratio) * 0.15,
                    surfaceFinish: ratio > 1 ? 1 - (ratio - 1) * 0.1 : 1 + (1 - ratio) * 0.2
                };
            }
        }
        // Fall back to basic TOLERANCE_MODES
        if (!toleranceModifiers) {
            const tolerance = TOLERANCE_MODES[toleranceMode];
            if (tolerance && tolerance.modifiers) {
                toleranceModifiers = tolerance.modifiers;
            }
        }
        if (toleranceModifiers) {
            if (toleranceModifiers.feed) modifiers.feed *= toleranceModifiers.feed;
            if (toleranceModifiers.surfaceFinish) modifiers.surfaceFinish *= toleranceModifiers.surfaceFinish;
        }
        // Apply selected coolant modifiers (if any)
        if (selectedCoolant && selectedCoolant.data && selectedCoolant.data.modifiers) {
            const coolantMods = selectedCoolant.data.modifiers;
            if (coolantMods.toolLife) modifiers.toolLife *= coolantMods.toolLife;
            if (coolantMods.surfaceFinish) modifiers.surfaceFinish *= coolantMods.surfaceFinish;
        }
        return modifiers;
    }
    function updateModifiersDisplay() {
        const mods = calculateFeatureModifiers();

        // Update each modifier display with color coding
        const updateMod = (id, value) => {
            const el = document.getElementById(id);
            el.textContent = value.toFixed(2) + '×';

            if (value > 1.02) {
                el.className = 'mod-positive';
            } else if (value < 0.98) {
                el.className = 'mod-negative';
            } else {
                el.className = 'mod-neutral';
            }
        };
        updateMod('modSfm', mods.sfm);
        updateMod('modFeed', mods.feed);
        updateMod('modDoc', mods.doc);
        updateMod('modWoc', mods.woc);
        updateMod('modLife', mods.toolLife);
        updateMod('modFinish', mods.surfaceFinish);

        // Update overall multiplier display
        const overallMult = (mods.sfm * mods.feed * mods.doc * mods.woc) ** 0.25;  // Geometric mean
        document.getElementById('featureMultiplier')?.textContent = overallMult.toFixed(2) + '× overall';
    }
