    // Update turret visualization when machine changes
    function updateTurretLayout() {
        const machineKey = document.getElementById('machineSelect')?.value;
        const turretPanel = document.getElementById('turretLayoutPanel');
        const noTurretMsg = document.getElementById('noTurretMessage');
        const discContainer = document.getElementById('turretDiscContainer');
        const gangContainer = document.getElementById('gangContainer');

        console.log('updateTurretLayout called, machineMode:', machineMode, 'machineKey:', machineKey);

        if (!turretPanel) {
            console.log('Turret panel not found');
            return;
        }
        // Hide entire panel in mill mode - turret is lathe-only feature
        if (machineMode !== 'lathe') {
            turretPanel.style.display = 'none';
            return;
        }
        // Show panel in lathe mode
        turretPanel.style.display = 'block';

        // Get machine data
        const machine = LATHE_MACHINE_DATABASE?.machines?.[machineKey];
        console.log('Machine data:', machine ? 'found' : 'not found', machine?.turret);

        if (!machine || !machine.turret) {
            noTurretMsg.style.display = 'block';
            discContainer.style.display = 'none';
            gangContainer.style.display = 'none';
            return;
        }
        noTurretMsg.style.display = 'none';

        // Update turret config
        const turret = machine.turret;
        turretConfig.type = turret.type;
        turretConfig.capacity = turret.capacity || 12;
        turretConfig.liveTools = turret.liveTools || false;
        turretConfig.liveRpm = turret.liveRpm || 0;
        turretConfig.liveHp = turret.liveHp || 0;

        // Get turret type info
        const turretTypeInfo = LATHE_MACHINE_DATABASE?.turretTypes?.[turret.type] || { name: turret.type?.toUpperCase() || 'Unknown' };

        // Update badge and capacity
        document.getElementById('turretTypeBadge')?.textContent = turretTypeInfo.name;
        document.getElementById('turretCapacity')?.textContent = turretConfig.capacity + ' stations';

        // Show appropriate container
        if (turret.type === 'gang') {
            discContainer.style.display = 'none';
            gangContainer.style.display = 'flex';
            renderGangLayout();
        } else {
            discContainer.style.display = 'flex';
            gangContainer.style.display = 'none';
            renderTurretDisc();
        }
        // Update live tooling info
        updateLiveToolingInfo();

        // Close any open slot config
        closeSlotConfig();
    }
    function renderTurretDisc() {
        const disc = document.getElementById('turretDisc');
        const capacity = turretConfig.capacity;
        const radius = 75; // Distance from center to slot centers

        console.log('renderTurretDisc called, capacity:', capacity, 'disc element:', disc ? 'found' : 'not found');

        if (!disc) {
            console.error('Turret disc element not found!');
            return;
        }
        // Clear existing slots (keep center)
        const existingSlots = disc.querySelectorAll('.turret-slot');
        existingSlots.forEach(s => s.remove());

        // Create slots around the disc
        for (let i = 1; i <= capacity; i++) {
            const angle = ((i - 1) / capacity) * 2 * Math.PI - Math.PI / 2; // Start from top
            const x = 100 + radius * Math.cos(angle) - 18; // 18 = half slot width
            const y = 100 + radius * Math.sin(angle) - 18;

            const slot = document.createElement('div');
            slot.className = 'turret-slot';
            slot.dataset.slot = i;
            slot.style.left = x + 'px';
            slot.style.top = y + 'px';

            // Check if slot has tool configured
            if (turretConfig.slots[i]) {
                slot.classList.add('has-tool');
                const toolIcon = turretConfig.slots[i].icon || '🔧';
                slot.innerHTML = `<span class="turret-slot-icon">${toolIcon}</span>`;
            } else {
                slot.textContent = i;
            }
            slot.onclick = () => selectTurretSlot(i);
            disc.appendChild(slot);
        }
        console.log('Created', capacity, 'turret slots');

        // Update center label
        document.getElementById('turretCenterLabel')?.innerHTML = `<span style="font-size: 9px;">${turretConfig.capacity}<br>POS</span>`;
    }
    function renderGangLayout() {
        const rail = document.getElementById('gangRail');
        const capacity = turretConfig.capacity;

        rail.innerHTML = '';

        for (let i = 1; i <= capacity; i++) {
            const slot = document.createElement('div');
            slot.className = 'gang-slot';
            slot.dataset.slot = i;

            if (turretConfig.slots[i]) {
                slot.classList.add('has-tool');
                const toolIcon = turretConfig.slots[i].icon || '🔧';
                slot.innerHTML = `
                    <span class="turret-slot-icon">${toolIcon}</span>
                    <span class="gang-slot-num">T${i}</span>
                `;
            } else {
                slot.innerHTML = `
                    <span style="font-size: 14px; color: #3a4a5a;">+</span>
                    <span class="gang-slot-num">T${i}</span>
                `;
            }
            slot.onclick = () => selectTurretSlot(i);
            rail.appendChild(slot);
        }
    }
    function updateLiveToolingInfo() {
        const discLiveInfo = document.getElementById('turretLiveInfo');
        const gangLiveInfo = document.getElementById('gangLiveInfo');
        const discSpecs = document.getElementById('turretLiveSpecs');
        const gangSpecs = document.getElementById('gangLiveSpecs');

        if (turretConfig.liveTools) {
            const specs = `${turretConfig.liveRpm?.toLocaleString() || '--'} RPM / ${turretConfig.liveHp || '--'} HP`;

            if (turretConfig.type === 'gang') {
                gangLiveInfo.style.display = 'block';
                gangSpecs.textContent = specs;
                discLiveInfo.style.display = 'none';
            } else {
                discLiveInfo.style.display = 'block';
                discSpecs.textContent = specs;
                gangLiveInfo.style.display = 'none';
            }
        } else {
            discLiveInfo.style.display = 'none';
            gangLiveInfo.style.display = 'none';
        }
    }
    function selectTurretSlot(slotNum) {
        selectedSlot = slotNum;
        currentSlotStep = 1;
        slotConfigData = {
            interface: null,
            holdingMethod: null,
            holder: null,
            toolCategory: null,
            tool: null
        };
        // Update visual selection
        document.querySelectorAll('.turret-slot, .gang-slot').forEach(s => {
            s.classList.remove('selected');
            if (parseInt(s.dataset.slot) === slotNum) {
                s.classList.add('selected');
            }
        });

        // Show config panel
        const configPanel = document.getElementById('slotConfig');
        configPanel.classList.add('active');

        // Update title
        document.getElementById('slotConfigTitle')?.textContent = `Station T${slotNum}`;

        // If slot already has config, show summary
        if (turretConfig.slots[slotNum]) {
            showSlotSummary(slotNum);
        } else {
            // Start fresh configuration
            resetSlotWizard();

            // Pre-select turret interface from machine if available
            const machineKey = document.getElementById('machineSelect')?.value;
            const machine = LATHE_MACHINE_DATABASE?.machines?.[machineKey];
            if (machine?.turret?.type) {
                const interfaceSelect = document.getElementById('slotTurretInterface');
                const turretType = machine.turret.type.toLowerCase();
                // Try to find matching option
                for (const option of interfaceSelect.options) {
                    if (option.value && turretType.includes(option.value.replace(/\d+/g, ''))) {
                        interfaceSelect.value = option.value;
                        onTurretInterfaceChange();
                        break;
                    }
                }
            }
        }
    }
