    function getTurretInterfaceInfo(interfaceType) {
        const interfaces = {
            vdi20: { name: 'VDI20', description: 'Small lathes, light-duty tooling. 20mm shank diameter.' },
            vdi30: { name: 'VDI30', description: 'Medium lathes. 30mm shank diameter.' },
            vdi40: { name: 'VDI40', description: 'Most common CNC lathe interface. 40mm shank diameter.' },
            vdi50: { name: 'VDI50', description: 'Heavy-duty lathes. 50mm shank diameter.' },
            vdi60: { name: 'VDI60', description: 'Large lathes. 60mm shank diameter.' },
            bmt45: { name: 'BMT45', description: 'Bolt-mount tooling, 45mm. Higher rigidity than VDI.' },
            bmt55: { name: 'BMT55', description: 'Bolt-mount tooling, 55mm. Good for heavy cutting.' },
            bmt65: { name: 'BMT65', description: 'Bolt-mount tooling, 65mm. Most common BMT size.' },
            bmt75: { name: 'BMT75', description: 'Bolt-mount tooling, 75mm. Heavy-duty applications.' },
            capto_c4: { name: 'Capto C4', description: 'Sandvik modular quick-change system. 40mm coupling.' },
            capto_c5: { name: 'Capto C5', description: 'Sandvik modular quick-change system. 50mm coupling.' },
            capto_c6: { name: 'Capto C6', description: 'Sandvik modular quick-change system. 63mm coupling.' },
            km40: { name: 'KM40', description: 'Kennametal modular system. 40mm interface.' },
            km50: { name: 'KM50', description: 'Kennametal modular system. 50mm interface.' },
            axa: { name: 'AXA', description: 'Quick-change tool post for lathes up to 12" swing.' },
            bxa: { name: 'BXA', description: 'Quick-change tool post for 12-15" swing lathes.' },
            cxa: { name: 'CXA', description: 'Quick-change tool post for 15-20" swing lathes.' }
        };
        return interfaces[interfaceType] || { name: interfaceType.toUpperCase(), description: 'Standard turret interface.' };
    }
    function slotStepNext() {
        if (currentSlotStep === 1) {
            // Move to step 2 - Holding Method
            currentSlotStep = 2;
            populateHoldingMethods();
            document.getElementById('slotStep1')?.style.display = 'none';
            document.getElementById('slotStep2')?.style.display = 'block';
            document.getElementById('slotBackBtn')?.style.display = 'block';
            document.getElementById('slotNextBtn')?.disabled = true;
            updateSlotProgress(2);
        } else if (currentSlotStep === 2) {
            // Move to step 3 - Holder Selection
            currentSlotStep = 3;
            populateHolderOptions();
            document.getElementById('slotStep2')?.style.display = 'none';
            document.getElementById('slotStep3')?.style.display = 'block';
            document.getElementById('slotNextBtn')?.disabled = true;
            updateSlotProgress(3);
        } else if (currentSlotStep === 3) {
            // Move to step 4 - Tool Selection
            currentSlotStep = 4;
            document.getElementById('slotStep3')?.style.display = 'none';
            document.getElementById('slotStep4')?.style.display = 'block';
            document.getElementById('slotNextBtn')?.style.display = 'none';
            document.getElementById('slotApplyBtn')?.style.display = 'block';
            document.getElementById('slotApplyBtn')?.disabled = true;
            updateSlotProgress(4);
        }
    }
    function slotStepBack() {
        if (currentSlotStep === 2) {
            currentSlotStep = 1;
            document.getElementById('slotStep2')?.style.display = 'none';
            document.getElementById('slotStep1')?.style.display = 'block';
            document.getElementById('slotBackBtn')?.style.display = 'none';
            document.getElementById('slotNextBtn')?.disabled = false;
            updateSlotProgress(1);
        } else if (currentSlotStep === 3) {
            currentSlotStep = 2;
            document.getElementById('slotStep3')?.style.display = 'none';
            document.getElementById('slotStep2')?.style.display = 'block';
            document.getElementById('slotNextBtn')?.disabled = false;
            updateSlotProgress(2);
        } else if (currentSlotStep === 4) {
            currentSlotStep = 3;
            document.getElementById('slotStep4')?.style.display = 'none';
            document.getElementById('slotStep3')?.style.display = 'block';
            document.getElementById('slotNextBtn')?.style.display = 'block';
            document.getElementById('slotApplyBtn')?.style.display = 'none';
            document.getElementById('slotNextBtn')?.disabled = false;
            updateSlotProgress(3);
        }
    }
    function populateHoldingMethods() {
        const container = document.getElementById('holdingMethodOptions');
        const interfaceType = slotConfigData.interface;

        // Define holding methods based on interface
        let methods = [];

        if (interfaceType.startsWith('vdi') || interfaceType.startsWith('bmt')) {
            methods = [
                { id: 'direct_od', icon: '🔩', name: 'Direct OD Holder', desc: 'Square shank insert holder mounts directly to interface' },
                { id: 'boring_bar_sleeve', icon: '⭕', name: 'Boring Bar Sleeve', desc: 'Cylindrical sleeve holds round boring bars' },
                { id: 'collet_holder', icon: '🔘', name: 'Collet Holder (ER/5C)', desc: 'Collet chuck for drills, taps, round tools' },
                { id: 'direct_axial', icon: '🕳️', name: 'Axial Drill Holder', desc: 'Direct mount for drills along spindle axis' }
            ];

            // Add live tooling if available
            if (turretConfig.liveTools) {
                methods.push({ id: 'live_radial', icon: '⚡', name: 'Live Tool - Radial', desc: 'Driven tool perpendicular to spindle' });
                methods.push({ id: 'live_axial', icon: '⚡', name: 'Live Tool - Axial', desc: 'Driven tool along spindle axis' });
            }
        } else if (interfaceType.startsWith('capto') || interfaceType.startsWith('km')) {
            methods = [
                { id: 'modular_turning', icon: '🔩', name: 'Turning Unit', desc: 'Modular turning holder with insert' },
                { id: 'modular_boring', icon: '⭕', name: 'Boring Adapter', desc: 'Adapter for boring bars (Silent Tools compatible)' },
                { id: 'modular_collet', icon: '🔘', name: 'Collet Adapter', desc: 'ER collet adapter for round tools' },
                { id: 'modular_drill', icon: '🕳️', name: 'Drill Adapter', desc: 'Adapter for drills and reamers' }
            ];
        } else if (interfaceType === 'axa' || interfaceType === 'bxa' || interfaceType === 'cxa') {
            methods = [
                { id: 'qctp_turning', icon: '🔩', name: 'Turning Holder', desc: 'Standard QCTP turning tool holder' },
                { id: 'qctp_boring', icon: '⭕', name: 'Boring Bar Holder', desc: 'QCTP holder for round boring bars' },
                { id: 'qctp_parting', icon: '✂️', name: 'Parting Holder', desc: 'Blade-style parting tool holder' },
                { id: 'qctp_knurling', icon: '🔧', name: 'Knurling Holder', desc: 'Self-centering knurling tool' }
            ];
        }
        container.innerHTML = methods.map(m => `
            <button class="slot-method-btn" onclick="selectHoldingMethod('${m.id}')" data-method="${m.id}">
                <span class="slot-method-icon">${m.icon}</span>
                <div class="slot-method-info">
                    <div class="slot-method-name">${m.name}</div>
                    <div class="slot-method-desc">${m.desc}</div>
                </div>
            </button>
        `).join('');
    }
    function selectHoldingMethod(methodId) {
        slotConfigData.holdingMethod = methodId;

        // Update UI
        document.querySelectorAll('.slot-method-btn').forEach(btn => {
            btn.classList.toggle('selected', btn.dataset.method === methodId);
        });

        document.getElementById('slotNextBtn')?.disabled = false;
    }
