    function onHolderSelectChange() {
        const holder = document.getElementById('slotHolderSelect')?.value;
        const infoBox = document.getElementById('holderInfo');

        if (!holder) {
            infoBox.style.display = 'none';
            document.getElementById('slotNextBtn')?.disabled = true;
            return;
        }
        slotConfigData.holder = holder;

        // Show holder info
        infoBox.innerHTML = `<span style="color: var(--success);">✓</span> ${getHolderDisplayName(holder)} selected`;
        infoBox.style.display = 'block';

        document.getElementById('slotNextBtn')?.disabled = false;
    }
    function getHolderDisplayName(holderId) {
        // Parse holder ID into display name
        const parts = holderId.split('_');
        return parts.map(p => p.charAt(0).toUpperCase() + p.slice(1)).join(' ');
    }
    function onToolCategoryChange() {
        const category = document.getElementById('slotToolCategory')?.value;
        const toolSelect = document.getElementById('slotToolSelect');

        if (!category) {
            toolSelect.style.display = 'none';
            document.getElementById('slotApplyBtn')?.disabled = true;
            return;
        }
        slotConfigData.toolCategory = category;
        toolSelect.innerHTML = '<option value="">-- Select Specific Tool --</option>';

        // Populate tools based on category
        const tools = getToolsForCategory(category);
        tools.forEach(t => {
            const opt = document.createElement('option');
            opt.value = t.id;
            opt.textContent = t.name;
            toolSelect.appendChild(opt);
        });

        toolSelect.style.display = 'block';
    }
