    function onToolSelectChange() {
        const tool = document.getElementById('slotToolSelect')?.value;

        if (!tool) {
            document.getElementById('slotApplyBtn')?.disabled = true;
            return;
        }
        slotConfigData.tool = tool;
        document.getElementById('slotApplyBtn')?.disabled = false;
    }
    function showSlotSummary(slotNum) {
        const config = turretConfig.slots[slotNum] || slotConfigData;

        // Hide all steps
        document.getElementById('slotStep1')?.style.display = 'none';
        document.getElementById('slotStep2')?.style.display = 'none';
        document.getElementById('slotStep3')?.style.display = 'none';
        document.getElementById('slotStep4')?.style.display = 'none';
        document.getElementById('slotNavButtons')?.style.display = 'none';

        // Show summary
        document.getElementById('slotToolSummary')?.style.display = 'block';

        // Populate summary
        document.getElementById('summaryInterface')?.textContent = getTurretInterfaceInfo(config.interface || config.turretInterface).name;
        document.getElementById('summaryHolding')?.textContent = getHolderDisplayName(config.holdingMethod || 'Direct');
        document.getElementById('summaryHolder')?.textContent = getHolderDisplayName(config.holder || config.holderName || '--');
        document.getElementById('summaryTool')?.textContent = config.toolName || getHolderDisplayName(config.tool || '--');

        // Update progress to complete
        updateSlotProgress(5);
    }
    function editSlotConfig() {
        // Reset and start over
        resetSlotWizard();

        // Pre-fill with existing config if available
        if (turretConfig.slots[selectedSlot]) {
            const config = turretConfig.slots[selectedSlot];
            if (config.turretInterface) {
                document.getElementById('slotTurretInterface')?.value = config.turretInterface;
                onTurretInterfaceChange();
            }
        }
    }
    function showExistingSlotConfig(slotNum) {
        showSlotSummary(slotNum);
    }
    function closeSlotConfig() {
        selectedSlot = null;
        document.getElementById('slotConfig')?.classList.remove('active');

        // Remove selection from slots
        document.querySelectorAll('.turret-slot, .gang-slot').forEach(s => {
            s.classList.remove('selected');
        });
    }
    function clearSlot() {
        if (selectedSlot && turretConfig.slots[selectedSlot]) {
            delete turretConfig.slots[selectedSlot];

            // Update visual
            const slotEl = document.querySelector(`.turret-slot[data-slot="${selectedSlot}"], .gang-slot[data-slot="${selectedSlot}"]`);
            if (slotEl) {
                slotEl.classList.remove('has-tool');
                slotEl.innerHTML = selectedSlot;
            }
            closeSlotConfig();
        }
    }
    function applySlotConfig() {
        if (!selectedSlot) return;

        // Get icon based on tool category
        const icons = {
            turning_od: '🔩',
            turning_id: '⭕',
            drilling: '🕳️',
            tapping: '🔩',
            grooving: '✂️',
            threading: '🧵',
            reaming: '📍',
            milling: '⚡'
        };
        const toolCategory = slotConfigData.toolCategory || 'turning_od';
        const icon = icons[toolCategory] || '🔧';

        // Save config
        turretConfig.slots[selectedSlot] = {
            turretInterface: slotConfigData.interface,
            holdingMethod: slotConfigData.holdingMethod,
            holder: slotConfigData.holder,
            holderName: getHolderDisplayName(slotConfigData.holder || ''),
            toolCategory: slotConfigData.toolCategory,
            tool: slotConfigData.tool,
            toolName: document.getElementById('slotToolSelect')?.selectedOptions[0]?.text || slotConfigData.tool,
            icon: icon
        };
        // Update visual
        const slotEl = document.querySelector(`.turret-slot[data-slot="${selectedSlot}"], .gang-slot[data-slot="${selectedSlot}"]`);
        if (slotEl) {
            slotEl.classList.add('has-tool');
            slotEl.innerHTML = `<span class="turret-slot-icon">${icon}</span>`;
        }
        // Show summary
        showSlotSummary(selectedSlot);

        console.log(`Station T${selectedSlot} configured:`, turretConfig.slots[selectedSlot]);
    }
