    // HOLDER FILTERING & DISPLAY

    // Convert machine spindle taper to holder filter format
    function getMachineSpindleTaperFilter() {
        const machineId = document.getElementById('machineSelect')?.value;
        if (!machineId || !MACHINE_DATABASE.machines[machineId]) return null;

        const machine = MACHINE_DATABASE.machines[machineId];
        const spindle = selectedSpindleOption || machine.spindle;
        const taper = spindle.taper;
        const bigPlus = spindle.bigPlus;

        // Map machine taper names to holder filter values
        const taperMap = {
            'CAT40': bigPlus ? 'cat40_bigplus' : 'cat40',
            'CAT50': bigPlus ? 'cat50_bigplus' : 'cat50',
            'BT30': 'bt30',
            'BT40': 'bt40',
            'BT50': 'bt50',
            'HSK63A': 'hsk63a',
            'HSK-A63': 'hsk63a',
            'HSK100A': 'hsk100a',
            'HSK-A100': 'hsk100a',
            'HSK40E': 'hsk_e40',
            'HSK-E40': 'hsk_e40',
            'HSK-E32': 'hsk_e32',
            'HSK-F63': 'hsk_f63',
            'Capto C4': 'capto_c4',
            'Capto C5': 'capto_c5',
            'Capto C6': 'capto_c6',
            'Capto C8': 'capto_c8'
        };
        return taperMap[taper] || null;
    }
    // Update spindle filter based on machine selection
    function updateSpindleFilterFromMachine() {
        // Hide indicator in lathe mode - lathe uses different filter system
        const indicator = document.getElementById('spindleMatchIndicator');
        if (typeof machineMode !== 'undefined' && machineMode === 'lathe') {
            if (indicator) indicator.style.display = 'none';
            return;
        }
        const taperFilter = getMachineSpindleTaperFilter();
        const filterSelect = document.getElementById('filterTaper');
        const matchText = document.getElementById('spindleMatchText');

        if (taperFilter && filterSelect) {
            // Check if the option exists
            const option = filterSelect.querySelector(`option[value="${taperFilter}"]`);
            if (option) {
                filterSelect.value = taperFilter;

                // Show indicator
                if (indicator && matchText) {
                    const machineId = document.getElementById('machineSelect')?.value;
                    const machine = MACHINE_DATABASE.machines[machineId];
                    const spindle = selectedSpindleOption || machine.spindle;
                    const displayName = spindle.taper + (spindle.bigPlus ? ' Big Plus' : '');
                    matchText.innerHTML = `<strong>${displayName}</strong> — Showing compatible holders for your machine`;
                    indicator.style.display = 'block';
                }
                filterHolders();
            }
        } else {
            // No machine selected - hide indicator
            if (indicator) indicator.style.display = 'none';
        }
    }
    // Clear spindle filter and show all
    function clearSpindleFilter() {
        const filterSelect = document.getElementById('filterTaper');
        const indicator = document.getElementById('spindleMatchIndicator');

        if (filterSelect) filterSelect.value = '';
        if (indicator) indicator.style.display = 'none';

        // Call appropriate filter function based on mode
        if (typeof machineMode !== 'undefined' && machineMode === 'lathe') {
            filterLatheHolders();
        } else {
            filterHolders();
        }
    }
    function filterHolders() {
        const taperFilter = document.getElementById('filterTaper')?.value.toLowerCase();
        const typeFilter = document.getElementById('filterType')?.value;
        const brandFilter = document.getElementById('filterBrand')?.value;
        const modelFilter = document.getElementById('filterModel')?.value;
        const sizeFilter = document.getElementById('filterSize')?.value;
        const inStockOnly = document.getElementById('filterInStock')?.checked;
        const searchTerm = document.getElementById('filterSearch')?.value.toLowerCase();

        // MACHINE MODE DETECTION - LATHE vs MILL
        const isLatheMode = typeof machineMode !== 'undefined' && machineMode === 'lathe';
        let hasLiveTooling = false;
        let isMilLTurn = false;
        let turretType = null;

        if (isLatheMode) {
            // Get selected lathe machine capabilities
            const machineId = document.getElementById('machineSelect')?.value;
            if (machineId && LATHE_MACHINE_DATABASE?.machines?.[machineId]) {
                const lathe = LATHE_MACHINE_DATABASE.machines[machineId];
                hasLiveTooling = lathe.turret?.liveTools || false;
                isMilLTurn = lathe.type?.toLowerCase().includes('mill-turn') ||
                             lathe.type?.toLowerCase().includes('mill turn') ||
                             lathe.millingSpindle !== undefined;
                turretType = lathe.turret?.type?.toLowerCase() || null;
            }
            // Update spindle filter dropdown for lathe mode
            updateLatheSpindleFilterOptions(turretType, hasLiveTooling || isMilLTurn);
        }
        // Show/hide model dropdown based on brand+type selection
        const modelSelect = document.getElementById('filterModel');
        if (brandFilter && typeFilter) {
            modelSelect.style.display = 'block';
            // Populate model dropdown (will be done after first filter pass)
        } else {
            modelSelect.style.display = 'none';
            modelSelect.value = '';
            selectedModelSeries = '';
        }
        // Show/hide dimension category filters based on spindle+type selection
        const dimFiltersEl = document.getElementById('dimensionCategoryFilters');
        if (taperFilter && typeFilter) {
            dimFiltersEl.style.display = 'block';
        } else {
            dimFiltersEl.style.display = 'none';
            // Reset category selections when hidden
            selectedBoreCategory = '';
            selectedProjectionCategory = '';
        }
        // Get type info to check for brand restrictions
        const typeInfo = typeFilter ? HOLDER_DATABASE.types[typeFilter] : null;
        const allowedBrands = typeInfo?.brands || null;

        // Normalize taper value for comparison
        const normalizeTaper = (taper) => {
            if (!taper) return '';
            const t = taper.toLowerCase().replace(/[\s-]/g, '_').replace('big_plus', 'bigplus');
            // Map variations to standard form
            const taperMap = {
                'cat40': 'cat40',
                'cat40_bigplus': 'cat40_bigplus',
                'cat40bigplus': 'cat40_bigplus',
                'cat40_big_plus': 'cat40_bigplus',
                'cat50': 'cat50',
                'cat50_bigplus': 'cat50_bigplus',
                'cat50bigplus': 'cat50_bigplus',
                'cat50_big_plus': 'cat50_bigplus',
                'bt30': 'bt30',
                'bt30_bigplus': 'bt30',
                'bt40': 'bt40',
                'bt40_bigplus': 'bt40_bigplus',
                'bt50': 'bt50',
                'bt50_bigplus': 'bt50_bigplus',
                'hsk63a': 'hsk63a',
                'hsk_a63': 'hsk63a',
                'hsk100a': 'hsk100a',
                'hsk_a100': 'hsk100a',
                'hsk100': 'hsk100a',
                'hsk_a80': 'hsk100a',
                'hsk_a125': 'hsk100a',
                'hsk40e': 'hsk_e40',
                'hsk_e40': 'hsk_e40',
                'hsk50e': 'hsk_e40',
                'hsk_e50': 'hsk_e40',
                'hsk32e': 'hsk_e32',
                'hsk_e32': 'hsk_e32',
                'hsk63f': 'hsk_f63',
                'hsk_f63': 'hsk_f63',
                'capto_c3': 'capto_c4',
                'capto_c4': 'capto_c4',
                'capto_c5': 'capto_c5',
                'capto_c6': 'capto_c6',
                'capto_c8': 'capto_c8',
                'capto_c10': 'capto_c8',
                'sk40': 'cat40',
                'sk50': 'cat50',
                'r8': 'r8',
                'nmtb40': 'nmtb40',
                'tts': 'tts',
                'km4x63': 'km4x63',
                'universal': 'universal',
                // Lathe turret interfaces
                'vdi20': 'vdi20',
                'vdi30': 'vdi30',
                'vdi40': 'vdi40',
                'vdi50': 'vdi50',
                'vdi60': 'vdi60',
                'bmt45': 'bmt45',
                'bmt55': 'bmt55',
                'bmt65': 'bmt65',
                'bmt75': 'bmt75',
                'axa': 'axa',
                'bxa': 'bxa',
                'cxa': 'cxa',
                'ca': 'ca',
                'da': 'da'
            };
            return taperMap[t] || t;
        };
        const normalizedFilter = normalizeTaper(taperFilter);

        // First pass: filter by spindle, type, brand (before dimension categories)
        let preFilteredHolders = Object.entries(HOLDER_DATABASE.holders).filter(([id, holder]) => {
            // MACHINE MODE FILTER - LATHE vs MILL HOLDERS
            const holderTypeInfo = HOLDER_DATABASE.types[holder.type];
            const holderMachineType = holderTypeInfo?.machineType;

            if (isLatheMode) {
                // In lathe mode - only show lathe holders
                if (!holderMachineType) {
                    // No machineType means it's a mill-only holder - EXCLUDE
                    return false;
                }
                if (holderMachineType === 'lathe') {
                    // Standard lathe holder - always show
                    // Pass
                } else if (holderMachineType === 'lathe_live') {
                    // Live tooling holder - only show if machine has live tools or is mill-turn
                    if (!hasLiveTooling && !isMilLTurn) {
                        return false;
                    }
                } else {
                    // Not a lathe holder type - exclude
                    return false;
                }
                // Also check turret interface compatibility
                if (turretType && holderTypeInfo?.turretInterface) {
                    const compatibleInterfaces = holderTypeInfo.turretInterface;
                    // Normalize turret type
                    const normalizedTurret = turretType.toLowerCase().replace(/[\s-]/g, '');
                    const hasCompatible = compatibleInterfaces.some(iface =>
                        normalizedTurret.includes(iface.replace(/[\s-]/g, '')) ||
                        iface.replace(/[\s-]/g, '').includes(normalizedTurret)
                    );
                    // If no match, check for VDI/BMT families
                    if (!hasCompatible) {
                        const isVdi = normalizedTurret.includes('vdi') &&
                                     compatibleInterfaces.some(i => i.includes('vdi'));
                        const isBmt = normalizedTurret.includes('bmt') &&
                                     compatibleInterfaces.some(i => i.includes('bmt'));
                        if (!isVdi && !isBmt) {
                            // No compatible interface - still show but lower priority
                            // Don't exclude for now to maintain flexibility
                        }
                    }
                }
            } else {
                // In mill mode - exclude lathe-only holders
                if (holderMachineType === 'lathe' || holderMachineType === 'lathe_live') {
                    return false;
                }
            }
            // Taper/Spindle filter - handle compatible tapers
            if (normalizedFilter) {
                const holderTaper = normalizeTaper(holder.taper);

                // Direct match
                if (holderTaper === normalizedFilter) {
                    // Pass
                }
                // Universal items (like reduction sleeves) should show for all
                else if (holderTaper === 'universal') {
                    // Pass
                }
                // Big Plus holders can be used on non-Big Plus machines (but not vice versa)
                else if (normalizedFilter === 'cat40' && holderTaper === 'cat40_bigplus') {
                    // Pass - Big Plus holders work on standard CAT40
                }
                else if (normalizedFilter === 'cat50' && holderTaper === 'cat50_bigplus') {
                    // Pass - Big Plus holders work on standard CAT50
                }
                else if (normalizedFilter === 'bt40' && holderTaper === 'bt40_bigplus') {
                    // Pass
                }
                else if (normalizedFilter === 'bt50' && holderTaper === 'bt50_bigplus') {
                    // Pass
                }
                else {
                    return false;
                }
            }
            if (typeFilter && holder.type !== typeFilter) return false;
            if (brandFilter && holder.brand !== brandFilter) return false;
            // If type has brand restrictions, enforce them
            if (allowedBrands && !allowedBrands.includes(holder.brand)) return false;
            if (sizeFilter) {
                const targetSize = parseFloat(sizeFilter);
                const holderSize = holder.clampDiameter;
                // Allow small tolerance for floating point comparison
                if (Math.abs(holderSize - targetSize) > 0.01) return false;
            }
            if (inStockOnly && !holder.inStock) return false;
            if (searchTerm && !holder.partNumber.toLowerCase().includes(searchTerm) &&
                !holder.name.toLowerCase().includes(searchTerm) &&
                !(holder.features && holder.features.some(f => f.toLowerCase().includes(searchTerm)))) return false;
            return true;
        });

        // Update model dropdown with available series (before applying model filter)
        if (brandFilter && typeFilter) {
            updateModelDropdown(preFilteredHolders, brandFilter, typeFilter);
        }
        // Update dimension category buttons with available options (before applying dimension filters)
        if (taperFilter && typeFilter) {
            updateDimensionCategories(preFilteredHolders);
        }
        // Second pass: apply model series and dimension category filters
        filteredHolders = preFilteredHolders.filter(([id, holder]) => {
            // Model/Series filter
            if (modelFilter) {
                const holderSeries = extractHolderSeries(holder);
                if (holderSeries !== modelFilter) return false;
            }
            // Bore category filter
            if (selectedBoreCategory) {
                const boreCategory = getBoreCategory(holder.clampDiameter);
                if (boreCategory !== selectedBoreCategory) return false;
            }
            // Projection category filter
            if (selectedProjectionCategory) {
                const projCategory = getProjectionCategory(holder.gageLength);
                if (projCategory !== selectedProjectionCategory) return false;
            }
            return true;
        });

        // Update brand dropdown to show only relevant brands for selected type
        updateBrandDropdown(allowedBrands);

        // Update type dropdown based on available holders
        updateTypeDropdownCounts();

        renderHolderList();
        updateTypeDescription(typeFilter);
        document.getElementById('holderCount')?.textContent = `${filteredHolders.length} of ${Object.keys(HOLDER_DATABASE.holders).length} holders`;
    }
    /**
     * Filter and display lathe-specific tool holders
     * Handles turret interface, holder type, and brand filtering
     */
    function filterLatheHolders() {
        const turretInterface = document.getElementById('filterTurretInterface')?.value || '';
        const holderType = document.getElementById('filterLatheHolderType')?.value || '';
        const brand = document.getElementById('filterLatheBrand')?.value || '';

        // Get machine capabilities for live tooling
        let hasLiveTooling = false;
        let isMilLTurn = false;
        let machineTurretType = null;

        const machineId = document.getElementById('machineSelect')?.value;
        if (machineId && typeof LATHE_MACHINE_DATABASE !== 'undefined' && LATHE_MACHINE_DATABASE?.machines?.[machineId]) {
            const lathe = LATHE_MACHINE_DATABASE.machines[machineId];
            hasLiveTooling = lathe.turret?.liveTools || false;
            isMilLTurn = lathe.type?.toLowerCase().includes('mill-turn') ||
                         lathe.type?.toLowerCase().includes('mill turn') ||
                         lathe.millingSpindle !== undefined;
            machineTurretType = lathe.turret?.type?.toLowerCase() || null;
        }
        // Show/hide live tooling options based on machine capability
        const liveToolingGroup = document.getElementById('liveToolingGroup');
        if (liveToolingGroup) {
            liveToolingGroup.style.display = (hasLiveTooling || isMilLTurn) ? 'block' : 'none';
        }
        // Auto-select turret interface if machine is selected
        if (machineTurretType && !turretInterface) {
            const turretSelect = document.getElementById('filterTurretInterface');
            if (turretSelect) {
                const normalizedTurret = machineTurretType.toLowerCase().replace(/[\s-]/g, '');
                // Try to find matching option
                for (const option of turretSelect.options) {
                    if (option.value && (normalizedTurret.includes(option.value) || option.value.includes(normalizedTurret))) {
                        turretSelect.value = option.value;
                        break;
                    }
                }
            }
        }
        // Build list of lathe holder types (from HOLDER_DATABASE)
        const latheHolderTypes = [];
        Object.entries(HOLDER_DATABASE.types).forEach(([typeId, typeInfo]) => {
            if (typeInfo.machineType === 'lathe' || typeInfo.machineType === 'lathe_live') {
                latheHolderTypes.push({
                    id: typeId,
                    info: typeInfo,
                    isLive: typeInfo.machineType === 'lathe_live'
                });
            }
        });

        // Filter holders
        let matchingHolders = latheHolderTypes.filter(holder => {
            // Filter by turret interface compatibility
            if (turretInterface && holder.info.turretInterface) {
                const compatibleInterfaces = holder.info.turretInterface;
                if (!compatibleInterfaces.includes(turretInterface)) {
                    // Check if it's in the same family (VDI/BMT)
                    const isVdiMatch = turretInterface.includes('vdi') &&
                                      compatibleInterfaces.some(i => i.includes('vdi'));
                    const isBmtMatch = turretInterface.includes('bmt') &&
                                      compatibleInterfaces.some(i => i.includes('bmt'));
                    const isCaptoMatch = turretInterface.includes('capto') &&
                                        compatibleInterfaces.some(i => i.includes('capto'));
                    const isKmMatch = turretInterface.includes('km') &&
                                     compatibleInterfaces.some(i => i.includes('km'));
                    const isQctpMatch = ['axa','bxa','cxa','ca','da'].includes(turretInterface) &&
                                       compatibleInterfaces.some(i => ['axa','bxa','cxa','ca','da'].includes(i));

                    if (!isVdiMatch && !isBmtMatch && !isCaptoMatch && !isKmMatch && !isQctpMatch) {
                        return false;
                    }
                }
            }
            // Filter by holder type
            if (holderType && holder.id !== holderType) {
                return false;
            }
            // Filter out live tooling if machine doesn't have it
            if (holder.isLive && !hasLiveTooling && !isMilLTurn) {
                return false;
            }
            // Filter by brand if specified
            if (brand && holder.info.brands) {
                if (!holder.info.brands.includes(brand)) {
                    return false;
                }
            }
            return true;
        });

        // Render the filtered lathe holders
        renderLatheHolderList(matchingHolders, turretInterface, brand);

        // Update holder count
        document.getElementById('holderCount')?.textContent = `${matchingHolders.length} lathe holder types`;
    }
    /**
     * Render the list of lathe tool holders
     */
    function renderLatheHolderList(holders, turretInterface, brand) {
        const container = document.getElementById('holderList');
        if (!container) return;

        if (holders.length === 0) {
            container.innerHTML = `
                <div style="padding: 20px; text-align: center; color: var(--text-muted);">
                    <p>No lathe holders match your filters</p>
                    <p style="font-size: 10px; margin-top: 8px;">Try adjusting your turret interface, holder type, or brand filters</p>
                </div>
            `;
            return;
        }
        // Group holders by category
        const categories = {
            turning: { label: '🔩 OD Turning Holders', holders: [] },
            boring: { label: '🔴 Boring Bar Holders', holders: [] },
            drilling: { label: '🕳️ Drilling/Axial Holders', holders: [] },
            parting: { label: '✂️ Parting/Grooving', holders: [] },
            collet: { label: '⭕ Collet Holders', holders: [] },
            live: { label: '⚡ Live Tooling', holders: [] },
            specialty: { label: '🔧 Specialty', holders: [] }
        };
        holders.forEach(holder => {
            const id = holder.id;
            if (id.includes('od_') || id.includes('qctp_holder')) {
                categories.turning.holders.push(holder);
            } else if (id.includes('boring') || id.includes('sleeve')) {
                categories.boring.holders.push(holder);
            } else if (id.includes('axial') || id.includes('drill')) {
                categories.drilling.holders.push(holder);
            } else if (id.includes('parting') || id.includes('grooving') || id.includes('threading')) {
                categories.parting.holders.push(holder);
            } else if (id.includes('collet') || id.includes('er_collet')) {
                categories.collet.holders.push(holder);
            } else if (id.includes('live')) {
                categories.live.holders.push(holder);
            } else {
                categories.specialty.holders.push(holder);
            }
        });

        let html = '';

        Object.entries(categories).forEach(([catId, catData]) => {
            if (catData.holders.length === 0) return;

            html += `<div style="margin-bottom: 12px;">`;
            html += `<div style="font-size: 11px; font-weight: 600; color: var(--primary); margin-bottom: 6px; padding-bottom: 4px; border-bottom: 1px solid var(--border);">${catData.label}</div>`;

            catData.holders.forEach(holder => {
                const info = holder.info;
                const isLive = holder.isLive;

                // Get compatible interfaces display
                let interfaceText = '';
                if (info.turretInterface && info.turretInterface.length > 0) {
                    interfaceText = info.turretInterface.slice(0, 3).map(i => i.toUpperCase()).join(', ');
                    if (info.turretInterface.length > 3) {
                        interfaceText += ` +${info.turretInterface.length - 3} more`;
                    }
                }
                // Get brand display
                let brandText = 'Universal';
                if (info.brands && info.brands.length > 0) {
                    const brandNames = info.brands.slice(0, 2).map(b => {
                        const brandInfo = HOLDER_DATABASE.brands[b];
                        return brandInfo ? brandInfo.name : b;
                    });
                    brandText = brandNames.join(', ');
                    if (info.brands.length > 2) {
                        brandText += ` +${info.brands.length - 2}`;
                    }
                }
                html += `
                    <div class="holder-card" onclick="selectLatheHolder('${holder.id}')"
                         style="padding: 10px; margin-bottom: 6px; border-radius: 8px;
                                background: var(--bg-dark); border: 1px solid var(--border);
                                cursor: pointer; transition: all 0.2s ease;"
                         onmouseenter="this.style.borderColor='var(--primary)'; this.style.background='rgba(0,212,255,0.1)'"
                         onmouseleave="this.style.borderColor='var(--border)'; this.style.background='var(--bg-dark)'">
                        <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                            <div style="flex: 1;">
                                <div style="font-weight: 600; font-size: 12px; color: var(--text);">
                                    ${info.name}
                                    ${isLive ? '<span style="color: #fbbf24; font-size: 10px; margin-left: 4px;">⚡LIVE</span>' : ''}
                                </div>
                                <div style="font-size: 10px; color: var(--text-muted); margin-top: 3px;">
                                    ${info.description}
                                </div>
                                <div style="display: flex; gap: 8px; margin-top: 6px; flex-wrap: wrap;">
                                    <span style="font-size: 9px; padding: 2px 6px; background: rgba(0,212,255,0.15); color: var(--primary); border-radius: 4px;">
                                        ${interfaceText || 'Various'}
                                    </span>
                                    <span style="font-size: 9px; padding: 2px 6px; background: rgba(74,222,128,0.15); color: var(--success); border-radius: 4px;">
                                        ${brandText}
                                    </span>
                                </div>
                            </div>
                            <div style="text-align: right; font-size: 10px; color: var(--text-muted);">
                                <div>Rigidity: ${(info.rigidityBase * 100).toFixed(0)}%</div>
                                <div>Damping: ${(info.dampingBase * 100).toFixed(0)}%</div>
                            </div>
                        </div>
                        ${info.pros ? `
                        <div style="margin-top: 8px; display: flex; gap: 6px; flex-wrap: wrap;">
                            ${info.pros.slice(0, 3).map(pro => `
                                <span style="font-size: 9px; color: var(--success);">✓ ${pro}</span>
                            `).join('')}
                        </div>
                        ` : ''}
                    </div>
                `;
            });

            html += `</div>`;
        });

        container.innerHTML = html;
    }
    /**
     * Select a lathe holder type
     */
    function selectLatheHolder(holderId) {
        const typeInfo = HOLDER_DATABASE.types[holderId];
        if (!typeInfo) return;

        // Update the holder type dropdown
        const holderTypeSelect = document.getElementById('filterLatheHolderType');
        if (holderTypeSelect) {
            holderTypeSelect.value = holderId;
        }
        // Show holder details in a styled notification
        const detailsHtml = `
            <div style="position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);
                        background: var(--bg-card); border: 2px solid var(--primary); border-radius: 12px;
                        padding: 20px; z-index: 10000; max-width: 450px; box-shadow: 0 20px 50px rgba(0,0,0,0.5);">
                <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px;">
                    <h3 style="color: var(--primary); margin: 0; font-size: 16px;">${typeInfo.name}</h3>
                    <button onclick="this.parentElement.parentElement.remove()"
                            style="background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 18px;">✕</button>
                </div>
                <p style="color: var(--text); font-size: 12px; margin-bottom: 12px;">${typeInfo.description}</p>
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 12px;">
                    <div style="background: rgba(0,212,255,0.1); padding: 10px; border-radius: 8px;">
                        <div style="font-size: 10px; color: var(--text-muted);">Rigidity</div>
                        <div style="font-size: 18px; font-weight: 700; color: var(--primary);">${(typeInfo.rigidityBase * 100).toFixed(0)}%</div>
                    </div>
                    <div style="background: rgba(74,222,128,0.1); padding: 10px; border-radius: 8px;">
                        <div style="font-size: 10px; color: var(--text-muted);">Damping</div>
                        <div style="font-size: 18px; font-weight: 700; color: var(--success);">${(typeInfo.dampingBase * 100).toFixed(0)}%</div>
                    </div>
                </div>
                ${typeInfo.pros ? `
                <div style="margin-bottom: 10px;">
                    <div style="font-size: 10px; color: var(--success); font-weight: 600; margin-bottom: 4px;">ADVANTAGES</div>
                    <ul style="margin: 0; padding-left: 16px; font-size: 11px; color: var(--text);">
                        ${typeInfo.pros.map(p => `<li>${p}</li>`).join('')}
                    </ul>
                </div>
                ` : ''}
                ${typeInfo.cons ? `
                <div style="margin-bottom: 10px;">
                    <div style="font-size: 10px; color: var(--danger); font-weight: 600; margin-bottom: 4px;">LIMITATIONS</div>
                    <ul style="margin: 0; padding-left: 16px; font-size: 11px; color: var(--text);">
                        ${typeInfo.cons.map(c => `<li>${c}</li>`).join('')}
                    </ul>
                </div>
                ` : ''}
                ${typeInfo.bestFor ? `
                <div>
                    <div style="font-size: 10px; color: var(--primary); font-weight: 600; margin-bottom: 4px;">BEST FOR</div>
                    <div style="font-size: 11px; color: var(--text);">${typeInfo.bestFor.join(', ')}</div>
                </div>
                ` : ''}
            </div>
            <div onclick="this.nextElementSibling?.remove(); this.remove()"
                 style="position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5); z-index: 9999;"></div>
        `;

        document.body.insertAdjacentHTML('beforeend', detailsHtml);
    }
    /**
     * Update spindle/turret filter dropdown options for lathe mode
     * Shows lathe turret interfaces instead of spindle tapers
     */
    function updateLatheSpindleFilterOptions(machineturretType, hasLiveTooling) {
        const filterSelect = document.getElementById('filterTaper');
        if (!filterSelect) return;

        const isLatheMode = typeof machineMode !== 'undefined' && machineMode === 'lathe';

        if (isLatheMode) {
            // Build lathe turret interface options
            let optionsHtml = '<option value="">All Turret Interfaces</option>';

            // VDI options
            optionsHtml += '<optgroup label="VDI (DIN 69880)">';
            optionsHtml += '<option value="vdi20">VDI20</option>';
            optionsHtml += '<option value="vdi30">VDI30</option>';
            optionsHtml += '<option value="vdi40">VDI40</option>';
            optionsHtml += '<option value="vdi50">VDI50</option>';
            optionsHtml += '<option value="vdi60">VDI60</option>';
            optionsHtml += '</optgroup>';

            // BMT options
            optionsHtml += '<optgroup label="BMT (Bolt Mount)">';
            optionsHtml += '<option value="bmt45">BMT45</option>';
            optionsHtml += '<option value="bmt55">BMT55</option>';
            optionsHtml += '<option value="bmt65">BMT65</option>';
            optionsHtml += '<option value="bmt75">BMT75</option>';
            optionsHtml += '</optgroup>';

            // Modular systems
            optionsHtml += '<optgroup label="Modular Systems">';
            optionsHtml += '<option value="capto_c3">Capto C3</option>';
            optionsHtml += '<option value="capto_c4">Capto C4</option>';
            optionsHtml += '<option value="capto_c5">Capto C5</option>';
            optionsHtml += '<option value="capto_c6">Capto C6</option>';
            optionsHtml += '<option value="km32">KM32</option>';
            optionsHtml += '<option value="km40">KM40</option>';
            optionsHtml += '<option value="km50">KM50</option>';
            optionsHtml += '</optgroup>';

            // QCTP options
            optionsHtml += '<optgroup label="Quick-Change Tool Post">';
            optionsHtml += '<option value="axa">AXA (up to 12" swing)</option>';
            optionsHtml += '<option value="bxa">BXA (12-15" swing)</option>';
            optionsHtml += '<option value="cxa">CXA (15-20" swing)</option>';
            optionsHtml += '<option value="ca">CA (20-25" swing)</option>';
            optionsHtml += '<option value="da">DA (25"+ swing)</option>';
            optionsHtml += '</optgroup>';

            filterSelect.innerHTML = optionsHtml;

            // Auto-select based on machine turret type if available
            if (machineturretType) {
                const normalizedTurret = machineturretType.toLowerCase().replace(/[\s-]/g, '');
                // Try to find matching option
                const options = filterSelect.querySelectorAll('option');
                for (const option of options) {
                    if (normalizedTurret.includes(option.value) || option.value.includes(normalizedTurret)) {
                        filterSelect.value = option.value;
                        break;
                    }
                }
            }
        } else {
            // Mill mode - restore original spindle taper options
            // This will be handled by the existing code
        }
    }
    /**
     * Update type dropdown to show lathe or mill holder types based on mode
     */
    function updateHolderTypeDropdownForMode() {
        const filterSelect = document.getElementById('filterType');
        if (!filterSelect) return;

        const isLatheMode = typeof machineMode !== 'undefined' && machineMode === 'lathe';
        let hasLiveTooling = false;
        let isMilLTurn = false;

        if (isLatheMode) {
            const machineId = document.getElementById('machineSelect')?.value;
            if (machineId && LATHE_MACHINE_DATABASE?.machines?.[machineId]) {
                const lathe = LATHE_MACHINE_DATABASE.machines[machineId];
                hasLiveTooling = lathe.turret?.liveTools || false;
                isMilLTurn = lathe.type?.toLowerCase().includes('mill-turn') ||
                             lathe.millingSpindle !== undefined;
            }
        }
        let optionsHtml = '<option value="">All Types</option>';

        // Build options based on machine mode
        Object.entries(HOLDER_DATABASE.types).forEach(([typeId, typeInfo]) => {
            const holderMachineType = typeInfo.machineType;

            if (isLatheMode) {
                // Lathe mode - show only lathe holders
                if (!holderMachineType) return; // Skip mill-only holders
                if (holderMachineType === 'lathe') {
                    optionsHtml += `<option value="${typeId}">${typeInfo.name}</option>`;
                } else if (holderMachineType === 'lathe_live' && (hasLiveTooling || isMilLTurn)) {
                    optionsHtml += `<option value="${typeId}">${typeInfo.name} (Live)</option>`;
                }
            } else {
                // Mill mode - show only mill holders
                if (holderMachineType === 'lathe' || holderMachineType === 'lathe_live') return;
                optionsHtml += `<option value="${typeId}">${typeInfo.name}</option>`;
            }
        });

        filterSelect.innerHTML = optionsHtml;
    }
    /**
     * Update brand dropdown to show only relevant brands for current mode and type
     */
    function updateBrandDropdownForMode() {
        const filterSelect = document.getElementById('filterBrand');
        if (!filterSelect) return;

        const isLatheMode = typeof machineMode !== 'undefined' && machineMode === 'lathe';
        let optionsHtml = '<option value="">All Brands</option>';

        // Group brands by category
        const categories = {
            premium_japan: { label: 'Premium Japanese', brands: [] },
            premium_europe: { label: 'Premium European', brands: [] },
            premium_usa: { label: 'Premium USA', brands: [] },
            tier3: { label: 'Professional', brands: [] },
            live_tooling: { label: 'Live Tooling Specialists', brands: [] },
            lathe_holders: { label: 'Lathe Tool Holder Specialists', brands: [] },
            qctp: { label: 'Quick-Change Tool Post', brands: [] },
            economy: { label: 'Economy/Value', brands: [] }
        };
        Object.entries(HOLDER_DATABASE.brands).forEach(([brandId, brandInfo]) => {
            const brandMachineType = brandInfo.machineType;

            // Filter by machine mode
            if (isLatheMode) {
                // In lathe mode, prefer lathe brands but also show universal premium brands
                if (brandMachineType === 'lathe') {
                    if (brandInfo.specialty?.toLowerCase().includes('live')) {
                        categories.live_tooling.brands.push({ id: brandId, info: brandInfo });
                    } else if (brandInfo.specialty?.toLowerCase().includes('qctp') || brandInfo.specialty?.toLowerCase().includes('tool post')) {
                        categories.qctp.brands.push({ id: brandId, info: brandInfo });
                    } else {
                        categories.lathe_holders.brands.push({ id: brandId, info: brandInfo });
                    }
                } else if (!brandMachineType) {
                    // Universal brands (no machineType) - include premium ones for lathe too
                    if (brandInfo.quality === 'Premium') {
                        if (brandInfo.country === 'Japan') {
                            categories.premium_japan.brands.push({ id: brandId, info: brandInfo });
                        } else if (['Germany', 'Switzerland', 'Sweden', 'Italy', 'Spain'].includes(brandInfo.country)) {
                            categories.premium_europe.brands.push({ id: brandId, info: brandInfo });
                        } else {
                            categories.premium_usa.brands.push({ id: brandId, info: brandInfo });
                        }
                    }
                }
            } else {
                // Mill mode - exclude lathe-only brands
                if (brandMachineType === 'lathe') return;

                if (brandInfo.quality === 'Premium') {
                    if (brandInfo.country === 'Japan') {
                        categories.premium_japan.brands.push({ id: brandId, info: brandInfo });
                    } else if (['Germany', 'Switzerland', 'Sweden', 'Italy', 'Spain'].includes(brandInfo.country)) {
                        categories.premium_europe.brands.push({ id: brandId, info: brandInfo });
                    } else {
                        categories.premium_usa.brands.push({ id: brandId, info: brandInfo });
                    }
                } else if (brandInfo.quality === 'Professional') {
                    categories.professional.brands.push({ id: brandId, info: brandInfo });
                } else {
                    categories.economy.brands.push({ id: brandId, info: brandInfo });
                }
            }
        });

        // Build optgroups
        Object.entries(categories).forEach(([catId, catData]) => {
            if (catData.brands.length > 0) {
                optionsHtml += `<optgroup label="${catData.label}">`;
                catData.brands.forEach(brand => {
                    optionsHtml += `<option value="${brand.id}">${brand.info.name}</option>`;
                });
                optionsHtml += '</optgroup>';
            }
        });

        filterSelect.innerHTML = optionsHtml;
    }
    // Get bore diameter category
    function getBoreCategory(diameter) {
        if (diameter <= 0.25) return 'micro';      // ≤1/4"
        if (diameter <= 0.5) return 'small';       // 1/4" - 1/2"
        if (diameter <= 0.75) return 'medium';     // 1/2" - 3/4"
        if (diameter <= 1.0) return 'large';       // 3/4" - 1"
        return 'xlarge';                           // >1"
    }
    // Get projection length category
    function getProjectionCategory(length) {
        if (length <= 2.0) return 'short';         // ≤2"
        if (length <= 3.5) return 'standard';      // 2" - 3.5"
        if (length <= 5.0) return 'long';          // 3.5" - 5"
        return 'extended';                         // >5"
    }
    // Extract model/series from holder name and features
    function extractHolderSeries(holder) {
        const name = holder.name || '';
        const features = holder.features || [];
        const partNumber = holder.partNumber || '';

        // Series patterns to detect (order matters - check specific patterns first)
        const seriesPatterns = [
            // Big Daishowa specific
            { pattern: /SLIM\s*Hydraulic/i, series: 'SLIM Hydraulic' },
            { pattern: /Super\s*Slim/i, series: 'Super Slim' },
            { pattern: /JET/i, series: 'JET (Coolant-Thru)' },
            { pattern: /MEGA\s*DS/i, series: 'MEGA DS' },
            { pattern: /MEGA\s*Micro/i, series: 'MEGA Micro' },
            { pattern: /MEGA\s*Double\s*Grip/i, series: 'MEGA Double Grip' },
            { pattern: /MEGA\s*ER/i, series: 'MEGA ER' },
            { pattern: /MEGA\s*\d+N/i, series: 'MEGA New Baby' },

            // Haimer specific
            { pattern: /Power\s*Shrink/i, series: 'Power Shrink' },
            { pattern: /Safe-Lock/i, series: 'Safe-Lock' },
            { pattern: /Duo-Lock/i, series: 'Duo-Lock' },
            { pattern: /Ultra\s*Short/i, series: 'Ultra Short' },
            { pattern: /Heavy\s*Duty/i, series: 'Heavy Duty' },

            // Schunk specific
            { pattern: /TRIBOS/i, series: 'TRIBOS' },
            { pattern: /TENDO/i, series: 'TENDO' },
            { pattern: /SINO/i, series: 'SINO' },

            // Rego-Fix specific
            { pattern: /powRgrip/i, series: 'powRgrip' },
            { pattern: /secuRgrip/i, series: 'secuRgrip' },

            // General patterns
            { pattern: /Long\s*Reach/i, series: 'Long Reach' },
            { pattern: /Extended/i, series: 'Extended Reach' },
            { pattern: /Slim\s*Line/i, series: 'Slim Line' },
            { pattern: /High\s*Speed/i, series: 'High Speed' },
            { pattern: /EPB/i, series: 'EPB' },
            { pattern: /CoroGrip/i, series: 'CoroGrip' },

            // ER Collet types
            { pattern: /ER\s*\d+/i, series: (name.match(/ER\s*(\d+)/i) || [])[0] || 'ER Collet' },

            // Default type-based series
            { pattern: /Hydraulic/i, series: 'Standard Hydraulic' },
            { pattern: /Shrink\s*Fit/i, series: 'Standard Shrink Fit' },
            { pattern: /Milling\s*Chuck/i, series: 'Milling Chuck' },
            { pattern: /Shell\s*Mill/i, series: 'Shell Mill' },
            { pattern: /Face\s*Mill/i, series: 'Face Mill' },
            { pattern: /Side\s*Lock/i, series: 'Side Lock' },
            { pattern: /Weldon/i, series: 'Weldon' },
            { pattern: /Drill\s*Chuck/i, series: 'Drill Chuck' },
            { pattern: /Tap\s*Holder/i, series: 'Tap Holder' },
            { pattern: /Boring/i, series: 'Boring Bar' }
        ];

        // Check name first
        for (const { pattern, series } of seriesPatterns) {
            if (pattern.test(name)) {
                return typeof series === 'string' ? series : series;
            }
        }
        // Check features
        const featureStr = features.join(' ');
        for (const { pattern, series } of seriesPatterns) {
            if (pattern.test(featureStr)) {
                return typeof series === 'string' ? series : series;
            }
        }
        // Check part number for series codes
        if (/HDC.*J/i.test(partNumber)) return 'JET (Coolant-Thru)';
        if (/HDC.*S/i.test(partNumber)) return 'SLIM Hydraulic';

        return 'Standard';
    }
    // Update model/series dropdown
    function updateModelDropdown(holders, brandFilter, typeFilter) {
        const modelSelect = document.getElementById('filterModel');
        const currentValue = modelSelect.value;

        // Count holders by series
        const seriesCounts = {};
        holders.forEach(([id, holder]) => {
            const series = extractHolderSeries(holder);
            seriesCounts[series] = (seriesCounts[series] || 0) + 1;
        });

        // Sort series by count (descending) then alphabetically
        const sortedSeries = Object.entries(seriesCounts)
            .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));

        // Only show dropdown if there are multiple series
        if (sortedSeries.length <= 1) {
            modelSelect.style.display = 'none';
            modelSelect.value = '';
            return;
        }
        modelSelect.style.display = 'block';

        // Build options
        let optionsHtml = '<option value="">All Models</option>';
        sortedSeries.forEach(([series, count]) => {
            const selected = series === currentValue ? 'selected' : '';
            optionsHtml += `<option value="${series}" ${selected}>${series} (${count})</option>`;
        });

        modelSelect.innerHTML = optionsHtml;
    }
    // Update dimension category buttons
    function updateDimensionCategories(holders) {
        // Count holders in each bore category
        const boreCounts = { micro: 0, small: 0, medium: 0, large: 0, xlarge: 0 };
        const projCounts = { short: 0, standard: 0, long: 0, extended: 0 };

        holders.forEach(([id, holder]) => {
            const boreCategory = getBoreCategory(holder.clampDiameter);
            const projCategory = getProjectionCategory(holder.gageLength);
            boreCounts[boreCategory]++;
            projCounts[projCategory]++;
        });

        // Generate bore category buttons
        const boreContainer = document.getElementById('boreCategoryBtns');
        const boreCategories = [
            { id: '', label: 'All', count: holders.length },
            { id: 'micro', label: '≤¼"', count: boreCounts.micro, mm: '≤6mm' },
            { id: 'small', label: '¼-½"', count: boreCounts.small, mm: '6-12mm' },
            { id: 'medium', label: '½-¾"', count: boreCounts.medium, mm: '12-20mm' },
            { id: 'large', label: '¾-1"', count: boreCounts.large, mm: '20-25mm' },
            { id: 'xlarge', label: '>1"', count: boreCounts.xlarge, mm: '>25mm' }
        ];

        boreContainer.innerHTML = boreCategories
            .filter(cat => cat.id === '' || cat.count > 0)
            .map(cat => {
                const isActive = selectedBoreCategory === cat.id;
                const label = holderUnitSystem === 'metric' && cat.mm ? cat.mm : cat.label;
                return `<button class="cat-btn ${isActive ? 'active' : ''}"
                                onclick="setBoreCategory('${cat.id}')"
                                data-category="${cat.id}">
                            ${label}<span class="count">(${cat.count})</span>
                        </button>`;
            }).join('');

        // Generate projection category buttons
        const projContainer = document.getElementById('projectionCategoryBtns');
        const projCategories = [
            { id: '', label: 'All', count: holders.length },
            { id: 'short', label: '≤2"', count: projCounts.short, mm: '≤50mm' },
            { id: 'standard', label: '2-3.5"', count: projCounts.standard, mm: '50-90mm' },
            { id: 'long', label: '3.5-5"', count: projCounts.long, mm: '90-125mm' },
            { id: 'extended', label: '>5"', count: projCounts.extended, mm: '>125mm' }
        ];

        projContainer.innerHTML = projCategories
            .filter(cat => cat.id === '' || cat.count > 0)
            .map(cat => {
                const isActive = selectedProjectionCategory === cat.id;
                const label = holderUnitSystem === 'metric' && cat.mm ? cat.mm : cat.label;
                return `<button class="cat-btn ${isActive ? 'active' : ''}"
                                onclick="setProjectionCategory('${cat.id}')"
                                data-category="${cat.id}">
                            ${label}<span class="count">(${cat.count})</span>
                        </button>`;
            }).join('');
    }
    // Set bore category filter
    function setBoreCategory(category) {
        selectedBoreCategory = category;
        filterHolders();
    }
    // Set projection category filter
    function setProjectionCategory(category) {
        selectedProjectionCategory = category;
        filterHolders();
    }
