                'bt30_bigplus': 'BT30',
                'bt40': 'BT40',
                'bt40_bigplus': 'BT40 BP',
                'bt50': 'BT50',
                'bt50_bigplus': 'BT50 BP',
                'hsk63a': 'HSK63A',
                'hsk_a63': 'HSK63A',
                'hsk100a': 'HSK100A',
                'hsk_a100': 'HSK100A',
                'hsk100': 'HSK100A',
