                'capto_c4': 'Capto C4',
                'capto_c5': 'Capto C5',
                'capto_c6': 'Capto C6',
                'capto_c8': 'Capto C8',
                'capto_c10': 'Capto C10',
                'sk40': 'SK40',
                'sk50': 'SK50',
                'r8': 'R8',
                'nmtb40': 'NMTB40',
