    function formatHolderDimension(inches) {
        if (inches === undefined || inches === null || isNaN(inches)) {
            return '--';
        }
        if (holderUnitSystem === 'metric') {
            const mm = inches * 25.4;
            return mm.toFixed(1) + 'mm';
        } else {
            // Format as fraction if close to common sizes
            const commonSizes = {
                0.125: '1/8"', 0.1875: '3/16"', 0.250: '1/4"', 0.3125: '5/16"',
                0.375: '3/8"', 0.4375: '7/16"', 0.500: '1/2"', 0.5625: '9/16"',
                0.625: '5/8"', 0.6875: '11/16"', 0.750: '3/4"', 0.8125: '13/16"',
                0.875: '7/8"', 0.9375: '15/16"', 1.000: '1"', 1.125: '1-1/8"',
                1.250: '1-1/4"', 1.375: '1-3/8"', 1.500: '1-1/2"', 1.750: '1-3/4"',
                2.000: '2"', 2.500: '2-1/2"', 3.000: '3"'
            };
            // Check for close match to common size
            for (const [size, label] of Object.entries(commonSizes)) {
                if (Math.abs(inches - parseFloat(size)) < 0.01) {
                    return label;
                }
            }
            return inches.toFixed(3) + '"';
        }
    }
    function formatHolderTIR(inches) {
        if (holderUnitSystem === 'metric') {
            const mm = inches * 25.4;
            if (mm < 0.01) {
                return (mm * 1000).toFixed(1) + 'μm';
            }
            return mm.toFixed(4) + 'mm';
        } else {
            return inches + '"';
        }
    }
