    // INVENTORY PERSISTENCE
    function saveInventoryToStorage() {
        const inventory = {};
        Object.entries(HOLDER_DATABASE.holders).forEach(([id, holder]) => {
            if (holder.inStock) inventory[id] = true;
        });
        localStorage.setItem('jmdie_holder_inventory', JSON.stringify(inventory));
    }
    function loadInventoryFromStorage() {
        try {
            const saved = localStorage.getItem('jmdie_holder_inventory');
            if (saved) {
                const inventory = JSON.parse(saved);
                Object.keys(inventory).forEach(id => {
                    if (HOLDER_DATABASE.holders[id]) {
                        HOLDER_DATABASE.holders[id].inStock = true;
                    }
                });
            }
        } catch (e) {
            console.error('Error loading inventory:', e);
        }
    }
    function saveInventory() {
        const inventory = {};
        Object.entries(HOLDER_DATABASE.holders).forEach(([id, holder]) => {
            inventory[id] = holder.inStock;
        });

        const blob = new Blob([JSON.stringify(inventory, null, 2)], {type: 'application/json'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'jmdie_holder_inventory.json';
        a.click();
        URL.revokeObjectURL(url);
    }
    function loadInventory() {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.json';
        input.onchange = function(e) {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onload = function(e) {
                try {
                    const inventory = JSON.parse(e.target.result);
                    // Reset all to false first
                    Object.keys(HOLDER_DATABASE.holders).forEach(id => {
                        HOLDER_DATABASE.holders[id].inStock = false;
                    });
                    // Apply loaded inventory
                    Object.entries(inventory).forEach(([id, inStock]) => {
                        if (HOLDER_DATABASE.holders[id]) {
                            HOLDER_DATABASE.holders[id].inStock = inStock;
                        }
                    });
                    saveInventoryToStorage();
                    filterHolders();
                    alert('Inventory loaded successfully!');
                } catch (err) {
                    alert('Error loading inventory file');
                }
            };
            reader.readAsText(file);
        };
        input.click();
    }
