    // MACHINE ACCESSORIES - 4th Axis, Trunnion, Tailstock Functions

    function toggleAccessory(accessoryType, btn) {
        const configSections = {
            '4th_axis': 'fourthAxisConfig',
            'trunnion': 'trunnionConfig',
            'tailstock': 'tailstockConfig'
        };
        const configId = configSections[accessoryType];
        const configEl = document.getElementById(configId);

        // Toggle button active state
        btn.classList.toggle('active');

        // Show/hide config section
        if (configEl) {
            configEl.style.display = btn.classList.contains('active') ? 'block' : 'none';
        }
        // If activating trunnion, deactivate 4th axis (mutually exclusive)
        if (accessoryType === 'trunnion' && btn.classList.contains('active')) {
            const fourthBtn = document.getElementById('btn4thAxis');
            if (fourthBtn && fourthBtn.classList.contains('active')) {
                fourthBtn.classList.remove('active');
                document.getElementById('fourthAxisConfig')?.style.display = 'none';
            }
        }
        // If activating 4th axis, deactivate trunnion
        if (accessoryType === '4th_axis' && btn.classList.contains('active')) {
            const trunnionBtn = document.getElementById('btnTrunnion');
            if (trunnionBtn && trunnionBtn.classList.contains('active')) {
                trunnionBtn.classList.remove('active');
                document.getElementById('trunnionConfig')?.style.display = 'none';
            }
        }
    }
    function updateRotaryModels() {
        const manufacturer = document.getElementById('rotaryManufacturer')?.value;
        const modelSelect = document.getElementById('rotaryModel');
        const specsDiv = document.getElementById('rotarySpecs');

        modelSelect.innerHTML = '<option value="">Select Model...</option>';
        if (specsDiv) specsDiv.style.display = 'none';

        if (!manufacturer || !ROTARY_TABLE_DATABASE[manufacturer]) return;

        const mfgData = ROTARY_TABLE_DATABASE[manufacturer];
        mfgData.models.forEach(model => {
            const option = document.createElement('option');
            option.value = model.id;
            option.textContent = model.name;
            modelSelect.appendChild(option);
        });
    }
    function updateRotarySpecs() {
        const manufacturer = document.getElementById('rotaryManufacturer')?.value;
        const modelId = document.getElementById('rotaryModel')?.value;
        const specsDiv = document.getElementById('rotarySpecs');

        if (!manufacturer || !modelId || !ROTARY_TABLE_DATABASE[manufacturer]) {
            if (specsDiv) specsDiv.style.display = 'none';
            return;
        }
        const model = ROTARY_TABLE_DATABASE[manufacturer].models.find(m => m.id === modelId);
        if (!model) {
            if (specsDiv) specsDiv.style.display = 'none';
            return;
        }
        // Update spec displays
        document.getElementById('rotaryTableSize')?.textContent = model.tableSize;
        document.getElementById('rotaryMaxRPM')?.textContent = model.maxRPM + ' rpm';
        document.getElementById('rotaryAccuracy')?.textContent = model.accuracy;
        document.getElementById('rotaryTorque')?.textContent = model.torque;
        document.getElementById('rotaryThruHole')?.textContent = model.thruHole;
        document.getElementById('rotaryWeightCap')?.textContent = model.weightCap;

        if (specsDiv) specsDiv.style.display = 'block';

        // Store selection
        activeAccessories.fourthAxis = {
            manufacturer: manufacturer,
            model: modelId,
            specs: model
        };
    }
