    // Update Machine Features visibility based on machine selection
    function updateMachineFeaturesSections(machineId) {
        const motionSection = document.getElementById('motionControlSection');
        const toleranceSection = document.getElementById('toleranceModeSection');
        const accessoriesSection = document.getElementById('machineAccessoriesSection');
        const machineFeaturesPrompt = document.getElementById('machineFeaturesPrompt');
        const machineFeaturesContent = document.getElementById('machineFeaturesContent');

        if (machineId) {
            // Machine selected - show all content
            if (machineFeaturesPrompt) machineFeaturesPrompt.style.display = 'none';
            if (machineFeaturesContent) machineFeaturesContent.style.display = 'block';
            if (motionSection) motionSection.style.display = 'block';
            if (toleranceSection) toleranceSection.style.display = 'block';

            // Check if machine is a mill (show accessories for mills only)
            const isMill = document.getElementById('operationType')?.value !== 'lathe' &&
                          document.getElementById('operationType')?.value !== 'turning';
            if (accessoriesSection) {
                accessoriesSection.style.display = isMill ? 'block' : 'none';
            }
        } else {
            // No machine - show only the prompt
            if (machineFeaturesPrompt) machineFeaturesPrompt.style.display = 'block';
            if (machineFeaturesContent) machineFeaturesContent.style.display = 'none';
            if (motionSection) motionSection.style.display = 'none';
            if (toleranceSection) toleranceSection.style.display = 'none';
            if (accessoriesSection) accessoriesSection.style.display = 'none';
        }
    }
    // FEATURE HELP MODAL - How to check if features are available

    function showFeatureHelp(featureId) {
        const feature = FEATURE_DEFINITIONS[featureId];
        if (!feature || !feature.howToCheck) return;

        const tooltip = document.getElementById('featureHelpTooltip');
        const content = document.getElementById('featureHelpTooltipContent');

        if (!tooltip || !content) return;

        // Get control type color
        let controlColor = '#00d4ff';
        if (featureId.startsWith('fanuc')) controlColor = '#22c55e';
        else if (featureId.startsWith('siemens')) controlColor = '#3b82f6';
        else if (featureId.startsWith('heidenhain')) controlColor = '#ef4444';
        else if (featureId.startsWith('okuma')) controlColor = '#f59e0b';
        else if (featureId.startsWith('mazak')) controlColor = '#a855f7';
        else if (featureId.startsWith('haas')) controlColor = '#ec4899';
        else if (featureId.startsWith('makino')) controlColor = '#14b8a6';

        content.innerHTML = `
            <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 12px;">
                <span style="font-size: 24px;">${feature.icon}</span>
                <div>
                    <div style="font-size: 14px; font-weight: 700; color: ${controlColor};">${feature.name}</div>
                    ${feature.gcode ? `<code style="font-size: 11px; background: rgba(0,0,0,0.3); padding: 2px 6px; border-radius: 4px; color: #4ade80;">${feature.gcode}</code>` : ''}
                </div>
            </div>
            <div style="font-size: 11px; color: var(--text-light); margin-bottom: 12px;">${feature.description}</div>
            <div style="background: rgba(251, 191, 36, 0.1); border: 1px solid rgba(251, 191, 36, 0.3); border-radius: 8px; padding: 12px;">
                <div style="font-size: 10px; font-weight: 600; color: #fbbf24; margin-bottom: 6px;">🔍 How to Check:</div>
                <div style="font-size: 11px; color: var(--text); line-height: 1.5;">${feature.howToCheck}</div>
            </div>
            <div style="margin-top: 10px; font-size: 9px; color: var(--text-muted); text-align: center;">
                Click elsewhere to close
            </div>
        `;

        // Position near center of screen
        tooltip.style.display = 'block';
        tooltip.style.top = '50%';
        tooltip.style.left = '50%';
        tooltip.style.transform = 'translate(-50%, -50%)';
    }
    function closeFeatureHelpTooltip() {
        const tooltip = document.getElementById('featureHelpTooltip');
        if (tooltip) tooltip.style.display = 'none';
    }
    // Close tooltip when clicking outside
    document.addEventListener('click', function(e) {
        const tooltip = document.getElementById('featureHelpTooltip');
        if (tooltip && tooltip.style.display === 'block') {
            if (!tooltip.contains(e.target) && !e.target.closest('[onclick*="showFeatureHelp"]')) {
                closeFeatureHelpTooltip();
            }
        }
    });

    function showFeatureHelpModal() {
        const modal = document.getElementById('featureHelpModal');
        const content = document.getElementById('featureHelpContent');

        if (!modal || !content) return;

        // Get current machine's available features
        const machineId = document.getElementById('machineModel')?.value;
        const availableFeatures = machineId ? getAvailableMotionFeatures(machineId) : [];

        // Group features by control type
        const featuresByControl = {};

        // If we have a selected machine, show its features
        if (availableFeatures.length > 0) {
            availableFeatures.forEach(featureId => {
                const feature = FEATURE_DEFINITIONS[featureId];
                if (!feature || !feature.howToCheck) return;

                const controlType = getControlTypeFromFeatureId(featureId);
                if (!featuresByControl[controlType]) {
                    featuresByControl[controlType] = [];
                }
                featuresByControl[controlType].push({ id: featureId, ...feature });
            });
        } else {
            // Show all features grouped by control
            const controlGroups = ['fanuc', 'siemens', 'heidenhain', 'okuma', 'mazak', 'haas', 'makino', 'hurco'];
            controlGroups.forEach(ctrl => {
                featuresByControl[ctrl] = [];
                Object.entries(FEATURE_DEFINITIONS).forEach(([id, feature]) => {
                    if (id.startsWith(ctrl) && feature.howToCheck) {
                        featuresByControl[ctrl].push({ id, ...feature });
                    }
                });
            });
        }
        // Generate HTML
        let html = '';

        const controlColors = {
            fanuc: { color: '#22c55e', name: 'FANUC' },
            siemens: { color: '#3b82f6', name: 'Siemens SINUMERIK' },
            heidenhain: { color: '#ef4444', name: 'Heidenhain TNC' },
            okuma: { color: '#f59e0b', name: 'Okuma OSP' },
            mazak: { color: '#a855f7', name: 'Mazak SmoothAi' },
            haas: { color: '#ec4899', name: 'Haas NGC' },
            makino: { color: '#14b8a6', name: 'Makino Pro6' },
            hurco: { color: '#06b6d4', name: 'Hurco WinMax' },
            mitsubishi: { color: '#f97316', name: 'Mitsubishi M800' },
            brother: { color: '#84cc16', name: 'Brother C00' },
            kitamura: { color: '#8b5cf6', name: 'Kitamura Arumatik' },
            sodick: { color: '#0ea5e9', name: 'Sodick LN' },
            roders: { color: '#d946ef', name: 'Röders RMS' }
        };
        Object.entries(featuresByControl).forEach(([control, features]) => {
            if (features.length === 0) return;

            const ctrlInfo = controlColors[control] || { color: '#888', name: control.toUpperCase() };

            html += `
                <div style="margin-bottom: 16px;">
                    <div style="font-size: 12px; font-weight: 700; color: ${ctrlInfo.color}; margin-bottom: 8px; padding-bottom: 4px; border-bottom: 1px solid ${ctrlInfo.color}40;">
                        ${ctrlInfo.name}
                    </div>
                    <div style="display: grid; gap: 8px;">
            `;

            features.forEach(feature => {
                html += `
                    <div style="background: rgba(0,0,0,0.2); border-radius: 8px; padding: 10px; cursor: pointer; transition: all 0.2s;"
                         onclick="this.querySelector('.help-details').style.display = this.querySelector('.help-details').style.display === 'none' ? 'block' : 'none'"
                         onmouseover="this.style.background='rgba(255,255,255,0.05)'"
                         onmouseout="this.style.background='rgba(0,0,0,0.2)'">
                        <div style="display: flex; align-items: center; gap: 8px;">
                            <span style="font-size: 16px;">${feature.icon}</span>
                            <div style="flex: 1;">
                                <span style="font-size: 11px; font-weight: 600; color: var(--text);">${feature.name}</span>
                                ${feature.gcode ? `<code style="font-size: 9px; background: rgba(74,222,128,0.2); padding: 1px 4px; border-radius: 3px; color: #4ade80; margin-left: 6px;">${feature.gcode}</code>` : ''}
                            </div>
                            <span style="font-size: 10px; color: var(--text-muted);">▼</span>
                        </div>
                        <div class="help-details" style="display: none; margin-top: 10px; padding-top: 10px; border-top: 1px dashed rgba(255,255,255,0.1);">
                            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 8px;">${feature.description}</div>
                            <div style="background: rgba(251, 191, 36, 0.1); border: 1px solid rgba(251, 191, 36, 0.3); border-radius: 6px; padding: 10px;">
                                <div style="font-size: 9px; font-weight: 600; color: #fbbf24; margin-bottom: 4px;">🔍 How to Check:</div>
                                <div style="font-size: 10px; color: var(--text); line-height: 1.5;">${feature.howToCheck}</div>
                            </div>
                        </div>
                    </div>
                `;
            });

            html += `</div></div>`;
        });

        if (html === '') {
            html = `
                <div style="text-align: center; padding: 20px; color: var(--text-muted);">
                    <div style="font-size: 32px; margin-bottom: 12px;">🔧</div>
                    <div style="font-size: 12px;">Select a machine first to see available features</div>
                </div>
            `;
        }
        content.innerHTML = html;
        modal.style.display = 'block';
    }
    function closeFeatureHelpModal() {
        const modal = document.getElementById('featureHelpModal');
        if (modal) modal.style.display = 'none';
    }
    // Close modal when clicking outside
    document.getElementById('featureHelpModal')?.addEventListener('click', function(e) {
        if (e.target === this) closeFeatureHelpModal();
    });

    function getControlTypeFromFeatureId(featureId) {
        const prefixes = ['fanuc', 'siemens', 'heidenhain', 'okuma', 'mazak', 'haas', 'makino', 'hurco', 'mitsubishi', 'brother', 'kitamura', 'sodick', 'roders', 'fidia', 'dmg'];
        for (const prefix of prefixes) {
            if (featureId.startsWith(prefix)) return prefix;
        }
        return 'generic';
    }
    // MY MACHINES - Save and Load Machine Configurations
    let myMachines = [];  // Array of {id, machineId, spindleId, name, savedAt}

    function loadMyMachinesFromStorage() {
        try {
            const saved = localStorage.getItem('jmdie_my_machines');
            if (saved) {
                myMachines = JSON.parse(saved);
                renderMyMachines();
            }
        } catch (e) {
            console.error('Error loading saved machines:', e);
            myMachines = [];
        }
    }
    function saveMyMachinesToStorage() {
        try {
            localStorage.setItem('jmdie_my_machines', JSON.stringify(myMachines));
        } catch (e) {
            console.error('Error saving machines:', e);
        }
    }
    function saveMyMachine() {
        const machineId = document.getElementById('machineSelect')?.value;
        const spindleId = document.getElementById('spindleSelect')?.value;

        if (!machineId || !MACHINE_DATABASE.machines[machineId]) {
            alert('Please select a machine first');
            return;
        }
        const machine = MACHINE_DATABASE.machines[machineId];
        const spindle = spindleId ? SPINDLE_OPTIONS.types[spindleId] : null;

        // Create a unique ID for this configuration
        const configId = `${machineId}_${spindleId || 'default'}_${Date.now()}`;

        // Check if this exact config already exists
        const exists = myMachines.some(m => m.machineId === machineId && m.spindleId === (spindleId || null));
        if (exists) {
            // Flash a message instead of adding duplicate
            const confirmDiv = document.getElementById('saveConfirmation');
            confirmDiv.textContent = '⚠️ This configuration already saved!';
            confirmDiv.style.color = '#fbbf24';
            confirmDiv.style.display = 'block';
            setTimeout(() => { confirmDiv.style.display = 'none'; }, 2000);
            return;
        }
        // Build the display name
        let displayName = machine.model;
        if (spindle) {
            displayName += ` / ${spindle.shortName}`;
        }
        // Add to saved machines
        myMachines.unshift({
            id: configId,
            machineId: machineId,
            spindleId: spindleId || null,
            name: displayName,
            taper: spindle ? spindle.taper : machine.spindle.taper,
            rpm: spindle ? spindle.maxRpm : machine.spindle.maxRpm,
            hp: spindle ? spindle.peakHp : machine.spindle.peakHp,
            savedAt: new Date().toISOString()
        });

        // Limit to 20 saved machines
        if (myMachines.length > 20) {
            myMachines = myMachines.slice(0, 20);
        }
        saveMyMachinesToStorage();
        renderMyMachines();

        // Show confirmation
        const confirmDiv = document.getElementById('saveConfirmation');
        confirmDiv.textContent = '✓ Saved to My Machines!';
        confirmDiv.style.color = '#4ade80';
        confirmDiv.style.display = 'block';
        setTimeout(() => { confirmDiv.style.display = 'none'; }, 2000);
    }
