    function applyMachineTemplate() {
        const templateId = document.getElementById('addMachineTemplate')?.value;
        if (!templateId || !MACHINE_SPEC_TEMPLATES.machineTypes[templateId]) return;

        const template = MACHINE_SPEC_TEMPLATES.machineTypes[templateId];

        // Apply template values to form
        document.getElementById('addMachineRpm')?.value = template.maxRpm;
        document.getElementById('addMachineHp')?.value = template.peakHp;
        document.getElementById('addMachineTorque')?.value = template.torque;
        document.getElementById('addMachineTaper')?.value = template.taper;

        // Set control based on template
        const controlSelect = document.getElementById('addMachineControl');
        const controlType = template.control;
        for (let option of controlSelect.options) {
            if (option.value === controlType || option.value.startsWith(controlType)) {
                controlSelect.value = option.value;
                break;
            }
        }
        // Auto-check some capabilities based on template
        document.getElementById('addMachineHSM')?.checked = template.maxRpm >= 12000;
        document.getElementById('addMachineATC')?.checked = true;
        document.getElementById('addMachine5th')?.checked = templateId.includes('5axis');
        document.getElementById('addMachineTSC')?.checked = template.maxRpm >= 10000;
    }
    function addCustomMachine() {
        // Validate required fields
        const manufacturer = document.getElementById('addMachineManufacturer')?.value;
        const model = document.getElementById('addMachineModel')?.value.trim();
        const rpm = parseInt(document.getElementById('addMachineRpm')?.value);
        const hp = parseFloat(document.getElementById('addMachineHp')?.value);
        const taper = document.getElementById('addMachineTaper')?.value;

        if (!manufacturer) {
            alert('Please select a manufacturer');
            return;
        }
        if (!model) {
            alert('Please enter a model name');
            return;
        }
        if (!rpm || rpm < 100) {
            alert('Please enter a valid max RPM');
            return;
        }
        if (!hp || hp < 0.5) {
            alert('Please enter a valid horsepower');
            return;
        }
        // Get optional values
        const year = document.getElementById('addMachineYear')?.value || '';
        const torque = parseInt(document.getElementById('addMachineTorque')?.value) || Math.round(hp * 5252 / (rpm * 0.3)); // Estimate if not provided
        const bigPlus = document.getElementById('addMachineBigPlus')?.checked;
        const tsc = document.getElementById('addMachineTSC')?.checked;
        const controlId = document.getElementById('addMachineControl')?.value;
        const control = MACHINE_SPEC_TEMPLATES.controls[controlId] || { name: 'Generic', type: 'generic' };

        // Get capabilities
        const hsm = document.getElementById('addMachineHSM')?.checked;
        const probing = document.getElementById('addMachineProbing')?.checked;
        const is5axis = document.getElementById('addMachine5th')?.checked;

        // Generate unique ID
        const machineId = `custom_${manufacturer.toLowerCase().replace(/[^a-z0-9]/g, '')}_${model.toLowerCase().replace(/[^a-z0-9]/g, '')}_${Date.now()}`;

        // Build display model name
        const displayModel = year ? `${manufacturer} ${model} (${year})` : `${manufacturer} ${model}`;

        // Determine machine type based on specs
        let machineType = 'VMC';
        if (is5axis) machineType = '5-Axis';
        else if (taper.includes('A2-') || taper === 'ER32') machineType = 'Lathe';
        else if (taper === 'ISO30' && rpm > 18000) machineType = 'Router';
        else if (hp > 40) machineType = 'HMC';

        // Create power curve based on HP and RPM
        const peakPowerRpm = Math.round(rpm * 0.7); // Typically peak power at 70% of max RPM
        const continuousHp = Math.round(hp * 0.75 * 10) / 10;

        // Build the machine object matching database structure
        const newMachine = {
            model: displayModel,
            manufacturer: manufacturer,
            year: year || 'Unknown',
            type: machineType,
            isCustom: true,
            spindle: {
                maxRpm: rpm,
                peakHp: hp,
                continuousHp: continuousHp,
                peakTorque: torque,
                taper: taper,
                bigPlus: bigPlus,
                throughSpindleCoolant: tsc,
                powerCurve: [
                    { rpm: 0, hp: 0 },
                    { rpm: Math.round(rpm * 0.1), hp: Math.round(hp * 0.3 * 10) / 10 },
                    { rpm: Math.round(rpm * 0.3), hp: Math.round(hp * 0.7 * 10) / 10 },
                    { rpm: peakPowerRpm, hp: hp },
                    { rpm: rpm, hp: Math.round(hp * 0.85 * 10) / 10 }
                ]
            },
            control: {
                type: control.type,
                name: control.name
            },
            capabilities: {
                hsm: hsm,
                probing: probing,
                fiveAxis: is5axis
            }
        };
        // Add to database
        MACHINE_DATABASE.machines[machineId] = newMachine;

        // Save custom machines to localStorage
        saveCustomMachines();

        // Refresh machine list
        filterMachines();

        // Select the new machine
        document.getElementById('machineSelect')?.value = machineId;
        selectMachine();

        // Close modal
        document.getElementById('addMachineModal')?.remove();

        // Show confirmation
        const confirmDiv = document.getElementById('saveConfirmation');
        if (confirmDiv) {
            confirmDiv.textContent = `✓ ${displayModel} added!`;
            confirmDiv.style.color = '#60a5fa';
            confirmDiv.style.display = 'block';
            setTimeout(() => { confirmDiv.style.display = 'none'; }, 3000);
        }
    }
