    async function submitMachineRequest() {
        const make = document.getElementById('requestMachineMake')?.value.trim();
        const model = document.getElementById('requestMachineModel')?.value.trim();
        const type = document.getElementById('requestMachineType')?.value;
        const year = document.getElementById('requestMachineYear')?.value;
        const specs = document.getElementById('requestMachineSpecs')?.value.trim();

        // Validate required fields
        if (!make) {
            alert('Please enter the machine manufacturer/brand');
            document.getElementById('requestMachineMake')?.focus();
            return;
        }
        if (!model) {
            alert('Please enter the machine model number/name');
            document.getElementById('requestMachineModel')?.focus();
            return;
        }
        // Find the submit button and update it
        const submitBtn = document.querySelector('#requestMachineModal button[onclick="submitMachineRequest()"]');
        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.innerHTML = '<span>⏳</span> AI Researching Specs...';
            submitBtn.style.opacity = '0.7';
        }
        try {
            // Call Claude API to generate machine specs
            const machineData = await generateMachineWithAI(make, model, year, type, specs);

            if (machineData) {
                // Add to live database
                addMachineToDatabase(machineData);

                // Close the request modal
                document.getElementById('requestMachineModal')?.remove();

                // Show success with machine added confirmation
                showMachineAddedConfirmation(make, model, machineData.id);

                // Refresh dropdowns and select the new machine
                setTimeout(() => {
                    if (typeof populateManufacturerDropdown === 'function') {
                        populateManufacturerDropdown();
                    }
                    if (typeof filterMachines === 'function') {
                        filterMachines();
                    }
                    // Try to select the new machine
                    setTimeout(() => {
                        const machineSelect = document.getElementById('machineSelect');
                        if (machineSelect) {
                            machineSelect.value = machineData.id;
                            if (typeof selectMachine === 'function') {
                                selectMachine(machineData.id);
                            }
                        }
                    }, 300);
                }, 200);
            }
        } catch (error) {
            console.error('Machine generation error:', error);
            alert('Error generating machine specs: ' + error.message + '\n\nPlease try again or contact support.');
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.innerHTML = '<span>📨</span> Submit Request';
                submitBtn.style.opacity = '1';
            }
        }
    }
    async function generateMachineWithAI(brand, model, year, machineType, additionalSpecs) {
        const prompt = `You are a CNC machine database expert. Generate complete machine specifications for:

Brand/Manufacturer: \${brand}
Model: \${model}
Year: \${year || 'Current/Recent'}
Type: \${machineType || 'Please determine from model name'}
Additional info: \${additionalSpecs || 'None provided'}

Return ONLY a valid JSON object (no markdown code blocks, no explanation text) with this EXACT structure:
{
    "id": "brand_model" (lowercase, underscores instead of spaces/hyphens),
    "manufacturer": "brand" (lowercase),
    "model": "Full Model Name",
    "type": "3-axis VMC" or "4-axis VMC" or "5-axis VMC" or "4-axis HMC" or "5-axis HMC" or "2-axis Lathe" etc,
    "axes": 3 or 4 or 5 (number),
    "spindle": {
        "maxRpm": number (typical for this machine class),
        "peakHp": number,
        "continuousHp": number (typically 70-80% of peak),
        "torque": number (ft-lbs at spindle),
        "taper": "CAT40" or "CAT50" or "BT40" or "BT50" or "HSK63A" or "HSK100A",
        "bigPlus": true or false
    },
    "travels": {
        "x": number (inches),
        "y": number (inches),
        "z": number (inches)
    },
    "rapids": {
        "xy": number (inches per minute),
        "z": number (inches per minute)
    },
    "atc": {
        "capacity": number (tool count)
    },
    "control": "Fanuc 0i-MF" or "Fanuc 31i-B5" or "Siemens 840D sl" or "Haas NGC" or appropriate control,
    "coolant": {
        "tsc": true or false (through-spindle coolant),
        "pressure": number or null (PSI if TSC equipped)
    },
    "inStock": true,
    "userAdded": true,
    "volumetric": {
        "totalVolume": number (calculate: X * Y * Z in mm, then cube),
        "usableVolume": number (80% of total),
        "maxPartWeight": number (kg, estimate based on table size),
        "units": "mm3"
    },
    "collisionConfig": {
        "spindleGeometry": "cat40" or "cat50" or "hsk63a" (lowercase, matches taper),
        "kinematicType": "3-axis-vmc" or "4-axis-vmc" or "5-axis-trunnion" or "5-axis-swivel-head" or "3-axis-hmc" or "4-axis-hmc",
        "activeZones": ["spindleHead", "toolHolder", "table", "fixture", "enclosure"]
    },
    "workEnvelope": {
        "maxX": number (mm, = travels.x * 25.4),
        "maxY": number (mm, = travels.y * 25.4),
        "maxZ": number (mm, = travels.z * 25.4),
        "units": "mm"
    },
    "optionalFeatures": {
        "probing": true or false,
        "chipConveyor": true or false,
        "highPressureCoolant": true or false,
        "throughSpindleAir": true or false
    }
}
Use your knowledge of this specific machine model. If exact specs aren't known, use typical values for this machine class and brand quality level. Be realistic with specs.`;

        (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('[PRISM] Calling Claude API to generate machine specs...');

        const response = await fetch("https://api.anthropic.com/v1/messages", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({
                model: "claude-sonnet-4-20250514",
                max_tokens: 2000,
                messages: [
                    { role: "user", content: prompt }
                ],
            })
        });

        if (!response.ok) {
            const errorText = await response.text();
            console.error('[PRISM] API Error:', errorText);
            throw new Error('API request failed: ' + response.status);
        }
        const data = await response.json();
        (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('[PRISM] API Response:', data);

        const text = data.content?.[0]?.text || '';
        (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('[PRISM] Response text:', text);

        // Parse the JSON from response (handle potential markdown code blocks)
        let jsonText = text;
        if (text.includes('```')) {
            const match = text.match(/```(?:json)?\s*([\s\S]*?)```/);
            if (match) jsonText = match[1];
        }
        const jsonMatch = jsonText.match(/\{[\s\S]*\}/);
        if (!jsonMatch) {
            throw new Error('Could not parse machine data from AI response');
        }
        const machineData = JSON.parse(jsonMatch[0]);

        // Validate required fields
        if (!machineData.id || !machineData.manufacturer || !machineData.model) {
            throw new Error('Missing required fields in machine data');
        }
        // Ensure userAdded flag is set
        machineData.userAdded = true;
        machineData.addedDate = new Date().toISOString();

        (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('[PRISM] Generated machine data:', machineData);
        return machineData;
    }
    function addMachineToDatabase(machineData) {
        const machineEntry = {
            manufacturer: machineData.manufacturer,
            model: machineData.model,
            type: machineData.type,
            axes: machineData.axes,
            spindle: machineData.spindle,
            travels: machineData.travels,
            rapids: machineData.rapids,
            atc: machineData.atc,
            control: machineData.control,
            coolant: machineData.coolant,
            inStock: true,
            userAdded: true,
            addedDate: machineData.addedDate || new Date().toISOString(),
            volumetric: machineData.volumetric,
            collisionConfig: machineData.collisionConfig,
            workEnvelope: machineData.workEnvelope,
            optionalFeatures: machineData.optionalFeatures
        };
        // Add to MACHINE_DATABASE
        if (typeof MACHINE_DATABASE !== 'undefined' && MACHINE_DATABASE && MACHINE_DATABASE.machines) {
            MACHINE_DATABASE.machines[machineData.id] = machineEntry;
            (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('[PRISM] Added to MACHINE_DATABASE:', machineData.id);
        }
        // Also add to window.MACHINE_DATABASE
        if (window.MACHINE_DATABASE && window.MACHINE_DATABASE.machines) {
            window.MACHINE_DATABASE.machines[machineData.id] = machineEntry;
            (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('[PRISM] Added to window.MACHINE_DATABASE:', machineData.id);
        }
        // Persist to localStorage
        saveUserAddedMachines();

        return machineData.id;
    }
    function saveUserAddedMachines() {
        try {
            const userMachines = {};
            const db = MACHINE_DATABASE || window.MACHINE_DATABASE;
            if (db && db.machines) {
                Object.entries(db.machines).forEach(([id, machine]) => {
                    if (machine.userAdded) {
                        userMachines[id] = machine;
                    }
                });
            }
            localStorage.setItem('prism_user_added_machines', JSON.stringify(userMachines));
            (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('[PRISM] Saved', Object.keys(userMachines).length, 'user-added machines to localStorage');
        } catch (e) {
            console.warn('[PRISM] Could not save user machines:', e);
        }
    }
    function loadUserAddedMachines() {
        try {
            const saved = localStorage.getItem('prism_user_added_machines');
            if (saved) {
                const userMachines = JSON.parse(saved);
                const count = Object.keys(userMachines).length;
                if (count > 0) {
                    const db = MACHINE_DATABASE || window.MACHINE_DATABASE;
                    if (db && db.machines) {
                        Object.entries(userMachines).forEach(([id, machine]) => {
                            db.machines[id] = machine;
                        });
                        (typeof PRISM_CONSTANTS !== 'undefined' && PRISM_CONSTANTS.DEBUG) && console.log('[PRISM] Loaded', count, 'user-added machines from localStorage');
                    }
                }
            }
        } catch (e) {
            console.warn('[PRISM] Could not load user machines:', e);
        }
    }
