    // View pending machine requests (for development/admin)
    function viewMachineRequests() {
        let requests = [];
        try {
            requests = JSON.parse(localStorage.getItem('machineRequests') || '[]');
        } catch (e) {
            requests = [];
        }
        if (requests.length === 0) {
            console.log('No machine requests pending.');
            return;
        }
        console.log('=== MACHINE REQUESTS ===');
        requests.forEach((req, i) => {
            console.log(`\n[${i + 1}] ${req.make} ${req.model}`);
            console.log(`    Type: ${req.type} | Year: ${req.year}`);
            console.log(`    Specs: ${req.specs}`);
            console.log(`    Email: ${req.email}`);
            console.log(`    Submitted: ${req.timestamp}`);
        });
        console.log('\n========================');

        return requests;
    }
    // Export requests as JSON for development
    function exportMachineRequests() {
        const requests = viewMachineRequests();
        if (requests && requests.length > 0) {
            const blob = new Blob([JSON.stringify(requests, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `machine_requests_${new Date().toISOString().split('T')[0]}.json`;
            a.click();
            URL.revokeObjectURL(url);
        }
    }
    // Save/Load custom machines from localStorage
    function saveCustomMachines() {
        const customMachines = {};
        for (const [id, machine] of Object.entries(MACHINE_DATABASE.machines)) {
            if (machine.isCustom) {
                customMachines[id] = machine;
            }
        }
        try {
            localStorage.setItem('customMachines', JSON.stringify(customMachines));
        } catch (e) {
            console.warn('Could not save custom machines to localStorage');
        }
    }
    function loadCustomMachines() {
        try {
            const saved = localStorage.getItem('customMachines');
            if (saved) {
                const customMachines = JSON.parse(saved);
                for (const [id, machine] of Object.entries(customMachines)) {
                    MACHINE_DATABASE.machines[id] = machine;
                }
            }
        } catch (e) {
            console.warn('Could not load custom machines from localStorage');
        }
    }
    function renderMyMachines() {
        const section = document.getElementById('myMachinesSection');
        const dropdown = document.getElementById('myMachinesDropdown');

        // Don't show in Easy Mode
        if (calculatorMode === 'easy') {
            if (section) section.style.display = 'none';
            return;
        }
        if (myMachines.length === 0) {
            if (section) section.style.display = 'none';
            return;
        }
        if (section) section.style.display = 'block';

        if (!dropdown) return;

        // Get current selection to maintain it
        const currentMachineId = document.getElementById('machineSelect')?.value;
        const currentSpindleId = document.getElementById('spindleSelect')?.value || null;

        // Find if current selection matches a saved machine
        let activeConfigId = '';
        myMachines.forEach(config => {
            if (config.machineId === currentMachineId && config.spindleId === currentSpindleId) {
                activeConfigId = config.id;
            }
        });

        // Build dropdown options
        dropdown.innerHTML = `
            <option value="">Select a saved machine (${myMachines.length})...</option>
            ${myMachines.map(config => {
                const isActive = config.id === activeConfigId;
                return `<option value="${config.id}" ${isActive ? 'selected' : ''}>
                    ${isActive ? '▶ ' : ''}${config.name} (${config.taper}, ${config.rpm.toLocaleString()} RPM)
                </option>`;
            }).join('')}
            <option value="_delete_" style="color: red;">── Delete a machine... ──</option>
        `;
    }
    function loadMyMachineFromDropdown(value) {
        if (!value) return;

        // Handle delete option
        if (value === '_delete_') {
            showDeleteMachineDialog();
            // Reset dropdown
            document.getElementById('myMachinesDropdown')?.value = '';
            return;
        }
        loadMyMachine(value);
    }
    function showDeleteMachineDialog() {
        if (myMachines.length === 0) return;

        const dialog = document.createElement('div');
        dialog.id = 'deleteMachineDialog';
        dialog.style.cssText = `
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: linear-gradient(135deg, #1a2a4a 0%, #0d1a30 100%);
            border: 2px solid rgba(239, 68, 68, 0.5);
            border-radius: 16px;
            padding: 20px;
            z-index: 10000;
            min-width: 300px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
        `;

        dialog.innerHTML = `
            <div style="font-size: 16px; font-weight: 600; color: var(--danger); margin-bottom: 12px;">🗑️ Delete Saved Machine</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 12px;">Select a machine to delete:</div>
            <div style="max-height: 200px; overflow-y: auto; margin-bottom: 16px;">
                ${myMachines.map(config => `
                    <div style="display: flex; align-items: center; justify-content: space-between; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.1); border-radius: 6px; padding: 8px 10px; margin-bottom: 6px;">
                        <div>
                            <div style="font-size: 11px; font-weight: 600; color: var(--text-light);">${config.name}</div>
                            <div style="font-size: 9px; color: var(--text-muted);">${config.taper} • ${config.rpm.toLocaleString()} RPM</div>
                        </div>
                        <button onclick="deleteMyMachine('${config.id}'); document.getElementById('deleteMachineDialog')?.remove();"
                                style="background: rgba(239, 68, 68, 0.2); border: 1px solid var(--danger); color: var(--danger); padding: 4px 10px; border-radius: 4px; cursor: pointer; font-size: 10px;">
                            Delete
                        </button>
                    </div>
                `).join('')}
            </div>
            <button onclick="document.getElementById('deleteMachineDialog')?.remove();"
                    style="width: 100%; background: transparent; border: 1px solid var(--text-muted); color: var(--text-muted); padding: 8px; border-radius: 6px; cursor: pointer;">
                Cancel
            </button>
        `;

        document.body.appendChild(dialog);
    }
    function loadMyMachine(configId) {
        const config = myMachines.find(m => m.id === configId);
        if (!config) return;

        // Switch to Pro mode if needed (saved machines are Pro feature)
        if (calculatorMode === 'easy') {
            setCalculatorMode('pro');
        }
        // Set the machine
        const machineSelect = document.getElementById('machineSelect');

        // First, make sure the machine is visible in the dropdown
        // Clear filters to show all machines
        document.getElementById('machineManufacturer')?.value = '';
        document.getElementById('machineType')?.value = '';
        filterMachines();

        // Now select the machine
        machineSelect.value = config.machineId;
        selectMachine();

        // After selectMachine populates spindle options, set the spindle
        if (config.spindleId) {
            setTimeout(() => {
                document.getElementById('spindleSelect')?.value = config.spindleId;
                selectSpindle();
                renderMyMachines();  // Update active state
            }, 50);
        } else {
            renderMyMachines();  // Update active state
        }
    }
    function deleteMyMachine(configId) {
        myMachines = myMachines.filter(m => m.id !== configId);
        saveMyMachinesToStorage();
        renderMyMachines();
    }
    function clearAllMyMachines() {
        if (confirm('Are you sure you want to remove all saved machines?')) {
            myMachines = [];
            saveMyMachinesToStorage();
            renderMyMachines();
        }
    }
    // WORKHOLDING & STABILITY FUNCTIONS

    let currentStability = 7; // Default to "Good"

    function setStability(value) {
        currentStability = value;

        // Update button styling
        document.querySelectorAll('.stability-btn').forEach(btn => {
            const btnStab = parseInt(btn.dataset.stability);
            if (btnStab === value) {
                btn.classList.add('active');
                btn.style.borderWidth = '2px';
                btn.style.borderColor = 'var(--success)';
            } else {
                btn.classList.remove('active');
                btn.style.borderWidth = '1px';
                btn.style.borderColor = 'var(--border)';
            }
        });

        // Update recommendation
        updateWorkholdingRecommendation();

        // Recalculate
        calculate();
    }
    function updateWorkholdingOptions() {
        // Called when workholding type changes
        updateWorkholdingRecommendation();
        calculate();
    }
    function updateWorkholdingRecommendation() {
        const rec = document.getElementById('workholdingRecommendation');
        if (!rec) return;

        const workholdingType = document.getElementById('workholdingType')?.value || 'vise_std';
        const overhang = parseInt(document.getElementById('partOverhang')?.value) || 0;

        let stabilityText = '';
        let feedAdjust = 100;
        let docNote = '';

        if (currentStability <= 3) {
            stabilityText = '⚠️ <strong>Light setup</strong> - reduce feeds significantly';
            feedAdjust = 60;
            docNote = 'Reduce DOC to 50% or less';
        } else if (currentStability <= 5) {
            stabilityText = '🤔 <strong>Medium setup</strong> - conservative feeds recommended';
            feedAdjust = 80;
            docNote = 'Keep DOC moderate';
        } else if (currentStability <= 7) {
            stabilityText = '👍 <strong>Good setup</strong> - standard feeds OK';
            feedAdjust = 100;
            docNote = 'Standard depths OK';
        } else if (currentStability <= 9) {
            stabilityText = '💪 <strong>Solid setup</strong> - can push feeds';
            feedAdjust = 110;
            docNote = 'Can increase DOC 10-20%';
        } else {
            stabilityText = '🗿 <strong>Rock solid</strong> - maximum aggression';
            feedAdjust = 120;
            docNote = 'Full depth cuts OK';
        }
        // Adjust for overhang
        if (overhang >= 2) {
            feedAdjust -= 15;
            docNote += ' (reduced for overhang)';
        } else if (overhang >= 3) {
            feedAdjust -= 25;
            docNote += ' (significantly reduced for high overhang)';
        }
        const feedColor = feedAdjust >= 100 ? 'var(--success)' : (feedAdjust >= 80 ? 'var(--warning)' : 'var(--danger)');

        rec.innerHTML = `
            <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 6px;">
                <span style="font-size: 14px;">💡</span>
                <span style="font-weight: 700; color: var(--primary); font-size: 11px;">SETUP RECOMMENDATION</span>
            </div>
            <div style="font-size: 10px; color: var(--text-muted);">
                <p style="margin-bottom: 4px;">✓ ${stabilityText}</p>
                <p style="margin-bottom: 4px;">✓ Feed rate adjusted for rigidity: <span style="color: ${feedColor};">${feedAdjust}%</span></p>
                <p>✓ Recommended DOC: ${docNote}</p>
            </div>
        `;
    }
    function getStabilityFactor() {
        // Returns a multiplier for feed rate based on stability
        if (currentStability <= 3) return 0.6;
        if (currentStability <= 5) return 0.8;
        if (currentStability <= 7) return 1.0;
        if (currentStability <= 9) return 1.1;
        return 1.2;
    }
